// ==========================================
// ★ K 의 방 — A등급 직업 갈림길 · 굳건
// ==========================================
// 방패병 · 생존가 · 결계술사 · 외공 수련생 · 광부
// 굳건 — 보는 것 앞에서 버티고, 부르는 소리에 대답하지 않고, 끌고 가는 손에 발을 박는다

// ── 방패병 (shield) · 무력
kJob('shield', 'A', [

{ at:'A', t:'복도 — 방패를 두드리는 것',
  x:`복도가 길다. 불은 뒤에 있다. 맨 앞은 방패다. 늘 그랬다.<br><br>
    방패 앞면에서 소리가 난다. 똑. 똑. 손가락 마디로 두드리는 소리다. 문을 두드리는 박자다.<br>
    불을 앞으로 비춰 봤다. 빈 복도다. 방패 앞에는 아무것도 없다.<br><br>
    방패는 문이 아니다. 저쪽은 문으로 아는 모양이다. 똑. 똑. 열어 달라는 박자다.`,
  o:[
    { l:'① 방패를 내리지 않고 한 걸음씩 나간다.', k:'steady', dc:22, wake:1,
      ok:`방패를 내리지 않았다. 한 걸음 나가면 노크가 한 번. 두 걸음에 두 번.<br><br>열 걸음쯤에서 노크가 멈췄다. 대신 방패 전체가 지그시 눌린다. 손바닥 하나 넓이로. 밀지는 않는다. 대고 있다.<br>팔뚝으로 그 넓이를 느꼈다. 높이도. 이쪽 가슴께다. 키가 작다.<br><br>눈으로 보지 않고 팔로 봤다. 앞면에 닿는 것은 끈을 지나 팔뚝 뼈로 온다. 높이, 무게, 거리. 그걸 읽는 법이 손에 붙었다. 복도 끝에서 눌림이 떨어져 나갔다. 키 작은 것이 비켜 선 자리를 정확히 돌아서 지났다.`,
      ng:`일곱 걸음째에 팔이 저렸다. 반 뼘 내렸다.<br><br>그 반 뼘 위로 손가락 넷이 걸쳤다. 방패 윗가장자리를 쥐고 넘겨다본다. 눈은 안 보였다. 숨이 이쪽 이마에 닿았다. 젖은 천 냄새가 났다.<br><br>방패를 확 올려 쳐 냈다. 손가락은 사라졌다. 가장자리에 물기가 네 줄 남았다. 한동안 팔이 다시 오르지 않았다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-16, spirit:-22 } },
    { l:'② 방패를 기울여 앞면에 불빛을 받아 비춘다.', k:'sense', dc:21,
      ok:`방패를 비스듬히 틀었다. 뒤에서 오는 불빛이 앞면에 맞고 앞으로 튄다. 복도 바닥이 길게 밝아졌다.<br><br>바닥에 발자국이 있다. 맨발이다. 작다. 방패 바로 앞에서 시작해 앞으로 이어진다. 그런데 발가락이 이쪽을 본다. 뒷걸음으로 걸어간 자국이다. 이쪽을 보면서.<br><br>발자국을 밟지 않고 벽 쪽으로 붙어 걸었다. 노크는 복도 끝까지 따라왔다. 발자국 끝에서 멈췄다.`,
      ng:`방패를 틀자 앞면에 얼굴이 비쳤다. 이쪽 얼굴이다. 땀에 젖은 이마, 꽉 다문 입.<br><br>그런데 비친 쪽은 입을 벌리고 있다. 웃는 모양으로. 이쪽 입은 다물려 있다. 손으로 만져 보고 알았다.<br><br>방패를 도로 바로 세웠다. 그 뒤로 앞면을 들여다보지 못했다. 앞면은 앞에 있는 것이다. 이제 거기 무엇이 있는지 안다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-15, spirit:-20 } },
    { l:'③ 열어 준다 — 방패를 옆으로 젖혀 비켜선다.', k:'luck', dc:23,
      doom:{ title:'열어 준 문', what:'방패 틈으로 들어온 손에 끌려갑니다', dc:18, sec:50,
        text:`방패를 옆으로 젖혔다. 문을 열듯이. 노크가 멈췄다.<br><br>찬 것이 방패와 이쪽 사이로 들어왔다. 키가 작다. 이쪽 손목을 잡는다. 손이 작고 젖었다. 쥐는 힘만 어른이다.<br>들어왔으니 이제 같이 나가자는 듯이 당긴다. 복도 앞쪽 어둠으로. 방패가 벽에 긁히며 끌려간다. 팔뚝에 묶인 끈째로.<br><br>뒤에서 불빛이 흔들린다. 동료들이 부르는 소리가 멀어진다. 노크가 다시 난다. 이번엔 이쪽 손등을 두드린다.`,
        dieText:`복도 끝에 방패가 세워져 있었다. 앞면이 이쪽을 본다.<br><br>두드리자 안에서 똑똑, 대답이 왔다. 손가락 마디로. 열어 달라는 박자로.<br>아무도 방패를 젖히지 않았다. 일행은 방패를 두고 돌아서 갔다. 등 뒤에서 노크가 오래 따라왔다.` },
      ok:`방패를 반만 젖혔다. 몸은 벽에 붙이고, 방패로 뒤의 일행을 가렸다.<br><br>찬바람이 방패와 벽 사이를 지나갔다. 키 작은 바람이다. 일행 쪽은 방패가 막았다. 바람은 갈 데가 없어 이쪽 다리 옆을 스쳐 뒤로 빠졌다. 온 길 쪽 어둠으로.<br><br>노크는 그 뒤로 없었다. 문을 열어 주면 들어온다. 들어온 것은 어딘가로 나간다. 그 길만 일행 쪽이 아니면 된다.`,
      win:{ exp:20, dream:3 } }
  ] },

{ at:'A1', t:'방청석 — 방패에 걸린 조명',
  x:`4층 방청석 계단을 내려간다. 등 뒤 발코니에서 조명 하나가 켜졌다. 둥근 빛이 객석을 훑는다.<br><br>
    빛이 방패에 걸렸다. 쇠 앞면이 번쩍인다. 빛이 거기서 멈춘다. 이쪽을 찾은 것이다.<br>
    스피커에서 언니 목소리가 난다. 와, 반짝반짝 친구가 있네. 앞으로 나와 볼까?<br><br>
    빈 의자에서 박수가 터진다. 방석이 하나씩 눌린다. 박자가 맞다.`,
  o:[
    { l:'① 방패를 뒤집어 든다 — 가죽 면을 앞으로.', k:'steady', dc:22, wake:1,
      ok:`방패를 뒤집었다. 손잡이와 가죽 덧댐이 앞을 보고 쇠 면이 가슴에 붙었다. 무게 중심이 낯설다. 손목이 반 바퀴 비틀린다.<br><br>빛이 가죽에 닿았다. 번쩍이지 않는다. 빛이 방패 위를 미끄러지며 머뭇거린다. 박수가 잦아든다. 어? 어디 갔지?<br>빛이 옆으로 흘러갔다. 다른 걸 찾아서.<br><br>막는 면이 꼭 앞일 필요는 없다. 뒤집어 든 방패로도 막힌다. 손이 그 비틀린 무게를 금방 외웠다. 쥐는 법이 하나 늘었다.`,
      ng:`뒤집는 사이 빛이 이쪽 얼굴로 옮겨 왔다. 눈이 하얗게 멀었다.<br><br>찾았다! 박수가 커진다. 계단 양옆 의자에서 손이 뻗어 소맷자락을 잡는다. 장갑 낀 손이다. 손가락이 넷이다.<br><br>방패 모서리로 손목들을 쳐 내며 계단을 거꾸로 올라갔다. 빛이 꺼질 때까지. 소매가 길게 찢겼다. 찢긴 데에 하얀 실밥이 엉겨 붙어 있었다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-24, mind:-16, spirit:-20 } },
    { l:'② 무력을 실어 뛰어올라 조명을 친다.', k:'break', dc:23, cost:{ might:28 },
      ok:`계단을 거슬러 뛰었다. 빛이 따라온다. 방패가 빛을 다 받는다. 눈을 감고 뛰었다.<br><br>발코니 난간 너머에 조명대가 있다. 아무도 잡고 있지 않다. 방패 모서리로 렌즈를 내리쳤다. 유리가 깨지며 빛이 툭 꺼졌다.<br><br>박수가 한 박자 늦게 멈췄다. 스피커가 한참 조용하다가 말한다. 괜찮아요. 다음에 또 와요. 깨진 렌즈 안쪽에 눈동자 그림이 붙어 있었다.`,
      ng:`뛰어오르다 계단 모서리를 놓쳤다. 정강이가 찍혔다.<br><br>빛이 넘어진 이쪽 위에 멈췄다. 박수가 쏟아진다. 방패 쇠가 빛을 받아 뜨겁다. 손바닥이 달라붙는다.<br><br>방패를 놓지 못한 채 엎드려 기었다. 손바닥 살갗이 손잡이에 붙어 조금 떨어져 나갔다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, mind:-14 } }
  ] },

{ at:'A2', t:'교실동 — 물속에서 방패를 쥐는 손',
  x:`교실동 복도에 물이 허리까지 찼다. 방패를 물 밖으로 들고 걸었다. 팔이 금방 무겁다.<br><br>
    방패 아래 가장자리가 물에 잠기는 순간 무엇이 쥐었다. 손가락 다섯이 가장자리를 감싼다. 작고 하얗다. 당긴다. 아래로.<br>
    방패 끈은 팔뚝에 두 번 감아 묶여 있다. 늘 그렇게 맨다. 놓치지 않으려고.<br><br>
    교실 안에서 분필 소리가 난다. 출석부 넘기는 소리.`,
  o:[
    { l:'① 무력을 끌어올려 방패째 끌어 올린다.', k:'steady', dc:23, cost:{ might:30 },
      doom:{ title:'묶은 끈', what:'방패에 묶인 팔째 물 밑으로 끌려갑니다', dc:18, sec:50,
        text:`팔뚝에 힘을 모아 끌어 올렸다. 방패가 한 뼘 올라온다. 손이 하나 더 쥔다. 둘, 셋.<br><br>당기는 힘이 늘었다. 무게가 아니다. 숫자다. 팔뚝에 감긴 끈이 살을 판다. 놓으려 해도 묶여 있다. 놓지 않으려고 묶은 끈이다.<br>무릎이 꺾였다. 물이 가슴, 턱. 물 밑에서 방패 앞면에 작은 손바닥들이 차례로 붙는다. 출석 부르는 소리가 물속에서 웅웅 울린다.`,
        dieText:`한참 뒤에 방패가 떠올랐다. 뒤집혀서. 오목한 안쪽이 천장을 본다.<br><br>끈은 묶인 모양 그대로 둥글게 남아 있다. 팔 하나 들어갈 크기로. 안에 아무것도 없다.<br>교실 안에서 분필 소리가 났다. 출석부 맨 끝 칸에 동그라미가 하나 쳐졌다.` },
      ok:`팔뚝에 힘을 모아 끌어 올렸다. 방패가 물을 가르고 솟는다. 손이 끝까지 쥐고 있다가 물 밖에서 놓았다.<br><br>가장자리에 하얗게 불은 손자국 다섯이 남았다. 마르지 않는다. 문질러도 안 지워진다.<br>물속에서 거품이 하나 올라왔다. 아쉬운 소리를 내며 터졌다.`,
      win:{ exp:20, dream:3 } },
    { l:'② 끈을 풀고 손잡이만 쥔다.', k:'steady', dc:22, wake:1,
      ok:`끈을 풀었다. 팔뚝에서 두 바퀴. 손잡이만 손가락으로 쥐었다.<br><br>당기는 힘이 왔다. 팔꿈치로 받고 어깨로 받고 무릎으로 받았다. 버틸 만큼 버텼다. 더 오면 놓을 생각이었다. 놓을 수 있다는 걸 아니까 끝까지 쥐어졌다.<br>저쪽이 먼저 놓았다. 쥔 쪽이 질 생각이 없으면 당기는 쪽이 지친다.<br><br>묶은 방패는 사람을 같이 데려간다. 쥔 방패는 언제든 놓을 수 있다. 놓을 수 있게 쥐는 법을 손가락이 배웠다. 그 쥠새가 묶은 끈보다 오래 갔다.`,
      ng:`끈을 푸는 사이 방패가 기울었다. 물이 앞면으로 쏟아 들어간다. 손잡이를 놓쳤다.<br><br>방패가 가라앉는다. 손을 뻗어 물속을 휘저었다. 손가락 끝에 방패 가장자리가 닿았다. 그리고 다른 손가락들이.<br><br>방패를 겨우 건졌다. 손등에 작은 이빨 자국이 줄지어 있다. 아프지 않았다. 그게 더 나빴다.`,
      win:{ exp:22, dream:3, spirit:6 }, lose:{ hp:-26, spirit:-22 } }
  ] },

{ at:'A', t:'쉬는 자리 — 방패 뒤의 자리',
  x:`쉬는 자리에서 방패를 벽에 비스듬히 세웠다. 늘 그렇게 둔다. 방패와 벽 사이에 사람 하나 웅크릴 틈이 생긴다.<br><br>
    방패병은 그 틈을 제일 다친 동료에게 내준다. 등 뒤가 막힌 자리라 잠이 온다.<br>
    오늘은 아무도 거기 안 들어갔다. 그런데 방패 뒤에서 숨소리가 난다. 무릎을 끌어안은 사람의 숨소리.<br><br>
    머릿수를 셌다. 다 여기 있다. 다 이쪽에서 숨을 쉰다.`,
  o:[
    { l:'① 방패에 등을 대고 앉아 밤을 난다.', k:'steady', dc:22,
      ok:`방패 앞에 앉아 등을 댔다. 방패를 사이에 두고 등과 등이 붙었다. 저쪽 등도 떨린다.<br><br>밤새 숨소리를 들었다. 이쪽이 깨어 있는 동안 저쪽은 나오지 않았다. 지키는 사람이 등을 대고 있는 동안은 안 나온다. 방패 뒤는 그런 자리다.<br><br>새벽에 방패를 들었다. 틈 바닥이 말라 있다. 사람 하나 크기로. 둘레만 젖었다.`,
      ng:`등을 댔다. 졸았다. 한순간이다.<br><br>어깨를 누가 두드린다. 방패 너머에서 손이 넘어왔다. 이쪽 어깨에 얹혀 톡톡. 자리를 바꾸자는 것이다.<br><br>벌떡 일어섰다. 손은 없다. 어깨에 젖은 손자국이 남았다. 일행 중 아무도 그 손 크기가 아니다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-16, spirit:-24 } },
    { l:'② 방패를 한 번에 걷어 낸다.', k:'gaze', dc:23,
      ok:`방패를 한 번에 걷었다. 불을 들이댔다.<br><br>빈 틈이다. 벽에 손톱으로 그은 줄이 있다. 셀 수 없이 많다. 다섯 개마다 한 묶음이다. 기다린 날을 센 것이다.<br>맨 마지막 묶음이 넷에서 멈췄다.<br><br>방패를 다시는 그 벽에 세우지 않았다. 다섯째 줄을 긋게 하지 않으려고.`,
      ng:`걷어 내자 숨소리가 멎었다. 빈 틈이다.<br><br>그런데 방패 안쪽 가죽이 따뜻하다. 방금까지 누가 등을 댔던 것처럼. 가죽에 머리카락이 한 올 붙어 있다. 길고 젖었다.<br><br>그 밤 내내 방패를 들고 있었다. 내려놓을 데가 없었다. 어디에 세워도 뒤가 생긴다.`,
      win:{ exp:16, dream:3 }, lose:{ mind:-18, spirit:-20 } },
    { l:'③ 다친 동료를 그 자리에 앉히고 앞에 선다.', k:'bond', dc:22,
      ok:`발목을 접질린 동료를 방패 뒤에 앉혔다. 숨소리가 있는 그 자리에. 그리고 방패 앞에 섰다.<br><br>동료가 작게 말한다. 옆에 누가 있다고. 따뜻하다고. 무섭지 않다고. 이쪽은 앞만 봤다.<br>새벽에 동료가 일어났다. 부었던 발목이 가라앉아 있다. 누가 밤새 감싸 쥐고 있었던 것처럼.<br><br>방패 뒤는 지키는 자리다. 지키는 것이 꼭 이쪽만은 아니다.`,
      ng:`동료를 앉히고 앞에 섰다. 한참 뒤 동료가 말을 멈췄다.<br><br>돌아보니 동료가 웃고 있다. 눈을 감은 채로. 옆에 기대고 있다. 아무것도 없는 쪽으로.<br><br>흔들어 깨웠다. 동료는 아무것도 기억하지 못한다. 손목에 손가락 자국이 넷 있다. 꼭 쥔 자국이다.`,
      win:{ exp:18, dream:2, hp:8 }, lose:{ hp:-22, spirit:-22 } }
  ] },

{ at:'A', t:'계단 — 불이 옮을 때마다',
  x:`내려가는 계단이 길다. 방패가 맨 앞이다. 불은 뒤에서 흔들린다.<br><br>
    불빛이 흔들릴 때마다 아래 계단참에 누가 서 있다. 빛이 닿을 때는 없다. 빛이 옮겨 가는 사이에만 있다. 서 있는 자리가 매번 한 칸씩 가깝다.<br>
    맨 앞에 선 사람은 앞을 보는 사람이다. 맨 앞이 눈을 떼면 뒤가 다 무너진다.<br><br>
    지금은 앞을 볼수록 그것이 가까워진다.`,
  o:[
    { l:'① 방패를 눈높이로 올리고 발만 보고 걷는다.', k:'steady', dc:22, wake:1,
      ok:`방패를 눈높이까지 올렸다. 앞이 막혔다. 아래 가장자리 밑으로 발과 계단 두 칸만 보인다. 그것만 보고 걸었다.<br><br>셋째 칸쯤에서 방패 앞에 무엇이 섰다. 가장자리 아래로 발이 보인다. 맨발이다. 발가락이 이쪽을 향해 있다. 그 발 옆을 비켜 디뎠다. 다음 칸, 다음 칸.<br>발은 따라오지 않았다. 마주 보지 않는 것과는 마주 설 수 없다.<br><br>앞을 보는 일이 꼭 눈의 일이 아니었다. 발끝과 방패 가장자리 사이 한 뼘. 그 안에서 다 읽힌다. 계단을 다 내려와서도 방패를 한참 내리지 않았다. 내릴 필요가 없었다.`,
      ng:`방패를 올렸는데 발밑이 안 보인다. 계단 하나를 헛디뎠다.<br><br>무릎이 꺾이며 방패가 내려갔다. 코앞에 얼굴이 있었다. 눈이 감겨 있다. 감긴 눈꺼풀 밑으로 눈알이 움직인다. 이쪽을 따라서.<br><br>방패로 밀어 젖혔다. 아무것도 밀리지 않았다. 그 계단을 내려가는 내내 무릎이 떨렸다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-24, mind:-18 } },
    { l:'② 뒤에 대고 불을 흔들지 말라고 이른다.', k:'fix', dc:21,
      ok:`뒤에 대고 낮게 일렀다. 불을 아래 계단참에 고정하라고. 흔들지 말라고.<br><br>불빛이 계단참에 붙었다. 빛 안에는 아무것도 없다. 빛이 닿는 자리로만 디뎠다. 빛이 멈춰 있으니 그것도 설 틈이 없다.<br><br>계단참 벽에 그림 하나가 기대 세워져 있다. 계단 그림이다. 중간에 사람들이 서 있다. 방패를 든 사람이 맨 앞이다. 그 앞에 하나 더 있다.`,
      ng:`불을 멈추라 일렀다. 불 든 동료가 손을 떤다. 빛이 떨린다. 떨릴 때마다 사이가 생긴다.<br><br>사이마다 그것이 한 칸씩 왔다. 다섯 번 떨렸다. 다섯 칸. 이제 방패 바로 앞이다.<br><br>앞면에 무게가 실렸다. 밀지 않는다. 기대고 있다. 계단 끝까지 그 무게를 밀고 내려갔다. 팔이 한동안 안 올라갔다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-22, spirit:-20 } }
  ] },

{ at:'A1', t:'의상실 — 안아 주는 뭉치',
  x:`의상실 옷걸이 사이에서 뭉치 탈이 걸어 나왔다. 갈색 털이 통로를 꽉 채운다. 단추 눈 두 개. 좀약 냄새.<br><br>
    뭉치가 팔을 벌린다. 천천히. 안아 주려는 몸짓이다. 일행 쪽으로.<br>
    방패를 든 사람은 사이에 선다. 안는 것과 일행 사이에. 늘 그 자리다.<br><br>
    뭉치 팔이 방패를 감는다. 방패째 이쪽을 안는다. 털 속에서 갈비뼈 같은 것이 딱딱하게 닿는다.`,
  o:[
    { l:'① 방패를 가슴에 붙이고 안긴 채 버틴다.', k:'steady', dc:23,
      doom:{ title:'뭉치의 품', what:'뭉치에게 방패째 안겨 실려 갑니다', dc:18, sec:50,
        text:`방패를 가슴에 붙였다. 뭉치가 조인다. 방패가 숨 쉴 틈을 만든다. 그 틈으로 숨을 쉬었다.<br><br>발이 떴다. 뭉치가 이쪽을 안고 돌아선다. 옷걸이 사이로 걷는다. 좀약 냄새가 짙어진다. 털 속이 따뜻하다. 너무 따뜻하다.<br>방패와 가슴 사이의 틈이 조금씩 좁아진다. 뭉치는 서두르지 않는다. 안은 것은 서두르지 않는다. 의상실 안쪽, 탈 머리들이 얹힌 선반 쪽으로.`,
        dieText:`옷걸이 맨 끝에 새 탈이 한 벌 걸렸다. 갈색 털이다. 몸통이 조금 두껍다.<br><br>가슴께가 네모나게 불룩하다. 방패 하나 들어갈 만큼.<br>탈 머리 선반에서 단추 눈 하나가 굴러 떨어졌다. 아무도 줍지 않았다.` },
      ok:`방패를 가슴에 붙이고 버텼다. 뭉치가 조인다. 방패가 그 힘을 받아 낸다. 팔이 저리고 갈비가 울린다. 숨 쉴 틈은 남았다.<br><br>한참 조이던 뭉치가 팔을 풀었다. 안아도 안기지 않는 것을 안을 까닭이 없다. 털 덮인 머리가 기우뚱 기운다. 서운한 모양으로.<br><br>뭉치가 옷걸이 사이로 돌아갔다. 방패 앞면에 갈색 털이 한 줌 박혀 있다. 뽑으니 털 끝에 실이 매달려 나온다. 바늘이 꿰인 채로.`,
      win:{ exp:20, dream:3 } },
    { l:'② 무력을 실어 방패 가장자리로 팔꿈치 이음새를 끊는다.', k:'break', dc:22, cost:{ might:26 },
      ok:`방패를 비틀어 가장자리를 세웠다. 뭉치 팔꿈치 접히는 데, 털이 얇은 이음새에 대고 무력을 실어 밀었다.<br><br>실밥 터지는 소리가 났다. 팔 하나가 축 늘어졌다. 안에서 솜이 아니라 젖은 신문지가 쏟아진다. 날짜가 다 같다.<br><br>풀린 품에서 빠져나왔다. 뭉치는 남은 한 팔로 허공을 계속 안았다. 이쪽이 아직 안겨 있다는 듯이.`,
      ng:`가장자리를 세우는데 뭉치 팔이 먼저 조였다. 방패가 가슴뼈를 눌렀다. 뭔가 금이 갔다.<br><br>숨이 안 쉬어진다. 털이 입과 코를 막는다. 일행이 뒤에서 털을 뜯어냈다. 겨우 빠져나왔다.<br><br>숨 쉴 때마다 가슴께가 결린다. 방패 안쪽에 갈비뼈 모양 자국이 눌려 있다. 이쪽 것이다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-30, mind:-14 } }
  ] },

{ at:'A2', t:'기숙사 — 문간에 선 방패',
  x:`밤 아홉 시 종이 울렸다. 호실 점호다. 물 헤치는 발소리가 복도 끝에서 다가온다. 열쇠 소리가 같이 온다.<br><br>
    일행은 빈 호실 하나에 들어갔다. 문이 없다. 떨어져 나갔다. 문틀만 남았다.<br>
    방패를 문틀에 대면 문 하나 넓이가 된다. 딱 맞는다. 원래 문이었던 것처럼.<br><br>
    발소리가 옆 호실 앞에서 멈췄다. <span style="color:#8fb3bf;">"408호. 열두 명. 이상 없음."</span> 이 방은 409호다.`,
  o:[
    { l:'① 방패로 문틀을 막고 등으로 받친다.', k:'steady', dc:22, wake:1,
      ok:`방패를 문틀에 대고 등으로 받쳤다. 발로 문지방을 걸었다. 숨을 죽였다.<br><br>발소리가 409호 앞에 섰다. 앞면을 똑똑 두드린다. 문을 두드리는 것이다. 문은 대답하지 않는다. 열쇠가 방패 가장자리를 더듬는다. 열쇠 구멍을 찾는다. 없다.<br><span style="color:#8fb3bf;">"409호. 문 잠김. 다음."</span> 발소리가 멀어졌다.<br><br>방패를 들고 있던 게 아니다. 문틀에 끼워 세우고 등을 기둥 삼았다. 방패를 벽에 붙이면 벽의 일부가 된다. 몸도 같이. 그렇게 서는 법이 등에 들어왔다.`,
      ng:`방패를 댔는데 문틀이 한 뼘 넓다. 옆으로 틈이 생겼다.<br><br>두드리는 소리가 멈추고 그 틈으로 물에 불은 손가락이 들어왔다. 하나씩 센다. 일행 어깨를 하나씩 짚는다. 이쪽 어깨에서 멈췄다. 오래 누른다.<br><span style="color:#8fb3bf;">"409호. 다섯 명. 하나 더."</span><br><br>손이 빠져나갔다. 하나 더라는 말이 무슨 뜻인지 다들 알았다. 어깨에 손자국이 파랗게 남았다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-18, spirit:-24 } },
    { l:'② 방패를 침대에 눕히고 일행을 침대 밑에 숨긴다.', k:'hide', dc:23,
      ok:`방패를 침대 위에 눕혀 두고 일행을 침대 밑 물속에 엎드리게 했다. 물이 무릎 깊이다. 코만 내놓았다.<br><br>문간에 누가 섰다. 열쇠 소리. 방을 둘러보는 숨소리. 침대 위 방패를 한참 내려다본다. 그 위에 손을 얹는다. 머릿수를 세는 손이다. 방패를 하나로 셌다.<br><span style="color:#8fb3bf;">"409호. 한 명. 취침."</span><br><br>발소리가 멀어졌다. 침대 위 방패에 이불이 덮여 있었다. 누가 덮어 준 것이다.`,
      ng:`엎드리는데 방패가 침대에서 미끄러져 물에 떨어졌다. 쇳소리가 났다.<br><br>문간의 숨소리가 멈췄다. 물을 헤치고 들어온다. 침대 밑을 들여다본다. 거꾸로 숙인 얼굴이 수면에 비친다. 젖은 머리카락이 물에 닿는다.<br><br>숨을 참았다. 오래. 폐가 탔다. 얼굴이 물러갈 때까지. 물러간 뒤에도 일어서지 못했다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-24, mind:-18 } }
  ] },

{ at:'A', t:'좁은 틈 — 방패가 안 지나는 길',
  x:`길이 틈 하나로 좁아졌다. 사람은 옆으로 서면 지난다. 방패는 안 지난다.<br><br>
    동료들이 먼저 지났다. 틈 너머에서 부른다. 괜찮다고. 넓다고. 목소리가 다 맞다. 다 동료 목소리다.<br>
    방패를 든 사람은 방패를 두고 가는 법을 모른다. 두고 간 적이 없다.<br><br>
    너머의 목소리 중 하나가 조금 늦게 온다. 다른 목소리를 따라 하는 것처럼.`,
  o:[
    { l:'① 방패를 세워 두고 맨몸으로 지난다.', k:'evade', dc:22,
      doom:{ title:'맨몸', what:'틈 안에서 손목을 잡혀 벽 속으로 끌려갑니다', dc:18, sec:45,
        text:`방패를 틈 앞에 세워 두고 옆으로 섰다. 가슴과 등이 돌벽에 닿는다. 한 걸음, 두 걸음.<br><br>틈 가운데서 손목을 무엇이 잡았다. 앞에서가 아니다. 벽 속에서다. 돌 틈에서 손가락이 나와 손목을 감는다. 늦게 오던 목소리가 귀 옆에서 말한다. 괜찮아, 넓어.<br>당긴다. 옆으로. 틈은 앞뒤로만 나 있는데 옆으로 당긴다. 돌이 어깨를 깎는다. 방패는 틈 밖에 세워져 있다. 손이 거기까지 닿지 않는다.`,
        dieText:`틈 너머에서 동료들이 기다렸다. 한참.<br><br>돌아가 보니 틈 앞에 방패가 그대로 서 있다. 틈 안에는 아무도 없다. 돌벽에 어깨 높이로 긁힌 자국이 옆으로 길게 났다. 들어갈 데가 없는 쪽으로.<br>늦게 오던 목소리가 그 뒤로 하나 더 늘었다.` },
      ok:`방패 손잡이에 끈을 묶어 그 끝을 손목에 감았다. 방패는 틈 앞에 세우고 몸만 넣었다. 늦게 오던 목소리를 등지고, 숨을 내쉬어 가슴을 줄였다.<br><br>벽 속에서 손가락이 손목을 스쳤다. 잡기 전에 빠져나왔다. 너머에 닿았다. 동료가 넷이다. 이쪽까지 다섯. 들어간 수대로다.<br><br>끈을 당겼다. 방패가 모로 서며 틈을 따라 끌려왔다. 가장자리에 하얀 손자국이 하나 묻어 있다. 방패도 붙잡혔다가 놓여난 것이다.`,
      win:{ exp:18, dream:2 } },
    { l:'② 방패를 모로 세워 앞에 밀고 들어간다.', k:'steady', dc:22, wake:1,
      ok:`방패를 모로 세웠다. 가장자리가 앞을 보게. 그대로 틈에 밀어 넣고 그 뒤에 몸을 붙였다. 방패가 틈을 열고 몸이 따라간다.<br><br>틈 가운데서 앞면 쪽 벽에서 손이 나와 더듬었다. 쇠다. 손은 쇠를 쥐다가 미끄러졌다. 반대편 벽은 이쪽 등이 막았다. 손이 들어올 자리가 없다.<br><br>방패는 앞을 막는 것인 줄 알았다. 모로 세우면 옆을 막는다. 몸과 방패로 좁은 길 양쪽을 다 막을 수 있다. 너머에 닿았을 때 동료 목소리가 하나 줄어 있었다. 늦게 오던 것이.`,
      ng:`모로 세웠는데 방패가 틈 중간에 끼었다. 앞으로도 뒤로도 안 간다. 이쪽도 같이 끼었다.<br><br>너머에서 목소리들이 부른다. 괜찮다고. 늦게 오던 목소리가 제일 가깝다. 방패 바로 너머다. 방패를 사이에 두고 숨이 닿는다.<br><br>무릎으로 돌을 차 가며 뒤로 빠졌다. 정강이 살갗이 벗겨졌다. 결국 방패를 먼저 밀어 넣고 몸이 따라갔다. 다 지나서 보니 앞면이 긁혀 있다. 손톱 넓이로.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-28, mind:-16 } },
    { l:'③ 무력을 실어 틈 가장자리를 부숴 넓힌다.', k:'break', dc:23, cost:{ might:25 },
      ok:`방패 모서리를 틈 가장자리 돌에 대고 무력을 실어 쳤다. 돌이 무르다. 젖은 석회다. 세 번에 한 뼘이 떨어졌다.<br><br>떨어진 돌 안쪽이 비어 있다. 벽 속에 굴이 있다. 팔 하나 넓이로 옆으로 길게. 그 안에서 늦게 오던 목소리가 뚝 끊겼다.<br><br>넓힌 틈으로 방패째 지났다. 벽 속 굴은 진흙으로 막고 돌을 쌓았다. 쌓는 동안 안에서 아무 소리도 안 났다. 숨죽이는 소리만.`,
      ng:`쳤는데 돌이 쪼개지며 이쪽으로 튀었다. 광대뼈가 찢어졌다.<br><br>가장자리가 무너지고 그 안에서 팔 하나가 쑥 나왔다. 하얗고 길다. 이쪽 얼굴 앞을 휘젓다가 도로 들어갔다.<br><br>피를 닦으며 방패를 모로 세워 겨우 밀고 지났다. 틈 안쪽은 끝까지 쳐다보지 않았다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-30, spirit:-18 } }
  ] },

{ at:'A1', t:'무대 옆 — 다음 순서',
  x:`무대 옆 어두운 자리. 무대 감독이 헤드셋을 쓰고 서 있다. 얼굴이 없다. 헤드셋만 있다.<br><br>
    무대 감독이 손가락을 접는다. 다섯, 넷, 셋. 다음 순서를 내보내는 손짓이다. 손가락 끝이 이쪽을 가리킨다.<br>
    등 뒤에서 손바닥들이 등을 민다. 부드럽게. 무대 쪽 빛으로.<br><br>
    방패를 든 사람은 밀리는 것을 안다. 밀리는 데서 발을 박는 것도 안다.`,
  o:[
    { l:'① 돌아서서 미는 쪽에 방패를 대고 발을 박는다.', k:'steady', dc:22, wake:1,
      ok:`무대를 등지고 돌아섰다. 미는 손바닥들 쪽으로 방패를 댔다. 발을 어깨 너비로 벌려 박았다.<br><br>손바닥들이 방패를 민다. 여럿이다. 미는 힘이 방패에서 팔뚝으로, 어깨에서 허리로, 허리에서 발바닥으로 내려간다. 그리고 바닥으로 빠진다. 바닥 판자가 끽 운다.<br>무대 감독 손가락이 다 접혔다. 음악이 나온다. 아무도 나가지 않았다. 음악이 혼자 흐르다 멈췄다.<br><br>받은 힘을 쥐고 있지 않아도 된다. 발밑으로 흘려 보내면 된다. 그 길을 몸이 찾아냈다. 무대 감독이 손가락을 다시 편다. 다섯. 이번엔 다른 쪽을 가리킨다.`,
      ng:`돌아서는 사이 한 발이 무대 경계를 넘었다. 빛 안이다.<br><br>객석에서 박수가 터진다. 빛을 받은 발목이 뜨겁다. 발이 저절로 한 걸음 더 나가려 한다. 무대 쪽으로. 박자에 맞춰.<br><br>동료가 허리띠를 잡아 끌어당겼다. 빛 밖으로 넘어졌다. 발목 살갗이 벌겋게 익어 있다. 신발 밑창에 반짝이 가루가 묻었다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-24, spirit:-22 } },
    { l:'② 무력을 실어 세는 손을 방패로 쳐 낸다.', k:'break', dc:23, cost:{ might:27 },
      ok:`방패를 휘둘러 무대 감독의 손을 쳤다. 손가락 둘이 펴진 채 굳었다.<br><br>둘. 세다 만 숫자다. 무대 감독이 고개를 갸웃한다. 헤드셋에서 지직거리는 소리가 난다. 다음 순서가 나가지 못한다. 셈이 끝나지 않았다.<br><br>등을 밀던 손바닥들이 머뭇거리다 떨어졌다. 둘에서 멈춘 손을 뒤로하고 무대 뒤로 빠졌다. 지나가는 동안 헤드셋에서 계속 속삭였다. 둘. 둘. 둘.`,
      ng:`쳤는데 손이 방패 가장자리를 낚아챘다. 손가락 힘이 사람 것이 아니다.<br><br>방패째 빛 쪽으로 끌린다. 버티다가 가장자리에 손가락이 끼었다. 손톱 하나가 들렸다.<br><br>끝내 방패를 비틀어 빼냈다. 무대 감독은 남은 손가락을 계속 접었다. 하나. 이쪽은 그 하나가 끝나기 전에 뛰었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, mind:-16 } }
  ] },

{ at:'A2', t:'식당동 — 문을 미는 물',
  x:`식당동은 물이 가슴까지다. 조리실로 가는 문 너머에서 물이 민다. 문틈으로 물이 혀처럼 새어 나온다.<br><br>
    열면 물살이다. 누가 문을 붙들고 있어야 나머지가 지난다.<br>
    문틈으로 새는 물에 식판이 하나 떠내려왔다. 밥이 담겨 있다. 아직 따뜻하다.<br><br>
    문 너머 물살 속에서 손뼉 소리가 난다. 배식 시간을 알리는 박자다.`,
  o:[
    { l:'① 문을 열고 방패로 물살을 쪼개며 붙든다.', k:'steady', dc:23,
      doom:{ title:'배식 시간', what:'문 너머 물살에 실려 조리실 안으로 끌려갑니다', dc:18, sec:45,
        text:`문을 열었다. 물이 쏟아진다. 방패를 비스듬히 대 물살을 갈랐다. 동료들이 방패 그늘로 하나씩 지난다.<br><br>마지막 동료가 지난 순간 물살 속에서 손이 방패 뒤로 들어왔다. 이쪽 허리띠를 쥔다. 손뼉 소리가 바로 옆에서 난다. 배식 시간이다.<br>당긴다. 물살을 거슬러, 조리실 쪽으로. 발이 바닥 타일을 놓친다. 방패가 물살을 받아 돛처럼 부푼다. 이쪽을 더 빨리 데려간다.`,
        dieText:`조리실 배식대 위에 식판이 하나 늘었다. 따뜻한 밥이 담겼다.<br><br>식판 옆에 방패가 기대 세워졌다. 쟁반처럼. 앞면에 수저 한 벌이 가지런히 놓였다.<br>물속에서 손뼉 소리가 났다. 다 같이, 잘 먹겠습니다.` },
      ok:`문을 열었다. 물이 쏟아진다. 방패를 비스듬히 대 물살을 갈랐다. 쪼개진 물이 양옆으로 빠진다. 동료들이 방패 그늘로 하나씩 지났다.<br><br>마지막에 이쪽이 몸을 돌려 방패를 등에 지고 문을 닫았다. 물살이 방패를 두드린다. 문이 닫히자 손뼉 소리가 뚝 그쳤다.<br><br>떠내려온 식판은 그대로 두었다. 따뜻한 밥은 누가 먹으라고 차린 것이 아니다. 누구를 부르려고 차린 것이다.`,
      win:{ exp:20, dream:3 } },
    { l:'② 문을 두고 배식대 위로 돌아갈 길을 찾는다.', k:'sense', dc:22,
      ok:`문을 열지 않았다. 식당 천장을 따라 눈으로 길을 찾았다. 배식대 위 환풍구가 조리실로 이어진다.<br><br>방패를 배식대에 걸치고 디딤판으로 삼았다. 한 사람씩 올려 보냈다. 마지막에 방패를 끌어 올렸다.<br><br>환풍구 아래로 조리실이 보였다. 물속에 조리복 입은 것들이 줄지어 서서 문 쪽을 보고 있다. 문을 열고 들어올 사람을.`,
      ng:`배식대에 방패를 걸치는데 방패가 미끄러졌다. 물에 빠진 쇳소리가 식당 전체를 울렸다.<br><br>조리실 문이 저절로 열렸다. 물살이 쏟아져 일행을 쓸었다. 다들 의자 다리를 붙잡고 버텼다.<br><br>물살이 잦아들자 손뼉 소리도 멎었다. 이쪽 허리띠가 끊겨 있었다. 칼로 자른 자리가 아니다. 이빨로 끊은 자리다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-28, mind:-16 } }
  ] },

{ at:'A', t:'쉬는 자리 — 방패에 비친 등',
  x:`쉬는 동안 방패를 무릎에 세웠다. 쇠 앞면이 닦여 있다. 불빛이 비친다. 뒤에서 자는 동료들도 비친다.<br><br>
    비친 쪽에서 무엇이 움직인다. 제일 어두운 자리에 누운 동료 머리맡에 누가 웅크렸다. 들여다보고 있다.<br>
    방패병은 돌아보지 않는다. 돌아보는 사이 앞이 빈다.<br><br>
    방패 속 웅크린 것이 고개를 천천히 숙인다. 동료 얼굴 쪽으로.`,
  o:[
    { l:'① 방패를 기울여 비친 것을 계속 지켜본다.', k:'gaze', dc:23, wake:1,
      ok:`돌아보지 않았다. 방패를 손가락 하나만큼 기울였다. 웅크린 것이 방패 한가운데에 오게.<br><br>그것이 고개를 숙이다 멈췄다. 보이는 것을 안다. 숙이던 고개가 천천히 이쪽을 향한다. 방패 속에서. 눈이 마주쳤다. 이쪽은 방패만 봤다. 그것도 방패만 봤다.<br>한참 그렇게 있다가 그것이 일어나 뒤로 물러났다. 어둠 쪽으로.<br><br>앞을 막고 있는 동안 뒤를 보는 법. 앞면은 앞을 막고, 같은 앞면이 뒤를 비춘다. 기울기 하나로 등 뒤 어디든 볼 수 있다. 방패를 쥔 손목이 그 각도들을 하나씩 외웠다.`,
      ng:`기울이는데 손이 떨렸다. 비친 것이 흔들린다. 흔들리는 사이 사라졌다.<br><br>어디 갔는지 찾느라 방패를 이리저리 틀었다. 어느 각도에도 없다. 그러다 방패 한복판에 얼굴 하나가 비쳤다. 이쪽 어깨 바로 뒤다.<br><br>돌아봤다. 아무도 없다. 다시 방패를 봤다. 아무도 없다. 그 밤 내내 목덜미에 숨이 닿았다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-18, spirit:-26 } },
    { l:'② 일어나 그 동료 머리맡에 가서 선다.', k:'bond', dc:22,
      ok:`방패를 들고 일어나 제일 어두운 자리로 갔다. 동료 머리맡에 섰다. 방패를 어둠 쪽으로 세웠다.<br><br>아무것도 없다. 동료는 잔다. 숨이 고르다. 방패를 세운 채 그 옆에 앉았다.<br>방패 앞면에서 무엇이 한 번 긁었다. 손톱으로 천천히. 그리고 그쳤다.<br><br>아침에 동료가 말했다. 꿈에 누가 들여다보다가 쇠 냄새를 맡고 갔다고.`,
      ng:`일어서는 소리에 비친 것이 사라졌다. 머리맡에 가 섰다. 아무것도 없다.<br><br>돌아와 앉으려는데 방금 이쪽 자리에 누가 앉아 있다. 방패를 무릎에 세우고. 이쪽 등을 하고.<br><br>눈을 비볐다. 빈자리다. 바닥이 따뜻하다. 그 밤 자리를 옮겨 잤다. 원래 자리가 밤새 따뜻했다.`,
      win:{ exp:16, dream:2, mind:6 }, lose:{ hp:-22, spirit:-24 } }
  ] },

{ at:'A', t:'내려가는 길 — 무거워지는 방패',
  x:`걸을수록 방패가 무거워진다. 한 걸음마다 조금씩.<br><br>
    방패병은 제 방패 무게를 안다. 손바닥이 안다. 지금 무게는 그보다 아이 하나만큼 더 무겁다.<br>
    윗가장자리가 조금 기운다. 무엇이 걸터앉은 쪽으로. 끈이 운다.<br><br>
    귓가에서 아이 숨소리가 난다. 방패 위에서 내려다보는 높이다.`,
  o:[
    { l:'① 무게를 재고 기울여 미끄러뜨린다.', k:'steady', dc:23, wake:1,
      ok:`걸음을 멈추지 않고 손바닥으로 무게를 쟀다. 왼쪽 위다. 엉덩이 하나 넓이. 다리는 앞으로 늘어졌다. 앞면에 발뒤꿈치가 톡톡 닿는다.<br><br>방패를 오른쪽으로 아주 조금 기울였다. 아주 조금씩, 계단 하나에 한 손가락씩. 걸터앉은 것이 모르게. 열 계단쯤에서 무게가 스르르 미끄러져 내려갔다. 작은 발이 바닥에 닿는 소리가 났다.<br><br>무게로 읽는다. 어디에 얼마나, 어떤 모양으로. 손바닥이 그걸 저울처럼 해냈다. 들고 있는 것의 무게가 바뀌면 바뀐 만큼을 안다. 내려간 것이 뒤에서 한참 서 있다가 다른 쪽으로 갔다.`,
      ng:`기울이는데 무게가 따라 옮겨 앉았다. 반대쪽으로. 또 기울이면 또 옮긴다.<br><br>장난이다. 걸터앉은 것이 웃는다. 귀 바로 옆에서. 젖은 손이 이쪽 머리카락을 쥔다. 넘어지지 않으려고.<br><br>계단 끝까지 그 무게를 이고 갔다. 다 내려와서야 손이 놓였다. 머리카락이 한 줌 빠졌다. 목덜미가 젖었다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-22, mind:-16, spirit:-18 } },
    { l:'② 방패를 크게 흔들어 털어 낸다.', k:'break', dc:22,
      ok:`방패를 크게 한 번 휘둘렀다. 무게가 날아갔다. 벽에 무엇이 부딪혔다. 가볍다.<br><br>울음소리가 났다. 아이 울음이다. 어둠 저쪽으로 달려가며 운다. 작은 발소리가 멀어진다.<br><br>방패가 원래 무게로 돌아왔다. 아니다. 조금 가볍다. 앞면 가죽 덧댐 한쪽이 뜯겨 나갔다. 가져간 것이다.`,
      ng:`휘둘렀는데 무게가 안 떨어졌다. 대신 이쪽이 휘청했다. 벽에 어깨를 박았다.<br><br>걸터앉은 것이 두 팔로 이쪽 목을 감았다. 꼭 매달린다. 떨어지기 싫은 모양이다. 숨이 막힌다.<br><br>동료들이 와서 떼어 냈다. 아무것도 안 보이는데 다들 손이 차가웠다고 했다. 목에 가는 팔 자국이 둘렀다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-26, mind:-14 } },
    { l:'③ 방패 위를 손으로 쓸어 본다.', k:'sense', dc:22,
      ok:`걸으며 왼손을 들어 방패 윗가장자리를 쓸었다. 아무것도 안 닿는다. 그런데 가장자리가 젖어 있다.<br><br>손끝에 머리카락이 감겼다. 길고 가늘다. 끝에 리본이 묶여 있다. 빨간 고무줄이다.<br>그걸 풀어 바닥에 내려놓자 방패가 가벼워졌다.<br><br>무거운 것은 걸터앉은 게 아니었다. 그걸 매달고 다니게 한 것이었다. 고무줄은 뒤에서 누가 주웠다. 작은 손으로.`,
      ng:`쓸었는데 손이 잡혔다. 작은 손이 이쪽 손가락을 쥔다. 놀자는 듯이.<br><br>손을 뺄 수가 없다. 걸을 때마다 손이 방패 위로 끌려 올라간다. 팔이 저리다.<br><br>계단 끝에서 손이 놓였다. 손가락 끝이 하얗게 얼어 있다. 감각이 반나절 돌아오지 않았다.`,
      win:{ exp:16, dream:2, spirit:6 }, lose:{ hp:-22, spirit:-20 } }
  ] },

{ at:'A1', t:'놀이 세트 — 공 바다 위의 방패',
  x:`6층 놀이 세트. 색색의 공이 허리 높이로 깔린 공 바다다. 건너편에 다음 계단이 있다.<br><br>
    공 사이가 움직인다. 공 몇 개가 쑥 가라앉았다가 다른 자리에서 떠오른다. 밑에 무엇이 다닌다.<br>
    벽에 그림판이 붙어 있다. 공 바다에서는 손을 꼭 잡아요. 안 그러면 공 친구가 데려가요.<br><br>
    방패는 넓다. 위에 서면 무게가 퍼진다.`,
  o:[
    { l:'① 방패를 깔고 디디며 한 사람씩 건네준다.', k:'fix', dc:22,
      ok:`방패를 공 위에 눕혔다. 무게가 퍼져 안 빠진다. 그 위에 서서 다음 사람 손을 잡아 건넸다. 방패를 앞으로 밀고 다시 섰다.<br><br>밑에서 무엇이 방패 바닥을 쓸었다. 쇠다. 잡을 데가 없다. 공을 헤치고 다른 데로 갔다.<br><br>건너편에 닿아 방패를 들자 밑에 공이 하나 붙어 있었다. 손바닥 모양으로 우그러졌다. 쥐었다가 놓친 모양으로.`,
      ng:`방패를 눕혔는데 공이 밀려나며 방패가 기울었다. 한쪽이 쑥 가라앉는다.<br><br>균형을 잡느라 손을 놓쳤다. 뒤에 오던 동료 손이다. 공이 동료 가슴까지 올라온다. 공 사이에서 손이 동료 발목을 잡았다.<br><br>둘이 같이 끌어냈다. 동료 발목에 손가락 자국이 다섯. 아이 손 크기다. 동료는 끝까지 이쪽 손을 다시 잡으려 하지 않았다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, mind:-18 } },
    { l:'② 방패를 앞에 세우고 공을 헤치며 앞장선다.', k:'steady', dc:23,
      doom:{ title:'공 친구', what:'공 바다 밑으로 끌려 가라앉습니다', dc:18, sec:45,
        text:`방패를 세워 공을 헤치며 걸었다. 공이 방패 양옆으로 갈라진다. 뒤에서 일행이 그 길로 따라온다.<br><br>한가운데서 발목이 잡혔다. 둘 다. 공 밑에서 작은 손들이 끈다. 아래로. 방패를 세운 자세 그대로 몸이 꺼진다. 허리, 가슴. 공이 턱까지 차오른다.<br>공 사이로 숨을 쉰다. 공이 입술에 닿는다. 말랑하다. 밑에서 누가 웃는다. 손을 꼭 잡아야지.`,
        dieText:`공 바다가 잠잠해졌다. 색색의 공이 고르게 덮였다.<br><br>한가운데에 방패 윗가장자리가 손가락 한 마디만큼 나와 있다. 세운 자세 그대로.<br>벽 그림판 아래 이름표 칸에 새 이름이 붙었다. 공 친구 — 하나.` },
      ok:`방패를 세워 공을 헤쳤다. 공이 양옆으로 갈라진다. 일행이 그 길로 붙어 따라온다. 서로 손을 꼭 잡고.<br><br>한가운데서 발목에 무엇이 닿았다. 잡기 전에 방패 아래 가장자리를 공 밑으로 내리찍었다. 닿던 것이 움찔 물러났다.<br><br>건너편에 닿았다. 돌아보니 갈라졌던 길이 천천히 메워진다. 메워지는 자리에서 공 몇 개가 동시에 가라앉았다. 아쉬운 듯이.`,
      win:{ exp:20, dream:3 } }
  ] },

{ at:'A2', t:'체육관 — 방패에 담은 숨',
  x:`체육관 천장 철골 밑에 공기가 한 줄로 고였다. 머리만 내밀면 숨이 쉬어진다. 철골을 따라가면 탈의실이다.<br><br>
    중간에 공기가 끊긴다. 열 걸음쯤. 그 자리 물속에 손 하나가 떠 있다. 손바닥이 위를 본다.<br>
    방패는 오목하다. 뒤집어 물에 누르면 그 안에 공기가 남는다. 들고 다니는 천장이 된다.<br><br>
    동료 하나가 숨이 짧다. 열 걸음을 못 참는다.`,
  o:[
    { l:'① 방패를 뒤집어 공기를 가두고 동료와 함께 건넌다.', k:'fix', dc:22,
      ok:`방패를 뒤집어 철골 밑 공기에 대고 천천히 물로 눌렀다. 오목한 안쪽에 공기가 한 줌 남았다. 얼굴 둘이 들어갈 만큼.<br><br>숨이 짧은 동료와 방패 밑에 얼굴을 넣고 걸었다. 방패 안에서 숨소리가 둘. 손이 떠 있는 자리를 지날 때 손이 방패를 두드렸다. 똑. 똑. 안에 누가 있느냐는 듯이.<br><br>대답하지 않았다. 열 걸음 끝에서 철골 밑 공기에 머리를 내밀었다. 방패 안쪽 가죽에 물방울로 손바닥 자국이 맺혀 있었다. 안쪽에서 찍힌 것이다.`,
      ng:`누르는 사이 방패가 기울어 공기가 한쪽으로 빠져나갔다. 큰 거품이 철골을 따라 굴러간다.<br><br>남은 공기는 한 사람 몫도 안 된다. 동료에게 밀어 주고 숨을 참았다. 다섯 걸음째에 떠 있던 손이 이쪽 손목을 잡았다. 손바닥을 위로 한 채, 꼭.<br><br>억지로 떼어 냈다. 철골 밑에 머리를 내밀었을 때 눈앞이 하얬다. 손목에 물에 불은 손자국이 오래 남았다.`,
      win:{ exp:18, dream:2, hp:6 }, lose:{ hp:-30, spirit:-20 } },
    { l:'② 떠 있는 손 쪽을 방패로 막고 동료들을 먼저 보낸다.', k:'steady', dc:23,
      ok:`숨을 들이켜고 물에 들어가 떠 있는 손 앞에 방패를 세웠다. 손과 일행 사이를 막았다. 일행이 그 옆을 한 사람씩 지나갔다.<br><br>손이 방패를 짚었다. 쇠를 쓰다듬는다. 넘어오지는 않는다. 앞에 무엇이 서 있으면 손은 그걸 먼저 만진다.<br><br>마지막 사람이 지나고 물러났다. 숨이 거의 바닥이다. 철골 밑에 머리를 내밀자 공기가 폐를 찢으며 들어왔다. 손은 그대로 떠 있었다. 손바닥을 위로 하고, 다음 사람을 기다리며.`,
      ng:`방패를 세우는 사이 손이 방패 아래로 돌아 들어왔다. 이쪽 발목을 쥔다.<br><br>당긴다. 아래로, 체육관 바닥 쪽으로. 숨이 새어 나간다. 방패 모서리로 손을 찍었다. 물속이라 느리다. 세 번째에 손이 놓였다.<br><br>철골 밑에 머리를 내밀고 한참 기침을 했다. 물을 토했다. 발목에 쥔 자국이 다섯 줄로 파랗다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-32, mind:-16 } }
  ] },

{ at:'A', t:'복도 — 손이 나오는 벽',
  x:`복도 한쪽 벽에 손자국이 빼곡하다. 어른 손, 아이 손. 안쪽에서 민 모양으로 벽이 조금씩 부풀었다.<br><br>
    지나가면 벽에서 손이 나온다. 잡을 만한 것을 잡는다. 아까 앞서 지나간 짐승 하나가 반쯤 벽에 들어가 있다.<br>
    반대쪽 벽은 매끈하다. 아무 자국도 없다.<br><br>
    방패는 하나다. 막을 수 있는 쪽도 하나다.`,
  o:[
    { l:'① 방패를 손자국 쪽 벽에 대고 일행을 반대쪽으로 붙여 걷는다.', k:'steady', dc:22,
      ok:`손자국 쪽 벽에 방패를 대고 옆걸음으로 걸었다. 일행은 이쪽 등 뒤로, 매끈한 벽에 붙여 세웠다.<br><br>벽에서 손이 나와 방패를 더듬는다. 하나, 둘, 열. 쇠를 긁는 소리가 끊이지 않는다. 방패를 벽에서 한 치도 떼지 않았다. 떼면 그 틈으로 들어온다.<br><br>복도 끝에서 돌아봤다. 매끈하던 벽에 손자국이 하나 찍혀 있었다. 일행이 기댄 높이에. 저쪽 벽에서 오는 것은 막았다. 이쪽 벽도 벽이었다.`,
      ng:`옆걸음으로 걷다가 발이 엉켰다. 방패가 벽에서 한 뼘 떨어졌다.<br><br>그 틈으로 팔 하나가 들어와 이쪽 허리를 감았다. 벽 쪽으로 당긴다. 등이 벽에 닿는다. 벽이 무르다. 진흙처럼 받아들인다.<br><br>동료들이 팔을 붙잡고 끌어냈다. 등 쪽 옷이 벽에 붙어 찢겨 나갔다. 벽에 이쪽 등 모양이 오목하게 남았다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-30, spirit:-22 } },
    { l:'② 반쯤 들어간 짐승을 방패로 밀어 넣어 틈을 막는다.', k:'break', dc:22,
      ok:`반쯤 벽에 박힌 짐승을 방패로 밀었다. 짐승이 벽으로 쑥 들어간다. 벽이 받아 삼킨다. 부풀었던 자리가 꿀꺽 오므라든다.<br><br>그 순간 벽 전체에서 손이 나오던 소리가 멎었다. 먹는 동안은 잡지 않는다.<br><br>그 틈에 다 지났다. 방패 앞면에 짐승 털이 몇 가닥 붙어 있었다. 털 끝이 벽 속으로 당겨지며 뽑혀 나갔다.`,
      ng:`밀었는데 짐승이 아직 살아 있었다. 몸부림치며 방패를 찼다. 방패가 벽에 닿았다.<br><br>벽에서 손이 나와 방패를 쥐었다. 짐승과 방패를 같이 쥔다. 놓지 않는다. 방패를 비틀어 겨우 빼냈다. 손목이 꺾였다.<br><br>짐승은 다 들어갔다. 마지막에 나온 소리가 사람 목소리 같았다.`,
      win:{ exp:16, dream:2, item:'짐승 고기' }, lose:{ hp:-26, mind:-16 } }
  ] },

{ at:'A1', t:'스튜디오 — 빨간 불이 켜진 카메라',
  x:`7층 스튜디오. 카메라 세 대 중 하나에 빨간 불이 켜졌다. 지금 나가는 화면이다.<br><br>
    렌즈가 천천히 돈다. 얼굴을 찾는다. 앞서 렌즈에 잡힌 의자 위 인형들은 다 같은 얼굴로 웃고 있다.<br>
    모니터에 지금 화면이 보인다. 빈 무대. 렌즈가 돌수록 일행이 선 쪽이 화면 가장자리로 들어온다.<br><br>
    렌즈는 얼굴을 원한다. 방패에는 얼굴이 없다.`,
  o:[
    { l:'① 렌즈 앞에 방패를 세우고 마주 선다.', k:'steady', dc:23, wake:1,
      ok:`렌즈 앞으로 걸어가 방패를 세웠다. 렌즈 바로 앞, 한 뼘 거리에. 그 뒤에 몸을 숨겼다.<br><br>모니터에 방패 앞면이 꽉 찼다. 긁힌 자국, 우그러진 자리, 이빨 자국, 손톱 자국. 렌즈가 초점을 맞추려고 웅웅거린다. 얼굴이 아니다. 맞출 데가 없다.<br>빨간 불이 깜빡이다 꺼졌다. 다른 카메라로 넘어가려 할 때마다 방패를 그쪽으로 옮겼다.<br><br>방패 앞면이 얼굴 노릇을 했다. 받아 낸 것들이 다 거기 새겨져 있다. 무엇이 쳐다보든 그걸 보여 주면 된다. 방패를 앞에 두고 서는 일이 그렇게 하나 더 늘었다.`,
      ng:`방패를 세우는데 렌즈가 먼저 돌았다. 가장자리 너머로 이쪽 반쪽 얼굴을 잡았다.<br><br>모니터에 반쪽 얼굴이 나간다. 입꼬리가 저절로 올라간다. 내릴 수가 없다. 화면 속 반쪽은 웃고, 화면 밖 반쪽은 굳었다.<br><br>방패로 렌즈를 내리찍었다. 화면이 꺼졌다. 입꼬리는 한참 뒤에야 내려왔다. 볼이 아직 당긴다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-20, spirit:-26 } },
    { l:'② 일행을 방패 뒤에 한 줄로 세워 카메라 앞을 지난다.', k:'bond', dc:22,
      ok:`일행을 방패 뒤에 한 줄로 세웠다. 각자 앞사람 등에 얼굴을 묻게 했다. 방패가 맨 앞에서 렌즈를 막는다.<br><br>렌즈가 따라 돈다. 방패만 잡힌다. 가장자리 너머는 등과 뒤통수뿐이다. 얼굴이 하나도 없다.<br><br>스튜디오를 다 지났을 때 모니터에 자막이 떴다. 오늘의 친구 — 없음. 객석 스피커에서 실망한 소리가 길게 났다.`,
      ng:`줄을 세웠는데 맨 끝 동료가 고개를 들었다. 어디까지 왔는지 보려고.<br><br>빨간 불이 그쪽으로 홱 돌았다. 모니터에 동료 얼굴이 꽉 찼다. 동료가 웃는다. 웃고 싶지 않은 얼굴로.<br><br>방패를 들고 뛰어가 렌즈를 막았다. 동료는 한참 웃음을 멈추지 못했다. 멈춘 뒤에는 울었다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-18, spirit:-24 } }
  ] },

{ at:'A2', t:'강당 — 맨 끝 줄의 빈자리',
  x:`강당 관람석 위쪽 마른 줄에 일행이 앉았다. 아래로 물속에 의자가 줄지어 있다. 의자마다 명찰이 떠 있다.<br><br>
    무대 쪽에서 출석을 부른다. 이름 하나에 물속에서 대답 하나. 네. 거품 하나.<br>
    마른 줄 맨 끝 의자 하나만 젖어 있다. 그 위 허공에 명찰이 하나 떠 있다. 이름이 없다. 아직.<br><br>
    방패를 든 사람이 그 빈자리 옆에 앉았다. 일행과 빈자리 사이에.`,
  o:[
    { l:'① 빈자리 위에 방패를 눕혀 막아 둔다.', k:'steady', dc:22,
      ok:`방패를 빈 의자 위에 눕혔다. 의자를 덮었다. 그 위에 손을 얹고 눌렀다.<br><br>출석이 마른 줄까지 올라왔다. 이쪽 줄 이름들이 차례로 불린다. 동료 이름이다. 대답하지 말라고 눈짓했다. 아무도 대답하지 않았다. 빈자리 차례가 왔다. 이름 없는 차례.<br>방패 밑에서 무엇이 대답하려 했다. 들썩인다. 손으로 눌렀다.<br><br>무대에서 말했다. <span style="color:#8fb3bf;">"결석."</span> 떠 있던 명찰이 물속으로 가라앉았다.`,
      ng:`방패를 눕혔는데 의자가 방패를 밀어 올린다. 밑에서. 방패가 들썩인다.<br><br>손으로 누르는 사이 출석이 이쪽 이름을 불렀다. 입이 저절로 열렸다. 네, 하고 대답하기 직전에 동료가 이쪽 입을 막았다.<br><br>손바닥 밑에서 혀가 굳었다. 떠 있던 명찰에 글자가 반쯤 새겨졌다가 멈췄다. 이쪽 이름의 첫 글자다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-20, spirit:-24 } },
    { l:'② 떠 있는 명찰을 낚아 방패 안쪽에 숨긴다.', k:'luck', dc:23,
      ok:`허공의 명찰을 낚아채 방패 안쪽 가죽 덧댐 사이에 끼웠다. 방패를 앞면이 무대를 보게 세웠다.<br><br>출석이 마른 줄까지 왔다. 빈자리 차례에 무대 쪽 목소리가 멈칫했다. 명찰이 없다. 부를 이름이 없다. 다음 차례로 넘어갔다.<br><br>강당을 나와서 명찰을 꺼냈다. 이름 칸이 비었다. 뒷면에 바늘로 꿰맨 자국이 있다. 다섯 땀. 이쪽 일행 수다.`,
      ng:`낚아채는데 명찰이 손바닥에 달라붙었다. 차고 젖었다. 떼어지지 않는다.<br><br>출석이 빈자리 차례에 왔다. 명찰을 쥔 이쪽 손이 저절로 들렸다. 대답하는 손이다. 무대 쪽에서 이쪽을 본다. 물속의 머리들이 일제히 위를 본다.<br><br>손을 방패로 찍어 내렸다. 명찰이 떨어져 물에 가라앉았다. 손바닥 살갗이 반쯤 같이 갔다.`,
      win:{ exp:16, dream:3 }, lose:{ hp:-24, spirit:-22 } }
  ] },

{ at:'A', t:'불침번 — 감기는 눈',
  x:`불침번이다. 방패를 앞에 세우고 섰다. 앉으면 잠이 온다. 서 있으면 덜 온다.<br><br>
    어둠 저편에 누가 서 있다. 눈을 깜빡일 때마다 한 걸음씩 가깝다. 뜨고 있을 때는 안 움직인다.<br>
    눈이 마른다. 따갑다. 언젠가는 감긴다.<br><br>
    지금은 열 걸음 거리다. 아까는 스무 걸음이었다.`,
  o:[
    { l:'① 방패에 이마를 대고 한쪽 눈씩 감는다.', k:'steady', dc:22, wake:1,
      ok:`방패 윗가장자리에 이마를 댔다. 쇠가 차다. 잠이 물러난다.<br><br>오른눈을 감았다. 왼눈은 뜬 채로. 그것이 안 움직인다. 왼눈이 마르면 왼눈을 감고 오른눈을 떴다. 번갈아서. 한쪽은 언제나 열려 있다.<br>새벽까지 그것이 한 걸음도 오지 못했다. 열 걸음 거리에 선 채로 동이 텄다. 빛이 닿자 그 자리에 젖은 발자국만 남았다.<br><br>지키는 일을 몸이 쪼개서 하는 법을 배웠다. 반은 쉬고 반은 지킨다. 쇠에 이마를 대면 반쪽이 깨어 있다. 그 자세로 밤을 버티는 일이 처음으로 힘들지 않았다.`,
      ng:`이마를 댔다. 쇠가 차다. 그런데 차가움에 익었다. 익으니 잠이 왔다.<br><br>두 눈이 같이 감겼다. 한순간이다. 떴을 때 방패 앞면에 얼굴이 닿아 있었다. 반대편에서. 쇠 하나를 사이에 두고 이마와 이마가 닿았다.<br><br>뒤로 넘어졌다. 동료들이 깼다. 방패 앞면에 이마 자국이 하나 찍혀 있다. 이쪽보다 조금 높은 데에.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-22, mind:-18, spirit:-20 } },
    { l:'② 동료를 깨워 번을 나눈다.', k:'bond', dc:21,
      ok:`옆 동료를 흔들어 깨웠다. 손짓으로 저쪽을 가리켰다. 동료가 눈을 뜨고 그쪽을 본다.<br><br>둘이 번갈아 깜빡였다. 이쪽이 감을 때 동료가 뜨고, 동료가 감을 때 이쪽이 뜬다. 그것은 한 걸음도 오지 못했다.<br><br>새벽에 동료가 말했다. 저쪽에 하나가 아니라 둘이었다고. 이쪽에서 본 것과 동료가 본 것이 다른 자리에 서 있었다고.`,
      ng:`동료를 깨웠다. 동료가 일어나며 크게 하품을 했다. 눈이 감겼다. 이쪽도 따라 깜빡였다.<br><br>둘이 같이 감은 한순간. 떴을 때 그것이 방패 바로 앞에 서 있었다. 키가 크다. 고개를 숙여 방패 위로 이쪽을 내려다본다.<br><br>동이 틀 때까지 둘 다 한 번도 눈을 감지 못했다. 눈이 핏발로 붉다. 그것은 해가 뜨자 방패 앞에서 젖은 자국이 됐다.`,
      win:{ exp:16, dream:2, mind:6 }, lose:{ mind:-20, spirit:-22 } }
  ] },

{ at:'A', t:'쉬는 자리 — 덮어 둔 구멍',
  x:`쉬는 자리 바닥 한가운데에 구멍이 있다. 사람 하나 빠질 넓이다. 밑이 안 보인다.<br><br>
    구멍에서 바람이 올라온다. 숨처럼 들고 난다. 들 때는 이쪽 옷자락이 구멍 쪽으로 끌린다.<br>
    구멍 가장자리에 손톱자국이 있다. 밑에서 위로 긁은 자국이다. 기어오르려고. 아니면 끌려 내려가지 않으려고.<br><br>
    다른 쉴 데는 없다. 방패는 구멍보다 조금 넓다.`,
  o:[
    { l:'① 방패로 구멍을 덮고 그 위에 앉는다.', k:'steady', dc:23,
      ok:`방패를 구멍 위에 엎어 덮었다. 그 위에 앉았다. 무게로 눌렀다.<br><br>한밤에 밑에서 두드렸다. 쿵. 쿵. 방패가 들썩인다. 앉은 엉덩이로 받았다. 두드림이 멎으면 긁는 소리. 손톱이 쇠를 긁는다. 그것도 멎으면 숨소리.<br>밤새 그 위에 앉아 있었다. 동료들은 그 옆에서 잤다.<br><br>아침에 방패를 들었다. 구멍 안쪽 벽에 새 손톱자국이 있다. 위로 올라오다 방패에 막힌 자리에서 멈췄다.`,
      ng:`덮고 앉았다. 한밤에 밑에서 친 한 번이 너무 셌다. 방패째 엉덩이가 들렸다.<br><br>들린 틈으로 손이 나와 이쪽 발목을 잡았다. 구멍 쪽으로 당긴다. 방패 가장자리를 붙잡고 버텼다. 손가락이 쇠에 베였다.<br><br>동료들이 깨서 같이 당겼다. 손이 놓였다. 발목에 쥔 자국이 검다. 방패는 그 뒤로 내내 구멍 위에 엎어 두었다. 떠날 때까지 아무도 자지 못했다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-28, mind:-16 } },
    { l:'② 불을 들고 구멍 안을 들여다본다.', k:'gaze', dc:22,
      ok:`엎드려 불을 구멍 위로 내밀었다. 한 길쯤 아래에 무엇이 반짝인다. 눈이 아니다. 쇠다.<br><br>방패다. 누가 먼저 이 구멍을 덮었다. 그 방패가 떨어져 저 아래 걸렸다. 그 밑은 더 깊다.<br><br>불을 거뒀다. 먼저 덮은 사람이 왜 떨어졌는지 생각했다. 밑에서 민 게 아니다. 방패 위에서 잠이 들었다. 이쪽은 자지 않기로 했다.`,
      ng:`들여다봤다. 아래에 얼굴이 있다. 위를 보고 있다. 아주 깊은 데서. 그런데 점점 가까워진다.<br><br>올라오는 것이다. 벽을 짚고, 천천히. 불빛에 손톱이 반짝인다.<br><br>뒤로 물러나 방패로 덮었다. 그 위에 일행 짐을 다 올렸다. 밤새 밑에서 긁었다. 들여다본 눈이 오래 따끔거렸다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-18, spirit:-24 } },
    { l:'③ 돌을 굴려 와 막고 그 앞에 방패를 세운다.', k:'fix', dc:22,
      ok:`벽 쪽 큰 돌을 굴려 와 구멍을 덮었다. 다 안 덮인다. 틈은 방패로 막았다. 방패 앞에 앉아 등을 돌에 붙였다.<br><br>밤중에 돌이 한 번 흔들렸다. 등으로 받았다. 돌은 무겁다. 방패는 단단하다. 둘 다 이쪽보다 버틴다. 이쪽은 그 둘을 붙잡고만 있으면 된다.<br><br>아침에 보니 돌 둘레의 흙이 긁혀 있다. 안쪽에서. 돌이 넘어가지 않을 만큼만.`,
      ng:`굴리다가 돌이 구멍 가장자리를 쳤다. 가장자리가 무너졌다. 구멍이 넓어졌다.<br><br>무너진 흙과 같이 이쪽 한 발이 빠졌다. 허벅지까지. 밑에서 차가운 숨이 다리를 감는다. 무언가가 신발을 벗기려 한다.<br><br>방패를 가로로 걸쳐 짚고 기어 나왔다. 신발 한 짝을 구멍이 가졌다. 밤새 밑에서 신발을 두드리는 소리가 났다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, spirit:-20 } }
  ] },

{ at:'A', t:'나가는 길 — 안쪽에서 찍힌 자국',
  x:`나갈 길이 가깝다. 쉬는 틈에 방패를 무릎에 올렸다.<br><br>
    앞면에 자국이 빼곡하다. 손톱, 이빨, 손바닥, 이마. 다 앞에서 받은 것이다.<br>
    방패병은 자국을 세지 않는다. 그런데 오늘은 이상한 자국이 있다. 뒷면 가죽 밑 쇠가 바깥으로 볼록하다. 안쪽에서 친 자국이다.<br><br>
    방패 안쪽은 이쪽 몸이 있는 쪽이다.`,
  o:[
    { l:'① 볼록한 자국을 센다.', k:'sense', dc:21,
      ok:`손끝으로 짚어 셌다. 일곱이다. 다 작다. 주먹 하나 크기도 안 된다.<br><br>언제 생겼는지 기억을 더듬었다. 밀릴 때마다다. 이쪽이 밀려 뒤로 기울 때, 등 뒤에서 누가 방패를 받쳐 밀었다. 작은 주먹으로. 일곱 번.<br><br>등 뒤를 돌아봤다. 아무도 없다. 다만 방패 안쪽 가죽에 아이 손바닥 크기로 닳은 자리가 있다. 오래 짚은 자리다.`,
      ng:`세는데 볼록한 자국이 는다. 손끝 밑에서 하나가 새로 솟았다. 지금.<br><br>방패를 떨어뜨렸다. 쇳소리가 났다. 안쪽 가죽이 들썩인다. 가죽 밑에서 작은 주먹이 친다. 한 번 더.<br><br>방패를 뒤집어 엎어 놓았다. 그 위에 앉아 있었다. 출발할 때까지 엉덩이 밑에서 톡톡 쳤다. 놀자는 박자로.`,
      win:{ exp:16, dream:3 }, lose:{ mind:-18, spirit:-26 } },
    { l:'② 그대로 든다 — 앞뒤를 다 받는 것으로.', k:'steady', dc:22, wake:1,
      ok:`세지 않았다. 볼록한 자국 위에 손바닥을 얹었다가 손잡이를 쥐었다.<br><br>방패는 앞을 받는 것이다. 그런데 뒤에서도 받았다. 앞에서 오는 것은 앞면이, 이쪽을 받쳐 주던 것은 안쪽이. 둘 다 이 쇠에 남았다.<br>들어 보니 무게가 다르다. 앞뒤가 고르게 무겁다. 손이 그걸 바로 맞췄다.<br><br>막는 것만 방패가 아니다. 받쳐 주는 것도 받는다. 앞에서 미는 힘과 뒤에서 받치는 힘 사이에 서는 법. 그 사이가 제일 안 밀리는 자리다. 몸이 그 자리를 처음으로 알았다.`,
      ng:`그대로 들었는데 안쪽이 따뜻하다. 볼록한 자국마다 체온이 남았다.<br><br>걷는 내내 등 뒤에 누가 붙어 있었다. 이쪽이 멈추면 멈추고, 걸으면 걸었다. 돌아보면 없다.<br><br>나가는 문 앞에서 그것이 이쪽 옷자락을 잡아당겼다. 가지 말라는 힘으로. 뿌리치는 데 오래 걸렸다. 옷자락에 작은 손자국이 젖어 남았다.`,
      win:{ exp:22, dream:4 }, lose:{ mind:-16, spirit:-24 } }
  ] }

]);

// ── 생존가 (survivor) · 자원 없음
kJob('survivor', 'A', [

{ at:'A', t:'들어가는 길 — 하나 더 많은 몫',
  x:`첫 밤에 먹을 것을 나눴다. 말린 것을 손바닥 위에 펴고 머릿수대로 몫을 냈다.<br><br>
    생존가는 몫을 낼 때 머릿수를 두 번 센다. 한 번은 눈으로, 한 번은 손으로.<br>
    눈으로 센 것은 다섯이다. 손이 낸 몫은 여섯이다. 다시 나눴다. 또 여섯이다.<br><br>
    여섯째 몫이 어둠 쪽 가장자리에 놓여 있다. 누가 그쪽으로 밀어 둔 것처럼.`,
  o:[
    { l:'① 여섯째 몫을 어둠 쪽에 그대로 둔다.', k:'luck', dc:22,
      ok:`손대지 않았다. 몫 다섯만 거두고 여섯째는 어둠 가장자리에 두었다.<br><br>밤중에 씹는 소리가 났다. 아주 작게. 오래 씹는다. 아껴 먹는 소리다. 이쪽도 그렇게 먹는다.<br>아침에 그 자리에 몫이 없다. 대신 병이 하나 서 있다. 물이 찼다. 맑다.<br><br>마셔도 되는지 한참 봤다. 병 바닥에 모래가 가라앉아 있다. 거른 물이다. 누가 이쪽 방식대로 걸렀다.`,
      ng:`두었다. 아침에 여섯째 몫은 그대로다.<br><br>대신 이쪽 몫 다섯 중 하나가 없다. 제일 작은 동료의 것이다. 그 동료는 밤새 아무것도 못 먹었다고 한다. 배가 고프다고. 그런데 입가에 부스러기가 묻어 있다.<br><br>동료는 그걸 모른다. 이쪽도 말하지 못했다. 그 동료가 여섯째인지 다섯째인지 그날 하루 내내 셌다.`,
      win:{ exp:16, dream:2, item:'맑은 물' }, lose:{ mind:-16, spirit:-22 } },
    { l:'② 머릿수대로만 다시 나눈다 — 눈으로 센 수로.', k:'steady', dc:22, wake:1,
      ok:`손이 낸 셈을 버렸다. 눈으로 센 다섯대로 다시 나눴다. 말린 것을 다섯으로 쪼개고 남은 부스러기까지 다섯으로 나눴다. 하나도 남기지 않았다.<br><br>밤중에 누가 몫이 있던 자리를 더듬었다. 아무것도 없다. 오래 더듬다가 물러갔다. 줄 몫이 없으면 앉을 자리도 없다.<br><br>나누는 셈이 지키는 셈이다. 몫을 내는 손이 그날 처음으로 망설이지 않았다. 머릿수를 정하는 것은 이쪽이다. 그 셈을 손에 쥐고 있으면 남는 자리가 생기지 않는다.`,
      ng:`다섯으로 쪼갰다. 그런데 쪼갠 조각을 세면 또 여섯이다. 손이 하는 일을 눈이 못 따라간다.<br><br>밤새 몫을 무릎에 올려 두고 지켰다. 한 번 졸았다. 깨니 무릎이 젖어 있다. 누가 머리를 기대고 있었다. 젖은 머리를.<br><br>몫은 다섯이 남았다. 머릿수도 다섯이다. 맞는데 맞는 것 같지가 않았다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-18, spirit:-20 } },
    { l:'③ 밤새 몫 곁에서 지켜본다.', k:'sense', dc:22,
      ok:`몫을 펴 둔 채 등을 벽에 대고 앉아 눈을 반만 감았다.<br><br>한밤에 여섯째 몫이 움직였다. 조금씩 어둠 쪽으로. 끌려가는 게 아니다. 바닥이 기운다. 그 자리만 아주 조금 기울어 있다. 아래에 빈 데가 있다.<br><br>몫을 집어 다섯 몫 사이에 섞었다. 그리고 그 자리를 짐으로 눌러 두었다. 아침까지 짐 밑에서 바닥이 숨을 쉬었다.`,
      ng:`지켜보는데 몫이 안 움직인다. 아무 일도 없다. 그런데 이쪽 손이 움직인다.<br><br>정신을 차리니 여섯째 몫을 집어 어둠 쪽으로 내밀고 있었다. 팔을 쭉 뻗어서. 손바닥 위에 올려서. 받으라는 듯이.<br><br>어둠 속에서 차가운 손가락이 이쪽 손바닥을 스쳤다. 팔을 거두었다. 몫은 없어졌다. 손바닥에 젖은 지문이 남았다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-22, spirit:-24 } }
  ] },

{ at:'A1', t:'방청석 — 착한 어린이 간식',
  x:`방청석 의자마다 간식 상자가 놓였다. 리본이 묶였다. 상자에 적혀 있다. 착한 어린이 간식.<br><br>
    사흘째 제대로 못 먹었다. 배가 조용하다. 조용한 허기가 제일 위험하다.<br>
    남이 차려 준 것은 먹지 않는다. 이런 데서는 더더욱. 차려 준 쪽이 무엇을 원하는지 모를 때는.<br><br>
    상자에서 단 냄새가 난다. 진짜 꿀 냄새다.`,
  o:[
    { l:'① 손대지 않는다 — 허기를 쥐고 지난다.', k:'steady', dc:22, wake:1,
      ok:`상자를 보지 않고 지났다. 냄새가 따라온다. 침이 고인다. 삼키지 않고 뱉었다.<br><br>허기가 운다. 울게 두었다. 울음을 세었다. 한 번 울면 열 걸음. 그렇게 객석 끝까지 갔다.<br>뒤에서 리본 풀리는 소리가 났다. 누가 대신 열었다. 이쪽 일행은 아니다. 객석에 앉은 것들이다. 박수가 났다.<br><br>배고픔은 참는 게 아니었다. 쥐고 있는 것이다. 숨을 쥐듯이. 놓아야 할 때까지 쥐고 있는다. 그 쥠이 손에 익었다. 허기가 이쪽을 끌고 가지 않고 이쪽이 허기를 끌고 걸었다.`,
      ng:`지나가는데 상자 하나가 저절로 열렸다. 꿀 냄새가 확 끼쳤다.<br><br>손이 먼저 갔다. 하나 집어 입에 넣었다. 달다. 아주 달다. 이 사이에 뭔가 단단한 것이 씹혔다.<br><br>뱉었다. 작은 이다. 아이 젖니다. 뿌리까지 있다. 일행이 등을 두드려 줄 때까지 토했다. 입안에 단맛이 사흘 갔다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-22, mind:-18, spirit:-20 } },
    { l:'② 상자 하나를 뜯어 속을 들여다본다.', k:'gaze', dc:22,
      ok:`리본을 칼로 끊고 상자를 칼끝으로 열었다. 손은 대지 않았다.<br><br>사탕 포장지마다 웃는 해가 그려졌다. 포장지 안은 비었다. 상자 바닥에 꿀 단지가 하나 따로 있다. 봉인이 그대로다. 공장 도장이 찍혔다. 이건 진짜다. 누가 사 놓고 못 나눠 준 것이다.<br><br>단지만 꺼냈다. 상자는 리본을 다시 묶어 의자에 놓았다. 상자가 비었다는 걸 객석이 모르게.`,
      ng:`열었다. 사탕마다 포장지 위 해가 이쪽을 본다. 눈이 움직인다.<br><br>상자를 덮으려는데 의자 방석이 눌렸다. 누가 앉았다. 상자 주인이다. 손이 이쪽 손목을 톡 친다. 남의 걸 왜 열어. 아이 목소리다.<br><br>사과하듯 상자를 내려놓고 물러섰다. 손목에 작은 손가락 자국이 빨갛게 남았다. 가렵다. 긁으면 단 냄새가 난다.`,
      win:{ exp:18, dream:2, item:'꿀 한 줌' }, lose:{ mind:-16, spirit:-22 } }
  ] },

{ at:'A2', t:'조리실 — 물속 저장고',
  x:`조리실은 물이 가슴까지다. 저장고 문이 물속에 반쯤 잠겼다. 안이 깊다. 계단으로 내려가는 저장고다.<br><br>
    저장고라면 안다. 통조림, 소금, 마른 곡식. 오래 가는 것은 저장고 맨 아래 있다.<br>
    벽 맨 위 선반에 소금 단지가 하나 물 밖에 걸려 있다. 손이 닿는다.<br><br>
    물속 저장고 계단에서 깡통 부딪는 소리가 난다. 누가 아래서 선반을 정리한다.`,
  o:[
    { l:'① 맨 위 선반의 소금 단지만 꺼낸다.', k:'fix', dc:22,
      ok:`발끝으로 서서 소금 단지를 끌어내렸다. 단지가 차고 무겁다. 뚜껑을 밀랍으로 봉했다. 안이 말랐다.<br><br>소금은 썩지 않는다. 물에 젖지 않으면. 이 학교에서 젖지 않은 것은 이게 마지막일지도 모른다.<br><br>단지를 머리에 이고 조리실을 나왔다. 아래서 깡통 소리가 멈췄다. 선반 하나가 빈 걸 아래서도 아는 모양이다.`,
      ng:`단지를 끌어내리는데 선반이 무너졌다. 단지가 물에 떨어졌다.<br><br>물속에 손을 넣어 더듬었다. 단지를 찾았다. 다른 손이 같이 쥐고 있다. 작고 불은 손이다. 놓지 않는다.<br><br>당겨서 빼앗았다. 단지 바닥에 손톱자국이 넷. 소금은 반쯤 녹아 물이 됐다. 아래서 깡통 소리가 다시 났다. 빠르게.`,
      win:{ exp:16, dream:2, item:'소금 덩이' }, lose:{ hp:-24, mind:-16 } },
    { l:'② 숨을 크게 쉬고 저장고 아래까지 내려간다.', k:'steady', dc:23,
      doom:{ title:'저장고 아래', what:'저장고 물속 계단으로 끌려 내려갑니다', dc:18, sec:50,
        text:`숨을 크게 들이쉬고 물속 계단을 내려갔다. 선반에 깡통이 줄지어 있다. 상표가 다 불었다. 맨 아래 칸이 말린 것이다. 손을 뻗었다.<br><br>손목을 누가 잡았다. 선반 사이에서. 앞치마를 두른 몸이 깡통을 정리하던 자세 그대로 이쪽 손을 다른 칸에 옮겨 놓는다. 정리하는 것이다. 이쪽을.<br>당긴다. 더 아래로. 계단이 끝나는 데 없이 이어진다. 숨이 반 남았다. 위의 빛이 동전만 해진다.`,
        dieText:`조리실 저장고 맨 아래 칸에 새 깡통 하나가 놓였다. 상표가 없다.<br><br>흔들면 안에서 무엇이 구른다. 단추 같은 것이다.<br>저장고 문 위에 재고 칠판이 걸려 있다. 맨 아래 줄에 숫자 하나가 늘었다. 분필이 아직 젖어 있다.` },
      ok:`숨을 들이쉬고 물속 계단을 내려갔다. 맨 아래 칸에 손을 뻗었다. 앞치마 두른 손이 이쪽 손목을 잡으려 했다. 그보다 먼저 꾸러미 하나를 쥐고 발로 선반을 차 올라왔다.<br><br>물 위에 머리를 내밀었다. 숨이 터졌다. 꾸러미는 기름종이에 싼 말린 고기다. 매듭이 단단하다. 젖지 않았다.<br><br>매듭법이 이쪽 것이다. 이쪽이 쓰는 매듭이다. 언제 묶었는지 모른다.`,
      win:{ exp:22, dream:3, item:'말린 고기' } }
  ] },

{ at:'A', t:'쉬는 자리 — 세 자리',
  x:`잘 자리가 셋이다. 눕기 전에 자리부터 본다.<br><br>
    하나는 가운데. 바닥이 평평하다. 사방이 열렸다. 하나는 구석. 등이 막혔다. 바닥이 차다.<br>
    마지막 하나는 기둥 옆. 마르고 따뜻하다. 바닥에 사람 하나 누운 모양으로 먼지가 없다.<br><br>
    따뜻한 자리는 늘 누가 먼저 쓰고 있다. 비어 있을 때만 빈 것처럼 보인다.`,
  o:[
    { l:'① 구석에 등을 붙이고 찬 바닥에서 잔다.', k:'steady', dc:22,
      ok:`구석을 골랐다. 짐을 깔고 등을 두 벽에 붙였다. 무릎을 세웠다. 찬 기운이 엉덩이로 들어온다. 그냥 두었다.<br><br>밤중에 기둥 옆 따뜻한 자리에서 몸 뒤척이는 소리가 났다. 아무도 안 누운 자리다. 소리는 한참 났다. 이쪽은 구석에서 한 번도 깨지 않았다.<br><br>아침에 기둥 옆을 보니 먼지 없는 자리가 조금 넓어져 있다. 둘이 누운 넓이로. 같이 눕자고 기다린 것이다.`,
      ng:`구석에 등을 붙였다. 찬 바닥이 밤새 뼈를 판다. 깜빡 잠들었다.<br><br>깨니 따뜻하다. 기둥 옆이다. 언제 옮겼는지 모른다. 옆에 누가 누워 있다. 등을 이쪽으로 하고. 숨을 쉰다. 숨이 차갑다.<br><br>구석으로 기어 돌아갔다. 아침까지 눈을 뜨고 있었다. 기둥 옆에서 누가 계속 이불을 끌어당기는 소리를 냈다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-22, spirit:-22 } },
    { l:'② 따뜻한 자리를 손바닥으로 짚어 본다.', k:'sense', dc:22,
      ok:`쪼그려 앉아 따뜻한 자리에 손바닥을 댔다. 미지근하다. 가운데보다 가장자리가 더 따뜻하다. 사람이 누워 있다면 반대여야 한다.<br><br>밑에서 데우는 것이다. 바닥 아래 무엇이 몸을 대고 있다. 위에 누울 것을 기다리며.<br><br>그 자리에는 짐 하나도 두지 않았다. 일행을 다 구석으로 모았다. 밤새 따뜻한 자리가 식지 않았다.`,
      ng:`짚었다. 따뜻하다. 손바닥이 녹는다. 사흘 만에 처음 따뜻하다.<br><br>손을 떼기 싫다. 무릎도 대고 싶다. 정신을 차렸을 때는 반쯤 누워 있었다. 바닥이 등을 받는다. 부드럽게. 아래로.<br><br>동료가 발목을 잡아 끌어냈다. 등 쪽 옷이 바닥에 붙어 늘어났다가 떨어졌다. 그 자리가 이쪽 등 모양으로 오목하다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-18, spirit:-24 } },
    { l:'③ 잠을 쪼갠다 — 앉은 채로 조금씩 잔다.', k:'steady', dc:22, wake:1,
      ok:`어느 자리에도 눕지 않았다. 구석과 가운데 사이에 앉아 무릎을 안았다. 한 번에 아주 조금씩 잤다. 숨 백 번 자고 숨 열 번 깨고.<br><br>깰 때마다 둘러봤다. 세 번째 깼을 때 기둥 옆 자리에 누가 앉아 있었다. 이쪽처럼 무릎을 안고. 다섯 번째에는 없었다.<br><br>잠도 나눠 먹는 것이다. 먹을 것처럼. 한 번에 다 먹으면 다음이 없다. 몸이 그 나눔을 스스로 했다. 백 번째 숨이 오면 저절로 눈이 떠졌다. 아침에 머리가 맑았다. 밤새 잔 사람들보다.`,
      ng:`쪼개 자려 했는데 잠이 안 쪼개진다. 한 번 잠기니 깊다.<br><br>깨니 무릎을 안고 있던 팔이 다른 사람 팔이다. 이쪽 무릎을 다른 팔이 안고 있다. 차갑고 길다. 이쪽 팔은 바닥에 늘어져 있다.<br><br>소리를 지르자 팔이 풀렸다. 아무도 없다. 무릎에 팔 자국이 하얗게 두 줄 남았다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-20, spirit:-22 } }
  ] },

{ at:'A', t:'한밤 — 밖에서 부르는 동료',
  x:`가리개를 세우고 그 안에 다 들어왔다. 다섯이다. 셌다. 다 안에 있다.<br><br>
    밖에서 이쪽 이름을 부른다. 동료 목소리다. 다쳤다고. 발이 끼었다고. 도와 달라고.<br>
    그 동료는 지금 이쪽 옆에서 자고 있다. 숨을 쉰다. 어깨가 오르내린다.<br><br>
    생존가가 지키는 규칙 중 오래된 것이 있다. 밤에는 나가지 않는다. 누가 불러도.`,
  o:[
    { l:'① 대답하지 않는다 — 소리 없이 버틴다.', k:'steady', dc:22, wake:1,
      ok:`입을 다물었다. 옆 동료 어깨에 손을 얹었다. 따뜻하다. 진짜는 여기 있다.<br><br>밖의 목소리가 운다. 아프다고. 왜 안 오느냐고. 이름을 부른다. 이쪽 이름을, 하나씩 다 정확히. 대답이 없으니 목소리가 바뀐다. 이번엔 이쪽 어머니 목소리다.<br>그래도 대답하지 않았다. 새벽이 오자 목소리가 그쳤다. 가리개 밖에 발자국이 빙 둘러 나 있다. 한 바퀴. 들어올 틈을 찾던 자국이다.<br><br>대답하지 않는 것도 버티는 것이다. 귀는 듣되 입은 닫는다. 그 둘을 따로 쥐는 법을 몸이 익혔다. 그 밤 이후로 이름이 불려도 목이 먼저 움직이지 않았다.`,
      ng:`입을 다물었다. 그런데 목소리가 이쪽 목소리로 바뀌었다. 밖에서 이쪽이 이쪽 이름을 부른다.<br><br>옆 동료가 깼다. 이쪽을 보고, 밖을 본다. 어느 쪽이 진짜냐는 눈이다. 이쪽 손을 뿌리친다. 차가운 손이라고.<br><br>새벽까지 동료는 이쪽 옆에 오지 않았다. 손은 차갑지 않았다. 아마.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-20, spirit:-24 } },
    { l:'② 가리개를 열고 나가 본다.', k:'bond', dc:23,
      doom:{ title:'다친 동료', what:'부르는 목소리에게 어둠 속으로 끌려갑니다', dc:18, sec:50,
        text:`가리개를 들추고 나갔다. 몇 걸음 앞에 동료가 쓰러져 있다. 발이 바위틈에 끼었다. 얼굴이 이쪽을 본다. 고맙다고.<br><br>무릎을 꿇고 발을 빼 주려 손을 뻗었다. 손이 잡혔다. 바위틈 속에서. 동료가 웃는다. 끼인 발은 처음부터 없었다. 바위틈 속으로 이쪽 손이 끌려 들어간다.<br>뒤에서 가리개가 펄럭인다. 동료들 목소리가 들린다. 진짜 목소리다. 멀다. 이쪽 앞의 동료가 같은 목소리로 대답한다. 여기 있어.`,
        dieText:`아침에 가리개 밖 바위틈에 소매 한 짝이 끼어 있었다.<br><br>그날 밤에도 밖에서 누가 불렀다. 다쳤다고. 발이 끼었다고. 이번엔 다섯 중 하나가 아니다. 없어진 사람의 목소리다.<br>남은 사람들은 대답하지 않았다. 대답하지 않는 법을 그날 배웠다. 늦게.` },
      ok:`가리개를 반만 들추고 손을 뻗지 않았다. 불만 내밀었다.<br><br>몇 걸음 앞에 동료가 쓰러져 있다. 발이 바위틈에 끼었다. 불빛이 닿자 얼굴이 웃는다. 끼인 발 쪽에는 발이 없다. 다리가 바위틈 속으로 길게 이어져 있다. 안에서 자란 것처럼.<br><br>가리개를 도로 닫았다. 밖의 동료가 운다. 새벽까지 울었다. 안의 동료는 이쪽 옆에서 잘 잤다.`,
      win:{ exp:20, dream:3 } }
  ] },

{ at:'A1', t:'의상실 — 체온이 남은 털옷',
  x:`의상실은 춥다. 옷이 다 젖었다. 이가 맞부딪힌다. 추위는 먼저 손가락을, 그다음 판단을 가져간다.<br><br>
    옷걸이에 털옷이 걸려 있다. 인형탈 몸통이다. 머리는 따로 선반에 얹혔다.<br>
    손을 대 보니 털 속이 따뜻하다. 방금 누가 벗어 건 것처럼.<br><br>
    탈 머리 선반에서 단추 눈 둘이 이쪽을 본다.`,
  o:[
    { l:'① 털옷을 입지 않고 떨면서 버틴다.', k:'steady', dc:22,
      ok:`손을 거뒀다. 따뜻한 것은 누가 데운 것이다. 데운 쪽이 누군지 모를 때는 안 입는다.<br><br>젖은 옷을 벗어 짰다. 다시 입었다. 짠 옷은 덜 차다. 겨드랑이에 손을 넣고 제자리에서 발을 굴렀다. 백 번. 몸이 조금 데워졌다.<br><br>나가면서 돌아봤다. 털옷이 옷걸이에서 이쪽 쪽으로 한 뼘 기울어 있다. 안아 주려는 모양으로. 단추 눈이 섭섭해 보였다.`,
      ng:`버티는데 손가락이 하얘진다. 판단이 흐려진다. 털옷이 자꾸 눈에 들어온다.<br><br>한 팔만 넣었다. 따뜻하다. 너무 따뜻하다. 소매 안에서 손이 이쪽 손을 쥐었다. 반가운 듯이 꽉.<br><br>팔을 빼는 데 일행 둘이 매달려야 했다. 소매 안쪽 털이 손등에 붙어 같이 딸려 나왔다. 털이 아니다. 머리카락이다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, spirit:-22 } },
    { l:'② 털옷을 뒤집어 안쪽을 본다.', k:'gaze', dc:22,
      ok:`털옷을 내려 칼끝으로 뒤집었다. 안감이 드러났다.<br><br>안감에 바늘땀이 빼곡하다. 이름이 수놓여 있다. 여러 사람 이름이 겹겹이. 맨 위 이름은 실이 새것이다.<br>따뜻한 건 그 이름에서 나온 온기다. 마지막으로 입었던 사람의 것.<br><br>도로 걸었다. 안 입었다. 대신 바닥에 떨어진 털 뭉치를 주워 신발 안에 채웠다. 발가락이 조금 살았다.`,
      ng:`뒤집었는데 안감이 없다. 털 안쪽이 살갗이다. 따뜻하고 매끄럽다.<br><br>칼끝이 닿자 털옷이 움찔했다. 옷걸이가 흔들린다. 선반의 탈 머리들이 일제히 이쪽으로 돌아갔다.<br><br>뒷걸음으로 의상실을 나왔다. 칼끝에 묻은 것이 피도 물도 아니다. 미지근한 것이 끈적하다. 닦아도 칼에서 좀약 냄새가 났다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-18, spirit:-24 } },
    { l:'③ 바닥에 쌓인 자투리 천으로 몸을 싼다.', k:'fix', dc:21,
      ok:`옷걸이 밑에 자투리 천이 쌓여 있다. 털옷을 만들고 남은 것이다. 차다. 그래도 말랐다.<br><br>몇 겹 몸에 감고 끈으로 묶었다. 젖은 옷 위에 마른 천. 찬 것 위에 찬 것이지만 바람은 막는다.<br><br>따뜻한 것보다 마른 것을 고른다. 따뜻한 것은 누가 줬고, 마른 것은 이쪽이 골랐다.`,
      ng:`자투리를 끌어당기는데 천 더미가 움직였다. 밑에 무엇이 웅크려 있다. 천을 덮고 잠든 것이다.<br><br>그것이 깼다. 천을 빼앗긴 줄 알고 이쪽 발목을 문다. 이빨이 납작하다. 단추 같다.<br><br>천을 던져 주고 물러났다. 발목에 동그란 이빨 자국이 둘. 단추 구멍처럼 넷씩 뚫렸다.`,
      win:{ exp:15, dream:2, hp:6 }, lose:{ hp:-24, mind:-14 } }
  ] },

{ at:'A2', t:'세면장 — 마실 물',
  x:`기숙사 세면장 수도꼭지에서 물이 흐른다. 맑다. 따뜻하다. 김이 난다.<br><br>
    학교 전체가 물에 잠겼다. 마실 물은 한 방울도 없다. 사방이 물인데.<br>
    그래도 안다. 이 물은 이 학교 물이다. 여기 잠긴 것들이 다 이 물을 마셨다.<br><br>
    거울에 김이 서렸다. 김 위에 손가락으로 쓴 글씨가 있다. 양치는 세 번.`,
  o:[
    { l:'① 꼭지 물은 버리고 창 유리에 맺힌 물을 모은다.', k:'steady', dc:22, wake:1,
      ok:`꼭지는 잠갔다. 창으로 갔다. 유리 너머가 물이다. 안쪽 유리에 이슬이 맺혀 있다. 바깥 물이 차고 안 공기가 따뜻해서다.<br><br>천을 유리에 대 이슬을 훑고 병에 짰다. 한 번에 몇 방울. 오래 걸렸다. 손이 저리도록 했다. 병 바닥에 한 모금이 고였다.<br>이 물은 잠긴 물이 아니다. 공기에서 나온 물이다.<br><br>물속에서 마실 물을 찾는 법. 물이 많을수록 마실 것은 적다. 마실 물은 늘 물과 물 아닌 것 사이에 맺힌다. 그 사이를 눈이 먼저 찾기 시작했다. 유리 너머에서 얼굴 하나가 이쪽 손을 따라 움직였다.`,
      ng:`유리에 천을 댔다. 이슬을 훑는데 유리 너머에서 손바닥이 마주 댔다. 이쪽 손바닥과 겹친다.<br><br>천을 짰다. 병에 떨어지는 물이 탁하다. 이슬이 아니다. 유리 틈으로 새어 든 바깥 물이다. 유리에 금이 가 있다. 이쪽 손바닥 크기로.<br><br>물러섰다. 금이 한 뼘 더 뻗었다. 그날 물은 못 마셨다. 혀가 입천장에 붙었다.`,
      win:{ exp:22, dream:3, item:'맑은 물' }, lose:{ hp:-22, mind:-16 } },
    { l:'② 꼭지 물을 받아 오래 끓인다.', k:'fix', dc:22,
      ok:`꼭지 물을 냄비에 받아 불에 올렸다. 오래 끓였다. 모르는 물은 끓인다. 끓이면 대부분 죽는다.<br><br>끓는 물 위로 김이 오른다. 김 속에서 작은 목소리가 났다. 뜨거워. 끓일수록 소리가 작아졌다. 그쳤다.<br><br>식혀서 맛봤다. 쇠 맛이 조금 난다. 물이다. 그냥 물이다. 이제는.`,
      ng:`끓였다. 거품이 올라온다. 거품마다 작은 얼굴이 비친다. 터질 때마다 비명이 난다.<br><br>불을 껐다. 냄비 바닥에 긴 머리카락이 한 덩이 엉켜 있다. 끓이기 전에는 없었다.<br><br>쏟아 버렸다. 세면장 하수구가 그 물을 꿀꺽 삼켰다. 하수구 안에서 고맙다는 소리가 났다.`,
      win:{ exp:18, dream:2, item:'맑은 물' }, lose:{ mind:-18, spirit:-22 } }
  ] },

{ at:'A', t:'내려가는 길 — 무거워진 짐',
  x:`짐이 무겁다. 아침보다 무겁다. 먹을 것은 줄었는데.<br><br>
    제 짐 무게는 손이 안다. 무엇이 어디 들었는지도. 바닥에 불, 그 위에 칼과 끈, 맨 위에 먹을 것.<br>
    짐 안에서 모르는 것이 손에 잡힌다. 작은 신발 한 짝. 젖은 명찰. 반쯤 먹은 사탕.<br><br>
    넣은 적이 없다. 짐 끈이 이쪽 매듭으로 묶여 있다.`,
  o:[
    { l:'① 모르는 것을 하나씩 꺼내 버린다.', k:'sense', dc:22,
      ok:`짐을 다 쏟았다. 아는 것과 모르는 것을 나눴다. 모르는 것은 길가에 줄지어 놓았다.<br><br>신발, 명찰, 사탕, 머리끈, 단추. 다섯 개다. 이쪽 일행 수와 같다. 하나씩 누가 넣은 것이다.<br><br>짐을 다시 쌌다. 가볍다. 몇 걸음 가다 돌아보니 길가에 놓은 것들이 없다. 누가 주워 갔다. 다음 사람 짐에 넣으려고.`,
      ng:`꺼내 버렸다. 그런데 다시 짐을 들면 무겁다. 열어 보면 또 들어 있다. 신발 한 짝. 이번엔 다른 쪽 짝이다.<br><br>세 번 버렸다. 세 번 다시 있었다. 네 번째엔 신발 안에 발이 들어 있었다. 작은 발이다. 차갑다.<br><br>짐을 내던지고 물러섰다. 다시 열어 보니 신발만 있다. 그 뒤로 짐을 열지 못했다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-18, spirit:-24 } },
    { l:'② 다 버리고 셋만 남긴다 — 불, 칼, 물.', k:'steady', dc:22, wake:1,
      ok:`짐을 통째로 내려놓았다. 손만 넣어 셋을 꺼냈다. 부싯깃, 칼, 물병. 그것만 몸에 지녔다. 나머지는 짐째 두고 갔다.<br><br>가볍다. 몸이 가볍고 머리가 맑다. 무엇을 잃을까 세지 않아도 된다. 셋은 몸에 붙어 있다.<br>뒤에서 짐이 끌려가는 소리가 났다. 누가 가져간다. 무거운 것을 좋아하는 무엇이.<br><br>살아남는 데 드는 것은 생각보다 적다. 버릴 줄 알면 빼앗길 것도 적다. 고르는 손이 망설이지 않았다. 셋. 그 셋이 무엇인지 몸이 오래전부터 알고 있었다는 걸 그제야 알았다.`,
      ng:`셋만 꺼내려는데 손이 짐 안에서 다른 손에 닿았다. 짐 안에서. 손가락이 이쪽 손가락을 센다.<br><br>손을 뺐다. 칼이 없다. 짐 안의 손이 가져갔다. 다시 넣을 엄두가 안 난다.<br><br>불과 물만 들고 갔다. 칼 없이. 칼부터 챙기던 손이 칼을 잃었다. 걷는 내내 허리가 허전했다. 뒤에서 짐이 따라 끌려오는 소리가 났다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-22, mind:-18 } },
    { l:'③ 짐 끈 매듭을 들여다본다.', k:'gaze', dc:22,
      ok:`매듭을 봤다. 이쪽 매듭이다. 그런데 끝을 마무리한 방향이 반대다. 거울에 비춘 것처럼.<br><br>이쪽을 아주 잘 아는 무엇이 묶었다. 이쪽 손을 오래 지켜본 것이다. 왼손잡이처럼 묶는 이쪽의 그림자.<br><br>매듭을 풀어 원래대로 다시 묶었다. 그리고 모르는 것들을 버렸다. 그날부터 매듭 끝에 표시를 하나 넣었다. 이쪽만 아는 꼬임 하나. 그 뒤로 짐은 무거워지지 않았다.`,
      ng:`매듭을 들여다보는데 매듭이 저절로 조금 풀렸다. 누가 안에서 당긴다.<br><br>짐 아가리가 벌어진다. 안이 어둡다. 짐보다 깊다. 그 안에서 젖은 냄새가 올라온다.<br><br>매듭을 확 당겨 닫았다. 손가락이 끈에 베였다. 짐 안에서 문 닫히는 소리가 났다. 짐 안에서.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-16, spirit:-22 } }
  ] },

{ at:'A1', t:'탕비실 — 이름 붙은 도시락',
  x:`5층 탕비실 직원 냉장고가 돌아간다. 전기가 끊겼다던 건물에서. 문을 여니 찬 바람이 나온다.<br><br>
    칸마다 도시락이 있다. 뚜껑에 이름이 적혔다. 날짜도. 다 오늘 날짜다. 밥이 아직 촉촉하다.<br>
    맨 아래 칸은 이름이 없다. 마른 것들이 비닐에 싸여 있다.<br><br>
    냉장고 안쪽 벽에 쪽지가 붙었다. 남의 도시락 먹지 마세요.`,
  o:[
    { l:'① 이름 없는 맨 아래 칸만 뒤진다.', k:'luck', dc:22,
      ok:`이름 붙은 칸은 손대지 않았다. 쪼그려 앉아 맨 아래 칸만 뒤졌다.<br><br>비닐 안에 말린 고기가 있다. 진짜다. 소금기가 하얗게 올라왔다. 오래 둔 것이다. 오늘 날짜가 아닌 유일한 것이다.<br><br>챙겨 넣고 문을 닫았다. 냉장고 안에서 도시락 뚜껑 여는 소리가 났다. 하나, 둘. 점심시간이다.`,
      ng:`맨 아래를 뒤지는데 위 칸 도시락 하나가 떨어졌다. 뚜껑이 열렸다. 밥 위에 이름이 쓰여 있다. 김으로 오려 붙인 글씨다. 이쪽 이름이다.<br><br>그 도시락은 처음부터 이쪽 것이었다. 냉장고가 기다리고 있었다. 밥에서 김이 난다. 따뜻하다. 방금 지은 밥이다.<br><br>먹지 않았다. 뚜껑을 닫아 도로 넣었다. 그날 내내 입안에 밥 냄새가 돌았다. 먹은 적 없는 밥 냄새.`,
      win:{ exp:16, dream:2, item:'말린 고기' }, lose:{ mind:-16, spirit:-22 } },
    { l:'② 문이 저절로 열리려 한다 — 등으로 막고 버틴다.', k:'steady', dc:23,
      doom:{ title:'점심시간', what:'냉장고 안으로 끌려 들어갑니다', dc:18, sec:45,
        text:`문이 안에서 밀린다. 등을 대고 막았다. 냉기가 등뼈로 스민다. 안에서 도시락 뚜껑 여는 소리가 줄줄이 난다.<br><br>문틈으로 손이 나와 이쪽 허리띠를 쥐었다. 손이 차다. 냉장고만큼. 등으로 막은 문을 손이 안쪽으로 당긴다. 이쪽도 같이.<br>등이 문에 붙었다. 얼어서 붙었다. 문이 열리며 이쪽을 안으로 끌어들인다. 칸과 칸 사이로. 빈 칸 하나가 기다린다. 사람 하나 웅크릴 크기다.`,
        dieText:`냉장고 문이 닫혔다. 돌아가는 소리가 조금 커졌다.<br><br>문에 붙은 쪽지 밑에 쪽지가 하나 늘었다. 오늘 날짜. 이쪽 이름. 그 밑에 한 줄. 남의 도시락 먹지 마세요.<br>탕비실 불이 꺼졌다. 냉장고 안 불만 켜져 있다. 문틈으로 새어 나온다.` },
      ok:`등을 대고 막았다. 안에서 미는 힘이 세다. 무릎을 굽혀 발바닥으로 바닥을 밀었다.<br><br>찬 데서 오래 버티는 법은 안다. 숨을 얕게, 근육을 풀고, 떨림을 그냥 둔다. 떨림이 몸을 데운다.<br>안에서 미는 힘이 먼저 지쳤다. 문이 닫히고 냉장고가 조용히 돈다.<br><br>등을 떼자 옷 등판이 얼어 문에 붙어 있다가 찢기며 떨어졌다. 문에 등 모양 서리가 남았다.`,
      win:{ exp:20, dream:3 } }
  ] },

{ at:'A2', t:'보일러실 — 둘러앉은 것들',
  x:`보일러실에 불이 꺼지지 않았다. 물이 가슴까지 찼는데 보일러 아궁이만 물 밖이다. 붉게 탄다.<br><br>
    온몸이 젖었다. 입술이 파랗다. 동료들도 다 떨고 있다.<br>
    아궁이 둘레에 무엇이 둘러앉아 있다. 물에 반쯤 잠겨서. 손을 불 쪽으로 내밀고. 녹이는 것이다. 녹을 리 없는 손을.<br><br>
    한 자리가 비었다. 불에서 제일 가까운 자리다.`,
  o:[
    { l:'① 불가에 가지 않는다 — 젖은 옷을 짜고 몸을 움직여 데운다.', k:'steady', dc:22, wake:1,
      ok:`불에서 가장 먼 벽으로 갔다. 동료들도 불렀다. 옷을 벗어 서로 짜 주고 다시 입혔다. 그리고 붙어 섰다. 등과 가슴을 대고.<br><br>제자리에서 발을 굴렀다. 다 같이. 박자를 맞춰서. 백 번에 손가락이 돌아왔다. 이백 번에 입술 색이 돌아왔다.<br>불가에 둘러앉은 것들이 고개를 돌려 이쪽을 본다. 불도 없이 데워지는 쪽을. 부러운 듯이.<br><br>몸은 불 없이도 데워진다. 데우는 것은 움직임이고, 지키는 것은 붙어 있는 것이다. 그 둘을 다른 사람 몸에까지 넓히는 법을 알게 됐다. 다섯이 붙으면 한 사람보다 오래 간다.`,
      ng:`벽에 붙어 발을 굴렀다. 그런데 물이 차다. 굴러도 굴러도 안 데워진다. 손가락이 굳는다.<br><br>정신을 차리니 한 걸음씩 불 쪽으로 가고 있다. 다리가 저절로. 둘러앉은 것들이 자리를 좁혀 준다. 빈자리가 이쪽을 기다린다.<br><br>동료가 뺨을 쳤다. 세 걸음 앞에서 멈췄다. 손이 불가의 빈자리를 향해 뻗어 있었다.`,
      win:{ exp:22, dream:3, hp:6 }, lose:{ hp:-26, mind:-16 } },
    { l:'② 빈자리에 앉아 잠깐만 손을 녹인다.', k:'luck', dc:23,
      doom:{ title:'제일 가까운 자리', what:'불가의 손들에게 물속으로 끌려 들어갑니다', dc:18, sec:45,
        text:`빈자리에 앉았다. 불이 따뜻하다. 손가락이 녹는다. 사흘 만이다. 눈이 저절로 감긴다.<br><br>양옆에서 손이 이쪽 어깨에 얹혔다. 둘러앉은 것들이 서로 어깨를 겯는다. 이쪽도 그 줄에 들었다. 다 같이 몸을 흔든다. 앞으로, 뒤로. 노래하는 박자다.<br>흔들 때마다 조금씩 아래로 내려간다. 물이 가슴, 어깨, 턱. 어깨를 겯은 팔이 풀리지 않는다. 불은 그대로 따뜻하다. 물만 차다.`,
        dieText:`보일러 아궁이는 계속 탔다.<br><br>둘레에 둘러앉은 것이 하나 늘었다. 물에 반쯤 잠겨서. 손을 불 쪽으로 내밀고.<br>빈자리가 또 하나 생겼다. 불에서 제일 가까운 자리.` },
      ok:`빈자리에 앉았다. 앉자마자 양옆 손이 어깨로 올라온다. 그보다 먼저 일어섰다. 손바닥만 불에 한 번 쬐고.<br><br>그 한 번에 손가락이 녹았다. 칼을 쥘 수 있게 됐다. 그거면 됐다.<br><br>둘러앉은 것들이 일어선 이쪽을 올려다본다. 다시 앉으라는 듯 자리를 좁혀 준다. 등을 돌렸다. 등 뒤에서 오래 그 자리가 비어 있었다.`,
      win:{ exp:20, dream:3 } }
  ] },

{ at:'A', t:'쉬는 자리 — 묻어 둔 불',
  x:`불을 피웠다. 작게. 밤이 길다.<br><br>
    어둠 속에서 무엇이 불 둘레를 돈다. 발소리가 일정하다. 불빛이 닿는 데 바로 바깥을 돈다.<br>
    불은 두 가지다. 짐승을 쫓는 불, 그리고 무엇을 부르는 불.<br><br>
    돌던 발소리가 멈췄다. 불을 보고 있다. 아주 가까이서.`,
  o:[
    { l:'① 불을 흙으로 묻는다 — 어둠 속에서 버틴다.', k:'steady', dc:22,
      ok:`흙을 한 줌씩 덮어 불을 묻었다. 숯은 안 꺼졌다. 흙 밑에서 탄다. 빛은 없고 온기만 남았다.<br><br>어둠이 덮였다. 발소리가 다시 돈다. 그런데 이번엔 헤맨다. 불빛을 보고 왔는데 불이 없다. 몇 바퀴 더 돌다가 멀어졌다.<br><br>새벽에 흙을 걷었다. 숯이 아직 붉다. 그 위에 손을 녹이고 다시 불을 살렸다. 밤의 불과 아침의 불은 같은 불이다. 숨기는 동안만 달랐다.`,
      ng:`묻었다. 어둠이 덮였다. 발소리가 멈췄다. 숨소리가 들린다. 불이 있던 자리 바로 앞에서.<br><br>그것이 흙을 판다. 손으로. 묻힌 불을 찾는다. 흙이 이쪽 무릎으로 튄다. 가깝다. 손 하나 거리다.<br><br>숨을 죽이고 새벽까지 앉아 있었다. 새벽에 보니 불 자리가 깊게 파였다. 숯이 없다. 다 가져갔다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-22, spirit:-24 } },
    { l:'② 불을 키워 불빛 끝까지 비춘다.', k:'fix', dc:22,
      ok:`마른 것을 다 넣어 불을 키웠다. 불빛이 넓어진다. 어둠이 물러난다.<br><br>불빛 끝에 그것이 서 있다. 사람 키다. 얼굴을 손으로 가리고 있다. 빛이 싫은 것이다. 한 걸음 물러난다. 불이 커질 때마다 한 걸음.<br><br>마른 것이 다 탔을 때 그것은 불빛 끝에서 멀리 있었다. 다시 줄어드는 불빛을 따라 오지 않았다. 아침까지 손으로 얼굴을 가린 채 서 있었다.`,
      ng:`불을 키웠다. 불빛 끝에 그것이 서 있다. 얼굴을 가리지 않는다. 불을 본다. 따뜻한 쪽을.<br><br>불빛 안으로 한 걸음 들어왔다. 키운 불이 그것을 불렀다. 마른 것은 다 탔다. 불이 줄어든다. 그것이 줄어드는 만큼 다가온다.<br><br>마지막 불씨에 겉옷을 넣었다. 그것이 불씨 앞에 쪼그려 앉아 손을 쬐었다. 그리고 갔다. 겉옷 한 벌과 바꾼 밤이다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-24, mind:-18 } }
  ] },

{ at:'A', t:'사흘째 — 먹은 기억이 없는 배',
  x:`아침에 깼는데 배가 부르다. 사흘째 굶었는데.<br><br>
    입안에 단맛이 남았다. 이 사이에 무엇이 끼었다. 이쪽은 아무것도 먹지 않았다.<br>
    동료 하나가 눈을 피한다. 밤중에 봤다고 한다. 이쪽이 어둠 쪽을 향해 앉아 무엇을 받아먹고 있었다고. 누가 떠먹여 주고 있었다고.<br><br>
    생존가는 모르는 것을 먹지 않는다. 자는 동안의 이쪽은 그걸 모르는 모양이다.`,
  o:[
    { l:'① 손가락을 목에 넣어 게워 낸다.', k:'steady', dc:22,
      ok:`구석으로 가 손가락을 목에 넣었다. 게웠다. 여러 번.<br><br>나온 것은 흙이다. 젖은 흙과 작은 돌, 꽃잎 몇 장. 무덤 흙 냄새가 난다. 배가 텅 비었다. 허기가 돌아왔다. 차라리 다행이다.<br><br>물로 입을 헹궜다. 허기는 이쪽 것이다. 부른 배는 남의 것이었다.`,
      ng:`손가락을 넣었는데 안 나온다. 배 속에 든 것이 버틴다. 꽉 붙어 있다.<br><br>세게 눌렀다. 나온 건 물뿐이다. 차갑고 비린 물. 배는 여전히 부르다. 안에서 무엇이 꿈틀했다.<br><br>그날 하루 배가 고프지 않았다. 그게 무서웠다. 밤이 되자 입안에 다시 단맛이 돌았다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, spirit:-22 } },
    { l:'② 이 사이에 낀 것을 빼 본다.', k:'gaze', dc:22,
      ok:`칼끝으로 이 사이를 쑤셨다. 실 한 가닥이 딸려 나왔다. 빨갛다. 끝이 매듭지어졌다.<br><br>실이다. 떠먹여 준 숟가락이 아니다. 실에 꿴 것을 입에 넣어 주고 실을 당겨 도로 빼 간 것이다. 먹인 게 아니다. 맛만 보게 했다. 길들이는 것이다.<br><br>실을 불에 태웠다. 탄내 속에 단내가 섞였다. 그날 밤 입을 천으로 묶고 잤다.`,
      ng:`쑤시는데 이 사이에서 나온 것이 손톱이다. 작은 손톱이 반달 모양으로.<br><br>떠먹여 준 것이 숟가락이 아니었다. 손가락이었다. 이쪽 입에 손가락을 넣고 무엇을 문질러 먹였다.<br><br>밤새 입을 헹궜다. 헹궈도 혀끝에 손가락 맛이 남았다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-18, spirit:-24 } },
    { l:'③ 잠들기 전에 손목을 동료 손목에 묶는다.', k:'fix', dc:22, wake:1,
      ok:`그날 밤 잠들기 전에 끈으로 이쪽 손목과 옆 동료 손목을 묶었다. 매듭은 이쪽만 아는 꼬임으로. 자는 손이 못 풀게.<br><br>한밤에 손목이 당겨졌다. 이쪽 몸이 일어나 어둠 쪽으로 가려 한다. 끈이 버틴다. 옆 동료가 깨서 이쪽 어깨를 눌렀다. 이쪽은 계속 잤다. 어둠 쪽에서 숟가락 부딪는 소리가 실망스럽게 멀어졌다.<br><br>깨어 있는 것만 지키면 되는 줄 알았다. 자는 몸도 지켜야 한다. 잠든 자신을 단속하는 법. 끈 한 줄, 매듭 하나, 옆 사람 하나. 그날부터 잠자리를 고르듯 잠든 몸을 묶을 데를 골랐다.`,
      ng:`묶고 잤다. 한밤에 손목이 당겨졌다. 끈이 버틴다. 그런데 옆 동료 쪽에서 당긴다.<br><br>눈을 떴다. 동료가 일어나 어둠 쪽으로 걷고 있다. 눈을 감은 채. 이쪽 손목을 끌고. 이번엔 동료 차례였다.<br><br>매달려 버텼다. 끈이 손목을 파고들었다. 동료가 멈춰 쓰러졌다. 아침에 둘 다 손목이 피투성이였다. 둘 다 배가 불렀다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-24, mind:-16 } }
  ] },

{ at:'A1', t:'놀이 세트 — 텃밭 동산',
  x:`6층 놀이 세트 한쪽이 텃밭이다. 가짜 흙에 가짜 채소가 꽂혀 있다. 천으로 만든 당근, 솜으로 만든 배추.<br><br>
    그 사이에 진짜가 자란다. 조명 아래서. 잎이 연하다. 산나물이다. 보면 안다.<br>
    텃밭 가운데 허수아비가 서 있다. 밀짚모자, 웃는 입. 팔을 벌렸다.<br><br>
    허수아비 발밑 흙이 제일 검고 기름지다. 거기 자란 것이 제일 푸르다.`,
  o:[
    { l:'① 허수아비에게서 먼 쪽 잎만 손끝으로 골라 딴다.', k:'gaze', dc:22,
      ok:`텃밭 가장자리부터 한 포기씩 잎 뒤를 손끝으로 쓸었다. 털 있는 것만 땄다. 매끈한 것은 그대로 두었다.<br><br>허수아비 발밑 쪽으로는 가지 않았다. 제일 푸른 것은 제일 많이 먹고 자란 것이다. 무엇을 먹었는지는 묻지 않는다.<br><br>한 줌이 모였다. 고개를 드니 허수아비 고개가 이쪽으로 돌아가 있다. 아까는 정면을 봤다.`,
      ng:`쓸어 보는데 손끝이 굳었다. 조명이 뜨겁다. 땀이 눈에 들어간다.<br><br>정신을 차리니 허수아비 발밑에 쪼그려 앉아 있다. 제일 푸른 잎을 쥐고. 뿌리째 뽑았다. 뿌리 끝에 머리카락이 엉켜 나왔다.<br><br>던져 버리고 물러섰다. 허수아비 웃는 입이 조금 더 벌어져 있었다.`,
      win:{ exp:16, dream:2, item:'산나물' }, lose:{ mind:-16, spirit:-22 } },
    { l:'② 아무것도 따지 않고 지난다.', k:'steady', dc:22,
      ok:`손을 거뒀다. 조명 아래 자란 것은 해 아래 자란 것과 다르다. 모르는 것은 안 먹는다. 사흘째라도.<br><br>텃밭 옆을 지나는데 허수아비가 팔을 내렸다. 천천히. 바구니를 내미는 자세로. 바구니에 산나물이 소복하다.<br><br>안 받았다. 허수아비 팔이 다시 올라갔다. 바구니가 흙에 떨어졌다. 산나물 밑에 손가락이 하나 있었다.`,
      ng:`지나가는데 배가 운다. 크게. 조명 아래 텃밭 전체가 이쪽을 돌아본다.<br><br>허수아비 팔이 내려와 이쪽 어깨를 짚는다. 배가 고프면 먹어야지. 짚은 손이 무겁다. 무릎이 꺾인다. 흙 쪽으로.<br><br>동료가 팔을 쳐 냈다. 어깨에 밀짚이 박혀 있다. 빼니 밀짚 끝에 피가 묻어 나왔다. 이쪽 피가 아니다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-22, spirit:-24 } }
  ] },

{ at:'A2', t:'중정 — 유리 온실',
  x:`중정에 유리 온실이 있다. 유리 너머가 물인데 온실 안은 말랐다. 흙이 있다. 풀이 자란다.<br><br>
    약초다. 상처에 붙이는 것, 열을 내리는 것. 잎 모양만 봐도 안다. 한쪽 그늘진 흙에는 버섯도 났다.<br>
    유리마다 얼굴이 붙어 있다. 바깥 물속에서. 학생들이다. 안을 들여다본다. 숨 쉬는 쪽을.<br><br>
    온실 천장 유리 한 장에 금이 갔다. 금에서 물이 한 방울씩 떨어진다.`,
  o:[
    { l:'① 약초만 한 줌 뜯고 바로 나온다.', k:'evade', dc:22,
      ok:`문 가까운 데 난 것만 골랐다. 허리를 굽힌 채 한 줌 뜯어 품에 넣었다. 오래 있지 않았다.<br><br>유리 너머 얼굴들이 이쪽을 따라 옆으로 미끄러진다. 유리에 손바닥을 댄다. 두드리지는 않는다.<br><br>문을 닫고 나오자 등 뒤에서 금 간 유리가 한 번 울었다. 물 떨어지는 박자가 빨라졌다.`,
      ng:`뜯는데 뿌리가 깊다. 당기는 사이 천장 금이 한 뼘 뻗었다. 물이 줄기로 쏟아진다.<br><br>얼굴들이 일제히 그 금으로 모인다. 유리에 이마를 댄다. 민다. 금이 더 뻗는다.<br><br>약초를 반만 뜯은 채 뛰쳐나왔다. 손바닥에 뿌리에 베인 자국이 길다. 등 뒤에서 유리가 깨지는 소리가 났다.`,
      win:{ exp:16, dream:2, item:'약초 뭉치' }, lose:{ hp:-24, mind:-16 } },
    { l:'② 그늘진 흙에 엎드려 버섯까지 캔다.', k:'steady', dc:23,
      doom:{ title:'온실 유리', what:'깨진 유리 틈으로 물속에 끌려 나갑니다', dc:18, sec:45,
        text:`그늘진 흙에 엎드려 버섯을 하나씩 캤다. 갓 밑 주름을 확인하며. 천천히. 버섯 앞에서는 서두르지 않는다.<br><br>그 사이 천장 유리가 깨졌다. 물이 쏟아진다. 온실이 금방 찬다. 일어서려는데 발목을 잡혔다. 깨진 틈으로 들어온 손들이다.<br>당긴다. 위로. 깨진 천장 쪽으로. 물이 이쪽을 들어 올린다. 유리 조각이 등을 긋는다. 틈 너머는 물이다. 학생들이 줄지어 손을 뻗고 있다.`,
        dieText:`온실이 물에 다 잠겼다. 흙 위에 버섯 한 줌이 가지런히 놓여 있다.<br><br>유리 너머 얼굴이 하나 늘었다. 맨 끝에. 안을 들여다본다. 숨 쉬는 쪽을.<br>그 얼굴만 손에 버섯을 쥐고 있다.` },
      ok:`엎드려 버섯을 캤다. 갓 밑 주름을 확인하며 하나씩. 천장에서 물 떨어지는 박자를 셌다. 빨라지면 멈추고, 느려지면 캤다.<br><br>한 줌 모였을 때 박자가 갑자기 빨라졌다. 바로 일어나 문으로 갔다. 등 뒤에서 천장이 터졌다. 물이 온실을 채운다. 문을 닫았다.<br><br>문 유리 너머로 버섯을 캐던 흙이 잠긴다. 학생 하나가 그 흙에 엎드린다. 이쪽이 엎드렸던 자세로. 버섯을 캐는 손 모양을 한다.`,
      win:{ exp:20, dream:3, item:'야생 버섯' } }
  ] },

{ at:'A', t:'벽장 — 줄어드는 공기',
  x:`복도에서 무엇이 온다. 발소리가 무겁다. 일행은 흩어져 숨었다. 이쪽은 벽장 안이다.<br><br>
    좁다. 문틈이 손가락 하나만 하다. 공기가 금방 탁해진다. 숨을 쉴수록 줄어든다.<br>
    숨에도 몫이 있다. 먹을 것처럼, 물처럼.<br><br>
    발소리가 벽장 앞에서 멈췄다. 그리고 그대로 서 있다. 오래 있을 모양이다.`,
  o:[
    { l:'① 숨을 반으로 쪼갠다 — 아주 얕게, 아주 느리게.', k:'steady', dc:22, wake:1,
      ok:`숨을 반으로 줄였다. 들이쉬는 데 넷을 세고 멈추는 데 넷, 내쉬는 데 넷. 그 반으로. 다시 그 반으로.<br><br>가슴이 거의 안 움직인다. 머리가 맑다. 이상하게 맑다. 벽장 밖 숨소리가 들린다. 저쪽은 크게 쉰다. 저쪽도 듣고 있다. 이쪽 숨을 찾고 있다.<br>찾지 못했다. 오래 서 있다가 발소리가 갔다.<br><br>숨도 나눠 쉬는 것이다. 한 모금을 열로 쪼개면 열 배를 버틴다. 그동안 몸은 소리를 내지 않는다. 몸이 그 쪼갬을 스스로 해냈다. 벽장 문을 열었을 때 공기가 아직 반이나 남아 있었다.`,
      ng:`숨을 줄였다. 그런데 공기가 너무 빨리 줄어든다. 머리가 핑 돈다. 눈앞에 하얀 점이 떠다닌다.<br><br>참다가 크게 한 번 들이켰다. 소리가 났다. 문틈 너머 숨소리가 멈췄다.<br><br>문틈으로 눈 하나가 들어왔다. 이쪽 눈 바로 앞에. 깜빡이지 않는다. 한참 보다가 물러갔다. 문을 열지는 않았다. 아직은 아니라는 듯이.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-18, spirit:-26 } },
    { l:'② 문틈에 입을 대고 바깥 공기를 마신다.', k:'sense', dc:22,
      ok:`문틈에 입술을 댔다. 바깥 공기가 가늘게 들어온다. 차다. 숨이 산다.<br><br>문틈 너머 발이 보인다. 맨발이다. 발가락이 이쪽을 향해 있다. 그 발이 숨 쉬는 쪽으로 돌아서 있지 않다. 반대쪽을 본다. 맞은편 벽장을. 동료가 숨은 쪽을.<br><br>문틈으로 아주 작게 손톱을 그었다. 긁는 소리. 발이 홱 이쪽으로 돌았다. 동료 쪽을 놓아주었다. 이쪽 숨을 찾다가 끝내 못 찾고 갔다.`,
      ng:`입을 댔다. 공기가 들어온다. 그 공기에 숨이 섞여 있다. 남의 숨이다. 바깥에서도 문틈에 입을 대고 있다.<br><br>이쪽이 들이쉬면 저쪽이 내쉰다. 저쪽 숨을 마시고 있다. 비린 물 냄새가 폐까지 들어온다.<br><br>입을 뗐다. 기침이 터지려는 걸 손으로 막았다. 그날 하루 내내 숨에서 물 냄새가 났다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-22, spirit:-24 } }
  ] },

{ at:'A1', t:'대기실 — 순서를 기다리는 의자',
  x:`방청객 대기실에 의자가 줄지어 놓였다. 맨 앞 의자 앞에 입장문이 있다. 문 위에 불이 들어온다. 다음 분.<br><br>
    불이 들어올 때마다 의자 줄이 한 칸씩 앞으로 밀린다. 저절로. 맨 앞 의자는 문 안으로 들어간다. 빈 의자다. 돌아오지 않는다.<br>
    일행이 앉은 의자는 줄 중간이다. 일어나려는데 의자가 엉덩이에 붙었다.<br><br>
    기다리는 일이라면 안다. 기다리는 쪽이 대부분 이긴다. 대부분.`,
  o:[
    { l:'① 움직이지 않는다 — 엉덩이를 떼지 말고 차례를 흘려보낸다.', k:'steady', dc:23,
      doom:{ title:'다음 분', what:'의자째 입장문 안으로 실려 갑니다', dc:18, sec:45,
        text:`가만히 앉아 있었다. 불이 들어온다. 줄이 밀린다. 한 칸. 또 한 칸. 버티면 끝날 거라고 생각했다.<br><br>맨 앞이 됐다. 입장문이 열린다. 안이 환하다. 박수 소리. 의자가 미끄러져 들어간다. 엉덩이가 붙어 있다. 발을 바닥에 박았다. 신발이 끌린다.<br>문틀을 손으로 잡았다. 손가락이 하얗게 질린다. 안에서 장갑 낀 손들이 이쪽 무릎을 다정하게 끌어당긴다. 어서 와요.`,
        dieText:`입장문이 닫혔다. 문 위 불이 꺼졌다가 다시 들어왔다. 다음 분.<br><br>줄이 한 칸 밀렸다. 대기실 맨 끝에 의자가 하나 새로 놓였다. 빈 의자다.<br>문 너머에서 박수가 터졌다. 한 사람 몫만큼 오래.` },
      ok:`가만히 앉아 숨을 세었다. 불이 들어올 때마다 줄이 밀린다. 밀릴 때 몸에 힘을 뺐다. 저항하면 의자가 더 붙는다.<br><br>세 칸 밀렸을 때 줄 뒤쪽에서 동료가 의자를 하나 빼냈다. 줄에 틈이 생겼다. 밀리는 힘이 그 틈에서 멈칫한다. 그 틈에 엉덩이가 떨어졌다.<br><br>의자를 버리고 일어섰다. 빈 의자들만 계속 앞으로 갔다. 하나씩 문 안으로. 박수가 났다. 빈 의자에도 박수는 났다.`,
      win:{ exp:20, dream:3 } },
    { l:'② 줄 맨 끝 의자를 빼내 줄을 끊는다.', k:'fix', dc:22,
      ok:`몸을 비틀어 뒤를 봤다. 줄 맨 끝 의자에 손이 닿는다. 그걸 끌어 줄에서 빼냈다.<br><br>줄이 끊기자 밀리던 힘이 멎었다. 앞으로 갈 뒤가 없다. 엉덩이가 떨어졌다. 다들 일어섰다.<br><br>문 위 불이 계속 깜빡였다. 다음 분. 다음 분. 아무도 가지 않았다. 빼낸 의자 밑에 이름표가 붙어 있었다. 보호자.`,
      ng:`손을 뻗는데 닿지 않는다. 한 뼘 모자라다. 줄이 밀린다.<br><br>의자째 몸을 틀어 뒤로 기울였다. 의자가 넘어졌다. 이쪽도 같이. 엉덩이는 그대로 붙어 있다. 넘어진 채로 줄이 끌고 간다. 바닥에 등이 쓸린다.<br><br>동료들이 의자 다리를 붙잡아 멈췄다. 겨우 떼어 냈다. 옷 엉덩이 쪽이 의자에 남았다. 등 살갗도 조금.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-28, mind:-16 } }
  ] },

{ at:'A2', t:'양호실 — 마른 침대',
  x:`양호실은 물이 턱까지다. 그런데 침대 하나가 물 위에 떠 있다. 마른 이불이 덮였다. 커튼이 반쯤 쳐졌다.<br><br>
    다리에 열이 오른다. 아까 긁힌 데가 부었다. 열이 무엇을 데려오는지 안다. 졸음, 그다음 헛것.<br>
    약장이 벽 높이 있다. 유리문이다. 안에 마른 약초 다발이 걸렸다.<br><br>
    커튼 너머에서 누가 숨을 쉰다. 아파서 누운 사람의 숨이다. 이쪽처럼.`,
  o:[
    { l:'① 침대에 오르지 않는다 — 약장에 매달려 약초만 꺼낸다.', k:'luck', dc:22,
      ok:`침대를 지나쳐 약장으로 갔다. 선반 모서리에 매달렸다. 유리문을 열었다. 약초 다발이 말라 있다. 오래 걸어 둔 것이다.<br><br>한 다발을 입에 물었다. 커튼 너머 숨소리가 멈췄다. 일어나 앉는 소리가 난다. 이불 스치는 소리.<br><br>약초를 물고 양호실을 나왔다. 뒤에서 침대가 물 위를 미끄러져 문 앞까지 따라왔다. 커튼이 걷혀 있었다. 아무도 없는 이불이 이쪽 모양으로 불룩했다.`,
      ng:`매달렸는데 선반이 기울었다. 약장째 이쪽으로 쏟아진다. 약병들이 물에 떨어져 깨진다.<br><br>깨진 병에서 나온 것이 물에 퍼진다. 쓴 냄새. 열이 확 오른다. 눈앞이 흔들린다. 커튼이 걷히고 누가 손짓한다. 누워, 누워.<br><br>동료가 머리채를 잡아 끌어냈다. 이쪽은 침대 쪽으로 헤엄치고 있었다. 이불 한 귀퉁이를 쥐고서.`,
      win:{ exp:16, dream:2, item:'약초 뭉치' }, lose:{ hp:-24, mind:-18 } },
    { l:'② 물속에 선 채 열을 버틴다 — 찬물로 열을 내린다.', k:'steady', dc:22, wake:1,
      ok:`침대에도 약장에도 가지 않았다. 문간에 서서 부은 다리를 물에 담갔다. 찬물이 열을 빨아 간다. 오래 담갔다.<br><br>졸음이 왔다. 손등을 물어 쫓았다. 헛것이 왔다. 커튼 너머 숨소리가 이쪽 귀에 대고 속삭였다. 누우면 괜찮아. 대답하지 않았다.<br>열이 내렸다. 다리 붓기가 가라앉았다.<br><br>몸 안의 열도 바깥 추위처럼 버티는 것이다. 무엇이 오는지 알면 하나씩 받을 수 있다. 졸음엔 아픔으로, 헛것엔 셈으로. 열이 몸을 데려가려 할 때 붙잡고 있을 손잡이가 생겼다.`,
      ng:`다리를 담갔다. 찬물이 열을 빨아 간다. 너무 많이. 이빨이 덜덜거린다. 열과 추위가 같이 왔다.<br><br>기대려고 손을 뻗은 데가 침대 모서리다. 마른 이불이 손을 감싼다. 따뜻하다. 몸이 저절로 오른다. 반쯤 올랐다.<br><br>커튼 너머 손이 이쪽 이마를 짚었다. 차다. 열이 확 내렸다. 동시에 정신이 꺼졌다. 깼을 때 동료들 품이었다. 이마에 손바닥 모양 얼음이 맺혀 있었다.`,
      win:{ exp:22, dream:3, hp:8 }, lose:{ hp:-26, spirit:-22 } }
  ] },

{ at:'A', t:'나가기 전 — 마지막 한 입',
  x:`남은 것이 한 입이다. 말린 것 손가락 한 마디.<br><br>
    마지막 한 입은 아낀다. 나가는 문 앞에서 먹는다. 그 전에 먹으면 문까지 못 간다.<br>
    쉬는 자리 가장자리에 누가 앉아 있다. 처음 밤에 몫을 셀 때 하나 많던 그것이다. 이제는 보인다. 무릎을 끌어안고 이쪽을 본다.<br><br>
    손을 내민다. 작은 손이다. 손바닥이 위를 본다.`,
  o:[
    { l:'① 마지막 한 입을 쥐고 내주지 않는다.', k:'steady', dc:22, wake:1,
      ok:`한 입을 주먹에 쥐었다. 내주지 않았다. 그것과 눈을 맞추고 고개를 저었다.<br><br>손이 내밀어진 채 오래 있었다. 이쪽도 오래 주먹을 쥐고 있었다. 누가 먼저 지치나. 이쪽은 늘 기다리는 쪽이다.<br>손이 천천히 내려갔다. 그것이 일어나 어둠으로 갔다. 그 뒤로 몫을 세면 다섯이었다.<br><br>나누는 것만 사는 법이 아니다. 지킬 것을 끝까지 쥐는 것도 사는 법이다. 무엇을 나누고 무엇을 쥘지 가르는 손이 단단해졌다. 그 손으로 쥐면 빼앗기지 않는다.`,
      ng:`쥐었다. 내주지 않았다. 그것이 손을 거두지 않는다. 대신 다른 손이 하나 더 나왔다. 둘. 셋.<br><br>둘러싼다. 다 손바닥을 위로 하고. 쉬는 자리 가장자리가 손으로 빽빽하다. 하나도 다가오지는 않는다. 그저 내밀고 있다.<br><br>새벽까지 주먹을 쥐고 앉아 있었다. 손가락이 펴지지 않았다. 아침에 펴 보니 한 입이 손바닥 안에서 젖어 녹아 있었다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-20, spirit:-24 } },
    { l:'② 반으로 나눠 반을 손바닥에 올려 준다.', k:'bond', dc:22,
      ok:`칼로 반을 냈다. 손가락 반 마디. 그것의 손바닥에 올려 주었다.<br><br>그것이 한참 내려다본다. 손바닥 위 조각을. 그리고 입에 넣었다. 오래 씹는다. 아껴 먹는 소리. 이쪽과 같은 소리다.<br><br>다 먹고 그것이 일어섰다. 쉬는 자리 바깥쪽으로 걸어가 거기 앉았다. 등을 이쪽으로 하고. 밤새 그 자리에 앉아 바깥을 봤다. 지키는 사람처럼.`,
      ng:`반을 올려 주었다. 그것이 받아 쥐었다. 그리고 다시 손을 내민다. 나머지 반을.<br><br>안 주자 그것이 운다. 소리 없이. 눈물이 바닥을 적신다. 젖은 바닥이 넓어진다. 쉬는 자리 전체가 물에 잠긴다. 발목까지.<br><br>남은 반을 던져 주었다. 물이 빠졌다. 아무것도 안 남았다. 문까지는 굶고 갔다.`,
      win:{ exp:18, dream:3, spirit:6 }, lose:{ hp:-22, mind:-18 } }
  ] },

{ at:'A', t:'쉬는 자리 — 옮겨진 잠자리',
  x:`아침에 깨면 잠자리가 조금씩 옮겨져 있다. 한 뼘씩. 매일.<br><br>
    바닥에 끌린 자국이 있다. 이쪽 발뒤꿈치에서 시작해 어둠 쪽 문간으로. 자는 동안 누가 발목을 쥐고 끌었다.<br>
    자리를 골랐다. 오늘은 문간에서 제일 먼 자리다. 그래도 자국은 문간을 향한다.<br><br>
    문간 너머가 까맣다. 오늘 밤이면 거기 닿는다.`,
  o:[
    { l:'① 몸을 끈으로 기둥에 묶고 잔다.', k:'steady', dc:22, wake:1,
      ok:`허리에 끈을 감아 기둥에 묶었다. 매듭은 이쪽만 아는 꼬임. 신발을 신은 채, 발을 문간 반대쪽에 두고 누웠다.<br><br>한밤에 발목이 당겨졌다. 끈이 팽팽해졌다. 허리가 끈에 걸린다. 몸이 둘로 당겨진다. 기둥 쪽과 문간 쪽으로. 기둥이 버틴다. 매듭이 버틴다.<br>한참 당기다 놓았다. 문간 쪽에서 신경질 난 듯 문 닫히는 소리가 났다.<br><br>자는 동안에도 몸은 어딘가에 붙어 있어야 한다. 기둥이든 사람이든. 붙들어 맬 데를 찾는 눈이 생겼다. 어디서 자든 먼저 기둥을 본다. 그다음에 눕는다.`,
      ng:`묶고 잤다. 한밤에 끈이 팽팽해졌다가 툭 끊어졌다. 매듭이 아니라 끈 가운데가 끊겼다. 이빨로 끊은 자리다.<br><br>발목이 끌린다. 눈을 떴다. 어둠 속에서 손 둘이 발목을 쥐고 있다. 문간까지 반 뼘이다.<br><br>발로 차고 기었다. 손이 놓였다. 기둥을 끌어안고 새벽을 기다렸다. 발목에 손가락 자국이 열 개다. 아이 손이다. 아이 둘.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-24, spirit:-24 } },
    { l:'② 문간에 짐을 쌓아 막는다.', k:'fix', dc:22,
      ok:`잠들기 전에 짐을 다 문간에 쌓았다. 돌도 굴려 왔다. 문간이 허리 높이까지 막혔다.<br><br>한밤에 발목이 당겨졌다. 끌려간다. 한 뼘, 두 뼘. 발이 짐더미에 닿았다. 멈췄다. 문간 너머로 넘어갈 길이 없다.<br><br>발목을 쥔 손이 짐더미를 더듬는다. 넘어갈 틈을 찾는다. 없다. 손이 놓였다. 아침에 짐더미 맨 위 짐 하나가 비어 있었다. 대신 가져간 것이다.`,
      ng:`쌓았다. 그런데 한밤에 끌려간 쪽이 문간이 아니다. 반대쪽 벽이다. 벽 밑에 틈이 있다. 거기도 문간이었다.<br><br>발이 벽 틈에 들어갔다. 발목, 정강이. 틈 안은 젖었다. 차다. 동료들이 깨서 붙잡았다.<br><br>빼냈다. 신발이 없다. 양말도. 맨발에 젖은 손자국이 줄줄이 찍혀 있다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-26, mind:-16 } },
    { l:'③ 깨어 있다가 끌린 자국을 따라가 본다.', k:'sense', dc:23,
      doom:{ title:'문간 너머', what:'문간 너머 어둠으로 발목을 잡혀 끌려갑니다', dc:18, sec:45,
        text:`그 밤 자지 않았다. 불을 들고 바닥의 자국을 따라갔다. 문간까지. 문간 너머로 자국이 이어진다. 한 걸음 넘었다.<br><br>너머는 방이다. 바닥에 잠자리가 줄지어 펴져 있다. 이불마다 누가 누워 있다. 다 발이 문간 쪽이다. 다 끌려와 누운 자세다.<br>빈 잠자리가 하나 있다. 돌아서는데 발목이 잡혔다. 이불 밑에서. 끈다. 빈 잠자리 쪽으로. 등이 바닥에 끌린다. 불이 떨어져 굴렀다.`,
        dieText:`아침에 쉬는 자리의 잠자리 하나가 비었다.<br><br>바닥에 자국이 새로 났다. 이번엔 문간에서 이쪽으로. 무엇이 이쪽을 향해 끌려왔다가 도로 간 자국이다.<br>그날 밤 남은 사람들은 다 발을 문간 반대쪽에 두고 잤다. 그래도 아침마다 한 뼘씩 옮겨져 있었다.` },
      ok:`자지 않았다. 불을 들고 자국을 따라 문간까지 갔다. 문간 너머를 불로 비췄다. 넘지 않았다.<br><br>너머에 잠자리가 줄지어 펴져 있다. 이불마다 누가 누웠다. 다 발이 문간 쪽이다. 빈 잠자리가 하나. 머리맡에 이쪽 신발과 똑같은 신발이 놓였다.<br><br>불을 거두고 문간에 돌을 쌓았다. 그 밤부터 자국은 더 늘지 않았다. 돌 앞에서 멈춘 자국만 매일 아침 하나씩 새로 났다.`,
      win:{ exp:20, dream:3 } }
  ] },

{ at:'A', t:'나가는 길 — 주머니를 다시 센다',
  x:`나가는 문이 보인다. 그 앞에서 멈췄다. 주머니를 뒤집었다.<br><br>
    생존가는 들어갈 때 센 것을 나갈 때 다시 센다. 불, 칼, 끈, 먹을 것. 순서대로.<br>
    셋은 맞다. 먹을 것은 없다. 그런데 하나가 더 나온다. 젖은 명찰이다. 이쪽 이름이 수놓였다. 학년, 반 칸은 비었다.<br><br>
    명찰 뒤에 바늘이 꽂혀 있다. 실 끝이 주머니 안쪽 어딘가로 이어져 있다.`,
  o:[
    { l:'① 실을 끊고 명찰을 버린다.', k:'steady', dc:22,
      ok:`칼로 실을 끊었다. 명찰을 문간에 내려놓았다. 이름이 바닥을 보게.<br><br>실 끝이 주머니 안에서 꿈틀하다가 멈췄다. 따라온 것이 끊겼다. 무엇이 실 끝을 쥐고 있었는지는 모른다.<br><br>문을 나섰다. 등 뒤에서 명찰이 뒤집히는 소리가 났다. 이름이 위를 보게. 다음에 올 때 찾기 쉽게.`,
      ng:`실을 끊었다. 그런데 끊긴 실이 다시 길다. 주머니 안쪽에서 계속 나온다. 당길수록 나온다.<br><br>실 끝을 따라 손을 넣었다. 주머니가 깊다. 팔꿈치까지 들어간다. 안이 젖었다. 물이 고였다. 안에서 무엇이 손가락을 쥐었다.<br><br>팔을 빼냈다. 실은 손가락에 감겨 있다. 감긴 데가 하얗게 불었다. 문을 나와서도 실이 손가락에서 풀리지 않았다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-22, spirit:-24 } },
    { l:'② 하나씩 다시 센다 — 소리 내어.', k:'sense', dc:22,
      ok:`문 앞에 다 펴 놓고 소리 내어 셌다. 불. 칼. 끈. 하나씩 손으로 짚으며.<br><br>명찰 차례에 짚지 않았다. 세지 않았다. 셈에 넣지 않으면 가진 것이 아니다. 명찰을 두고 셋만 다시 넣었다.<br><br>문을 나서는데 동료가 이쪽 주머니를 보고 말했다. 거기 뭐가 젖어 있다고. 주머니에서 물이 한 방울 떨어졌다. 그것뿐이었다.`,
      ng:`소리 내어 셌다. 불. 칼. 끈. 그리고 입이 저절로 하나를 더 셌다. 이쪽 이름을.<br><br>명찰이 따뜻해졌다. 실이 팽팽해진다. 주머니 안쪽에서 당긴다. 문 반대쪽으로.<br><br>명찰째 주머니를 칼로 도려냈다. 천 조각이 바닥에 떨어져 문 반대쪽으로 끌려갔다. 어둠 속으로 천천히. 그날 이후 그 옷은 다시 입지 못했다.`,
      win:{ exp:16, dream:3 }, lose:{ mind:-20, spirit:-22 } }
  ] }

]);

// ── 결계술사 (warder) · 마력
kJob('warder', 'A', [

{ at:'A', t:'쉬는 자리 — 금 안쪽의 발자국',
  x:`쉬기 전에 금을 그었다. 손끝에 마력을 묻혀 바닥에 둥글게. 다 안에 들였다. 다섯이다.<br><br>
    아침에 보니 금 안쪽에 발자국이 있다. 젖은 맨발이다. 잠든 사람들 머리맡을 하나씩 돌았다. 금 밖으로 나간 자국은 없다.<br>
    결계술사는 금이 밖을 막는다는 걸 안다. 안에 이미 있던 것은 금이 모른다.<br><br>
    발자국 끝이 금 안쪽 가장자리에서 멈췄다. 지금도 거기 서 있는 모양으로. 보이지 않는다.`,
  o:[
    { l:'① 마력을 써서 금을 안쪽으로 좁혀 다시 긋는다.', k:'steady', dc:22, cost:{ mana:28 }, wake:1,
      ok:`옛 금 안쪽에 새 금을 그었다. 한 뼘 좁게. 그 안쪽에 또. 한 바퀴 그을 때마다 마력이 손끝에서 빠져나간다.<br><br>금이 좁아질 때마다 발자국 끝이 밀려난다. 좁아진 금이 안에 든 것을 고른다. 사람은 남고 사람 아닌 것은 금과 금 사이에 남는다. 세 번째 금에서 바깥 금과 새 금 사이 바닥에 물기가 번졌다. 거기 서 있다.<br><br>금은 밖을 막는 것만이 아니었다. 안을 고르는 것이다. 좁혀 긋는 손이 무엇을 남기고 무엇을 밀어낼지 정한다. 그 고름이 손끝에 붙었다. 금과 금 사이의 물기가 한나절 뒤에 말랐다. 밀려난 것이 갔다.`,
      ng:`좁혀 긋는데 금 하나가 이쪽 발을 지나갔다. 발 하나가 금 밖이 됐다.<br><br>그 발목을 무엇이 쥐었다. 금과 금 사이에서. 차고 젖었다. 이쪽을 바깥 것으로 고른 것이다. 이쪽 손으로 그은 금이.<br><br>금을 지우고 다시 그었다. 마력이 바닥까지 긁혔다. 발목에 쥔 자국이 남았다. 금 모양으로 둥글게.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-18, spirit:-24 } },
    { l:'② 발자국을 처음부터 따라 읽는다.', k:'gaze', dc:22,
      ok:`발자국 시작점을 찾았다. 금 안쪽 한가운데다. 거기서 생겼다. 밖에서 들어온 게 아니다.<br><br>그 자리 바닥에 작은 웅덩이가 있다. 손바닥만 하다. 금을 그을 때 미처 못 봤다. 밑으로 깊다. 금 안에 구멍이 하나 있었다.<br><br>웅덩이 둘레에 작은 금을 하나 더 그었다. 금 안의 금. 그날 밤 발자국은 그 작은 금 안을 맴돌다 아침에 끊겼다.`,
      ng:`따라 읽는데 발자국이 이쪽 발 앞에서 끝난다. 이쪽 신발 코에 닿아서.<br><br>발자국 크기를 봤다. 이쪽 발이다. 맨발로 찍은 이쪽 발. 신발을 벗은 기억이 없다.<br><br>신발을 벗어 봤다. 발바닥이 젖어 있다. 그날 밤 신발 끈을 이중으로 묶고 잤다. 아침에 끈이 풀려 있었다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-16, spirit:-22 } },
    { l:'③ 금을 지우고 다른 자리로 옮긴다.', k:'sense', dc:23,
      doom:{ title:'지운 금', what:'금이 지워진 자리에서 바깥 손들에게 끌려갑니다', dc:18, sec:50,
        text:`신발로 금을 지웠다. 한쪽만. 나갈 틈을 냈다.<br><br>그 틈으로 바깥 것들이 먼저 들어왔다. 밤새 금 밖에 서 있던 것들이다. 금 안의 것만 생각했다. 금 밖은 잊었다.<br>손이 여럿 이쪽 소매를 쥔다. 틈으로 당긴다. 틈이 좁다. 어깨가 걸린다. 걸린 어깨째 당긴다. 등 뒤에서 동료들이 금을 다시 잇는 소리가 들린다. 이쪽은 이미 금 밖이다.`,
        dieText:`쉬는 자리에 금이 다시 이어졌다. 둥글게. 안에 넷이 앉았다.<br><br>금 바깥 바닥에 다른 금이 하나 그어져 있다. 아주 작다. 사람 하나 웅크린 크기다. 안쪽에서 그은 금이다.<br>그 작은 금 안에 아무것도 없다. 금은 아직 희미하게 빛난다. 마력이 다 빠질 때까지.` },
      ok:`금을 지우기 전에 바깥부터 봤다. 금 밖에 발자국이 없다. 밤새 아무것도 오지 않았다. 안의 것뿐이다.<br><br>신발로 금 한쪽을 지우고 다섯이 한꺼번에 빠져나왔다. 다른 자리에 새로 그었다. 안에 든 것은 옛 금 안에 남았다.<br><br>옛 금이 열린 채로 남았다. 아침 내내 그 틈 앞에 젖은 발자국이 서성였다. 나올 줄을 모른다. 금 안에서 태어난 것은 금 밖을 모른다.`,
      win:{ exp:20, dream:3 } }
  ] },

{ at:'A1', t:'방청석 — 무대 끝의 금',
  x:`방청석 맨 앞줄에 일행이 앉았다. 무대가 코앞이다. 방청 규칙이 벽에 붙었다. 자리에서 일어나지 않기.<br><br>
    등 뒤에서 의자 삐걱이는 소리가 일제히 난다. 뒷줄 빈 의자들이 일어서려 한다. 무대 쪽으로 몰려가려는 기척이다.<br>
    무대 끝과 맨 앞줄 사이는 한 걸음이다. 몰리면 그 한 걸음에 일행이 깔린다.<br><br>
    금은 밖을 막는다. 오늘은 막을 데가 등 뒤에 수백 석이다.`,
  o:[
    { l:'① 마력을 써서 객석 둘레에 금을 긋는다 — 자리에 있으라고.', k:'steady', dc:22, cost:{ mana:28 }, wake:1,
      ok:`일어서지 않고 손만 뻗었다. 맨 앞줄 의자 다리 밑을 따라 마력으로 금을 그었다. 객석 전체를 한 바퀴 둘렀다. 들어오지 말라는 금이 아니다. 거기 있으라는 금이다.<br><br>삐걱이던 의자들이 멎었다. 일어서던 것들이 도로 앉는다. 방석이 눌린다. 수백 개가 한꺼번에. 자리에서 일어나지 않기. 규칙과 금이 같은 말을 했다.<br><br>막는 금만 있는 줄 알았다. 붙들어 두는 금도 있다. 오지 말라고 하는 대신 거기 있으라고 하면 수백도 하나의 금으로 앉힌다. 그렇게 긋는 손이 생겼다. 무대 쪽으로 일행만 조용히 일어섰다.`,
      ng:`금을 두르는데 객석이 너무 넓다. 반쯤에서 마력이 달렸다. 금이 끊겼다.<br><br>끊긴 쪽 의자들이 일어섰다. 무대 쪽으로 쏟아진다. 보이지 않는 것들이 일행 등을 밀고 지나간다. 무릎이 무대 끝에 찍혔다.<br><br>밀려 무대에 엎어졌다. 조명이 켜진다. 박수. 동료들이 발목을 잡아 끌어내렸다. 무릎뼈가 욱신거린다. 객석 끊긴 쪽이 텅 비어 있다. 다들 무대 위에 있다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-26, mind:-16 } },
    { l:'② 일행을 데리고 무대 밑 틈으로 숨는다.', k:'hide', dc:23,
      ok:`무대 앞 가림막을 들추니 무대 밑에 틈이 있다. 일행을 하나씩 밀어 넣고 마지막에 들어갔다. 가림막을 내렸다.<br><br>머리 위로 발소리가 지나간다. 수백 개. 무대 위로 몰려 올라간다. 박수. 노랫소리. 판자 틈으로 먼지가 떨어진다.<br><br>노래가 끝나자 발소리가 객석으로 돌아갔다. 무대 밑 바닥에 분필로 그은 금이 있었다. 낡았다. 누가 여기 먼저 숨었다. 금이 안쪽에서 지워져 있다.`,
      ng:`틈으로 들어가는데 가림막이 걷혔다. 객석 쪽에서 들춘 것이다.<br><br>밑을 들여다보는 얼굴이 거꾸로다. 웃는다. 여기 있었네. 손이 들어와 맨 끝 동료의 발목을 잡는다.<br><br>동료를 끌어당기며 반대쪽으로 기어 나왔다. 무대 옆 어둠으로. 동료 발목에 장갑 자국. 손가락이 넷이다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-18, spirit:-22 } }
  ] },

{ at:'A2', t:'종탑 — 뱃전의 금',
  x:`배가 종탑 둘레를 돈다. 창으로 들어갈 자리를 찾는 중이다. 물이 검다.<br><br>
    배 둘레에 손이 올라온다. 하나씩. 뱃전을 짚으려고. 짚으면 배가 기운다.<br>
    물에는 금을 긋지 못한다. 흐르는 것은 나뉘지 않는다. 그어 봤자 번진다.<br><br>
    뱃전은 나무다. 젖었지만 흐르지는 않는다.`,
  o:[
    { l:'① 마력을 써서 뱃전 둘레를 한 바퀴 긋는다.', k:'steady', dc:22, cost:{ mana:26 }, wake:1,
      ok:`뱃전에 손끝을 대고 한 바퀴 돌았다. 배 위에서 기어가며. 젖은 나무에 마력이 스민다. 금이 뱃전을 따라 둥글게 감긴다.<br><br>손 하나가 뱃전을 짚다가 멈칫했다. 금에 닿은 손가락이 하얗게 김을 낸다. 미끄러져 물로 돌아갔다. 다른 손들도 뱃전 한 뼘 앞에서 맴돈다.<br><br>금은 땅에만 긋는 줄 알았다. 물 위에서는 물 위에 뜬 것에 긋는다. 금이 바닥이 아니라 물건을 따라간다. 배가 움직이면 금도 같이 간다. 손끝이 그걸 알아들었다. 그 뒤로 이쪽 금은 서 있는 자리에만 묶이지 않았다.`,
      ng:`긋는데 뱃전이 너무 젖었다. 마력이 나무에 안 붙고 물방울을 따라 흘러내린다.<br><br>금이 번진다. 번진 금 틈으로 손이 올라와 뱃전을 짚었다. 배가 기운다. 물이 넘어온다. 이쪽 무릎까지.<br><br>노로 손을 쳐 냈다. 배가 바로 섰다. 바닥에 물이 고였다. 고인 물속에 작은 손자국들이 아직 남았다. 뱃바닥을 짚은 자국이다. 안쪽에서.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-24, spirit:-22 } },
    { l:'② 노로 물을 쳐서 손들을 쫓는다.', k:'break', dc:22,
      ok:`노를 들어 수면을 내리쳤다. 물이 튄다. 손들이 움찔 가라앉는다. 소리가 종탑에 부딪혀 돌아온다.<br><br>세 번 쳤다. 손들이 물러났다. 그 틈에 창틀에 배를 댔다.<br><br>창을 넘으며 돌아봤다. 수면에 동그란 물결이 번진다. 노가 친 자리마다. 물결 가운데서 손 하나가 올라와 물결을 지운다. 지우고 또 지운다. 흔적을 싫어하는 모양이다.`,
      ng:`내리쳤는데 노가 물에 박혀 안 빠진다. 물속에서 노 끝을 무엇이 쥐었다.<br><br>당긴다. 노를 놓지 않으면 같이 간다. 놓았다. 노가 물속으로 스르르 들어갔다. 하나뿐인 노다.<br><br>손으로 물을 저어 창틀까지 갔다. 손이 물에 닿을 때마다 다른 손이 스쳤다. 창을 넘었을 때 손바닥이 퉁퉁 불어 있었다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-22, mind:-18 } }
  ] },

{ at:'A', t:'복도 — 낡은 금 너머에서 기다리는 것',
  x:`복도 바닥을 가로질러 금이 그어져 있다. 낡았다. 마력이 거의 빠졌다. 그래도 아직 금이다.<br><br>
    금 너머에 무엇이 서 있다. 불이 닿는 데 바로 바깥이다. 금 앞에서 멈춰 있다. 금이 그것을 막고 있다. 아니면 그것이 금을 지키고 있다.<br>
    결계술사는 남이 그은 금을 읽는다. 이건 이쪽에서 저쪽을 막으려고 그은 금이다. 이쪽에 있던 사람이 그었다.<br><br>
    길은 그 금 너머로 이어진다.`,
  o:[
    { l:'① 금을 넘지 않고 벽 따라 옆길을 찾는다.', k:'sense', dc:22,
      ok:`금 앞에서 멈추고 벽을 더듬었다. 옆벽에 문이 하나 있다. 칠이 벗겨져 벽과 같은 색이다. 금이 그어진 이유가 이거다. 옛사람은 이 문으로 갔다.<br><br>문을 열고 들어가 금 너머 복도를 비켜 갔다. 벽 너머로 그것이 금 앞에 그대로 서 있는 숨소리가 났다.<br><br>문 안쪽 벽에 분필 글씨. 넘지 마. 그 밑에 다른 손글씨. 넘었다. 그 밑은 비었다.`,
      ng:`벽을 더듬었다. 아무것도 없다. 더듬는 사이 손이 금 위를 지나갔다. 팔꿈치까지.<br><br>금 너머에서 손가락이 이쪽 손가락에 깍지를 낀다. 반가운 듯이. 따뜻하다. 사람 손처럼.<br><br>팔을 확 거둬들였다. 손가락 사이가 젖어 있다. 그날 내내 손이 남의 손처럼 무거웠다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-16, spirit:-24 } },
    { l:'② 마력을 써서 금을 데리고 넘는다 — 걸음마다 새 금을 이어 긋는다.', k:'steady', dc:23, cost:{ mana:30 }, wake:1,
      ok:`옛 금 바로 앞에 새 금을 그었다. 이쪽을 둘러싸는 작은 둥근 금. 일행을 그 안에 붙였다. 한 걸음 나가며 앞쪽을 지우고 앞쪽에 새로 그었다. 한 걸음, 지우고, 긋고.<br><br>금이 걷는다. 이쪽과 같이. 옛 금을 넘을 때도 이쪽은 여전히 금 안이다. 그것이 바로 옆에 섰다. 숨소리가 금에 닿아 끊긴다. 손이 금 언저리를 더듬다 미끄러진다.<br><br>금은 그어 둔 자리에만 있는 줄 알았다. 지우고 긋는 손이 빠르면 금이 사람을 따라온다. 둘레가 몸에 붙었다. 복도 끝에서 돌아보니 바닥에 둥근 자국이 줄줄이 찍혀 있었다. 발자국처럼.`,
      ng:`걸음마다 금을 이어 그었다. 그런데 넷째 걸음에서 지우는 손이 긋는 손보다 빨랐다. 한순간 금이 없었다.<br><br>그 한순간에 그것이 들어왔다. 둥근 금 안에. 이쪽 일행 사이에. 숨소리가 바로 옆에서 난다. 누구 옆인지 모른다.<br><br>복도 끝까지 그대로 걸었다. 금 안에 여섯이 걷는 걸음 소리가 났다. 끝에서 금을 풀자 다섯이었다. 하나가 언제 나갔는지 모른다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-20, spirit:-24 } },
    { l:'③ 낡은 금을 그냥 넘어 지난다.', k:'evade', dc:23,
      doom:{ title:'넘지 마', what:'금 너머의 것에게 손목을 잡혀 끌려갑니다', dc:18, sec:45,
        text:`금을 넘었다. 한 발. 아무 일도 없다. 두 발.<br><br>뒤에서 금이 빛났다. 낡은 금이 마지막 마력을 짜낸다. 이쪽을 바깥으로 셌다. 금 이쪽에 있던 사람은 이제 저쪽 것이다.<br>그것이 손목을 잡았다. 다정하게. 오래 기다린 손이다. 당긴다. 복도 저 안쪽으로. 뒤에서 동료들이 금 앞에 멈췄다. 넘어오지 못한다. 넘으면 같이 저쪽이 된다.`,
        dieText:`복도 바닥의 금 너머에 무엇이 둘 서 있다. 불이 닿는 데 바로 바깥에.<br><br>남은 사람들은 옆벽의 문을 찾아 돌아갔다. 문 안쪽 벽에 손글씨가 하나 늘었다. 넘었다.<br>낡은 금은 그날로 빛이 다 빠졌다. 그래도 아무도 다시 넘지 않았다.` },
      ok:`넘기 전에 금을 다시 봤다. 이쪽에서 저쪽을 막는 금이다. 넘는 순간 이쪽은 저쪽이 된다. 그러니 넘으면서 이쪽 발밑에 바로 다른 금을 그었다. 저쪽을 이쪽으로 만드는 금.<br><br>넘었다. 낡은 금이 뒤에서 빛났다가 이쪽 새 금에 막혀 꺼졌다. 그것이 손을 뻗다가 멈췄다. 이쪽은 아직 이쪽이다.<br><br>복도 끝까지 갔다. 그것은 낡은 금 앞에 그대로 서서 이쪽 반대쪽을 지켰다. 금을 지키는 게 그것의 일이었다.`,
      win:{ exp:20, dream:3 } }
  ] },

{ at:'A', t:'쉬는 자리 — 금 밖에서 부르는 이름',
  x:`금을 긋고 그 안에 앉았다. 밤이 깊다.<br><br>
    금 밖에서 이름을 부른다. 동료 이름이다. 하나씩. 다정하게. 엄마가 아이를 부르는 목소리로.<br>
    금은 대답하는 사람을 지키지 못한다. 대답하면 금을 건너간 것이다. 몸은 안에 있어도.<br><br>
    제일 어린 동료가 입술을 달싹인다. 졸린 눈이다.`,
  o:[
    { l:'① 마력을 써서 금 안쪽에 둘째 금을 긋는다 — 소리를 가두는 금.', k:'fix', dc:22, cost:{ mana:27 },
      ok:`바깥 금 안쪽에 둘째 금을 그었다. 이번엔 소리를 가두는 금이다. 옛 무늬에서 배운 것이다. 안의 소리가 안에서 맴돈다. 밖의 소리는 안 들어온다.<br><br>부르는 소리가 뚝 끊겼다. 금 안이 조용해졌다. 너무 조용하다. 서로 숨소리가 크게 들린다.<br><br>어린 동료가 눈을 감았다. 잠들었다. 대답할 소리를 듣지 못하면 대답하지 않는다. 금 밖에서 입 모양만 계속 움직였다. 이름. 이름.`,
      ng:`둘째 금을 그었다. 그런데 소리가 이미 안에 들어와 있다. 금 안에서 이름이 울린다. 가둔 소리가 빠져나가지 못하고 맴돈다.<br><br>어린 동료 이름이 금 안에서 계속 불린다. 점점 크게. 동료가 귀를 막는다. 막아도 안에서 난다.<br><br>금을 지웠다. 소리가 흩어졌다. 동료가 울면서 대답했다. 네. 금 밖에서 누가 웃었다. 그 동료는 그 뒤로 이름을 불러도 한 박자 늦게 돌아봤다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-20, spirit:-22 } },
    { l:'② 어린 동료 입을 손으로 막고 함께 버틴다.', k:'bond', dc:22,
      ok:`어린 동료 옆으로 가 입을 손바닥으로 막았다. 다른 손으로 어깨를 감쌌다. 동료가 이쪽 손바닥에 대고 숨을 쉰다. 뜨겁다.<br><br>밖의 목소리가 더 다정해진다. 왜 대답 안 하니. 동료가 몸을 떤다. 이쪽 손바닥이 젖는다. 눈물이다.<br><br>새벽에 목소리가 그쳤다. 손을 뗐다. 동료가 이쪽 손바닥을 한참 쥐고 있었다. 금 밖 바닥에 무릎 자국 하나. 밤새 거기 무릎 꿇고 불렀다.`,
      ng:`입을 막았다. 그런데 막힌 입 대신 동료 손이 올라간다. 손을 든다. 대답하는 손이다.<br><br>금 밖에서 그 손을 봤다. 반가운 듯이 손을 흔든다. 동료 손이 금 쪽으로 뻗는다. 팔꿈치, 어깨. 몸이 기운다.<br><br>둘이 같이 뒤로 넘어졌다. 손이 금 안으로 돌아왔다. 손끝이 하얗게 얼어 있다. 금 밖 공기가 그만큼 찼다.`,
      win:{ exp:16, dream:2, mind:6 }, lose:{ hp:-22, spirit:-24 } }
  ] },

{ at:'A1', t:'무대 바닥 — 이름이 적힌 표시',
  x:`무대 바닥에 테이프로 붙인 표시가 빼곡하다. 엑스 자. 각자 설 자리다. 표시마다 작게 이름이 적혔다.<br><br>
    금을 긋는 눈에는 표시도 금이다. 아주 작은 금. 사람 하나 설 만큼을 나눈다.<br>
    무대 한가운데 새 표시가 있다. 테이프가 반짝인다. 이름이 적혔다. 이쪽 이름이다.<br><br>
    발이 그쪽으로 간다. 무대에 서 본 적이 없는데 설 자리를 안다.`,
  o:[
    { l:'① 표시를 읽는다 — 누가 언제 붙였는지.', k:'gaze', dc:22,
      ok:`쪼그려 앉아 테이프를 봤다. 끝이 손톱으로 뜯겼다. 손으로 붙였다. 아래 다른 표시가 겹쳐 있다. 그 아래 또. 같은 자리에 표시가 일곱 겹이다.<br><br>맨 아래 것에 적힌 이름은 지워졌다. 그 위 것도. 이쪽 이름은 맨 위다. 이 자리는 계속 사람을 바꾼다.<br><br>표시를 밟지 않고 가장자리로 돌아 무대를 건넜다. 발이 계속 그쪽으로 기울었다. 끝까지 버텼다.`,
      ng:`읽으려고 다가가다가 신발 끝이 표시에 닿았다. 한 귀퉁이만.<br><br>조명이 켜졌다. 이쪽 머리 위에서만. 박수. 무대 감독이 손가락을 접는다. 셋, 둘. 발이 표시 한가운데로 미끄러져 들어간다.<br><br>동료가 허리를 끌어안고 넘어뜨렸다. 표시 밖으로. 조명이 꺼졌다. 신발 밑창에 테이프가 붙어 있다. 이쪽 이름이 거꾸로 찍혔다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-18, spirit:-22 } },
    { l:'② 마력을 써서 표시 둘레에 금을 그어 자리를 닫는다.', k:'fix', dc:22, cost:{ mana:25 },
      ok:`멀찍이서 손을 뻗어 표시 둘레에 금을 그었다. 표시보다 한 뼘 넓게. 그 자리를 닫았다. 아무도 들어갈 수 없는 자리로.<br><br>발이 그쪽으로 당기던 힘이 멎었다. 설 자리가 닫혔다. 서라는 말이 들리지 않는다.<br><br>무대 감독이 헤드셋을 만지작거린다. 손가락을 접었다 폈다 한다. 닫힌 자리 앞에서 셈을 못 끝낸다. 그 사이에 무대를 건넜다.`,
      ng:`그었는데 금이 테이프에 미끄러진다. 반짝이는 테이프가 마력을 튕긴다.<br><br>튕긴 마력이 이쪽 발목으로 돌아왔다. 발목에 둥근 금이 감겼다. 이쪽 자리가 된 것이다. 이제 어디에 서든 그 자리다.<br><br>발목 금을 손톱으로 긁어 지웠다. 살갗이 같이 벗겨졌다. 그날 내내 발목이 화끈거렸다. 이름을 불리는 것처럼.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, mind:-16 } }
  ] },

{ at:'A2', t:'기숙사 — 문지방 안쪽의 금',
  x:`아홉 시 종이 울렸다. 호실 점호다. 일행은 407호에 들어와 있다. 열쇠 소리가 복도를 따라온다.<br><br>
    사감은 문간에 서서 방 안을 센다. 방 안에 있는 것을 다 센다. 셈이 맞지 않으면 맞을 때까지 데려간다.<br>
    407호 문 옆 명패에 열두 명이라고 적혔다. 침대에 열두 자리. 다 물에 젖은 이불이 불룩하다.<br><br>
    방 안에 열두 자리와 일행 다섯. 열일곱이다.`,
  o:[
    { l:'① 방을 둘로 가르는 금을 긋고 일행을 금 안에 모은다.', k:'steady', dc:22,
      ok:`방 한구석, 창 밑에 둥근 금을 그었다. 물 위로 나온 창틀과 벽에 걸쳐서. 다섯을 그 안에 몰아넣었다. 금 안은 방이 아니다. 방 안의 다른 자리다.<br><br>문간에서 열쇠 소리. 사감이 센다. 손가락으로 하나씩. 침대 열둘. 금 쪽에서 손가락이 멈칫한다. 건너뛴다.<br><span style="color:#8fb3bf;">"407호. 열두 명. 이상 없음."</span><br><br>발소리가 다음 호실로 갔다. 금 안에서 다섯이 한꺼번에 숨을 쉬었다. 셈은 방을 센다. 금 안은 방이 아니다.`,
      ng:`금을 긋는데 물이 무릎까지라 바닥에 안 붙는다. 벽에만 반쯤 걸렸다.<br><br>사감 손가락이 금을 지나 일행을 짚는다. 열셋, 열넷, 열다섯. 열일곱에서 멈췄다. 오래.<br><span style="color:#8fb3bf;">"407호. 열일곱. 다섯 명 초과."</span><br><br>열쇠 소리가 방으로 들어온다. 일행은 창을 넘어 물로 뛰어들었다. 숨을 참고 다음 창까지 헤엄쳤다. 등 뒤에서 이불들이 일제히 일어나 앉는 소리가 났다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, mind:-18 } },
    { l:'② 침대 이불 밑으로 하나씩 숨는다.', k:'hide', dc:23,
      ok:`불룩한 이불 다섯 개를 골라 들췄다. 안이 비었다. 젖은 이불만 사람 모양으로 굳어 있다. 일행이 하나씩 그 밑에 들어갔다.<br><br>사감이 센다. 침대 열둘. 열둘. 맞다. 다섯이 이불 속에서 숨을 참았다. 이불 안쪽이 차고 미끈하다.<br><span style="color:#8fb3bf;">"407호. 열두 명. 취침."</span><br><br>발소리가 갔다. 이불을 걷고 나왔다. 그 침대들 이불이 다시 불룩해졌다. 원래 누워 있던 것들이 돌아왔다. 이쪽이 비켜 준 자리로.`,
      ng:`이불을 들췄다. 비어 있지 않다. 젖은 얼굴이 눈을 뜬다. 자리를 빼앗는 줄 안다.<br><br>그것이 이쪽 손목을 잡고 이불 속으로 당긴다. 같이 눕자는 힘이다. 차가운 이불이 이쪽을 감는다.<br><br>사감 발소리가 문간에서 멈췄다. 이불 속에서 숨을 참았다. 셈이 끝나고 손목이 놓였다. 손목에 이불 결대로 줄무늬 자국이 남았다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-18, spirit:-24 } }
  ] },

{ at:'A', t:'좁은 턱 — 몸에 긋는 금',
  x:`벽에 붙은 좁은 턱을 따라간다. 발 하나 너비다. 밑은 어둠이다. 바닥이 없다.<br><br>
    어둠에서 손이 올라온다. 발목을, 종아리를 더듬는다. 쥐지는 않는다. 아직은. 어디를 쥘지 고르는 손길이다.<br>
    금을 그을 바닥이 없다. 벽은 젖어 마력이 흘러내린다.<br><br>
    남은 데는 이쪽 몸뿐이다.`,
  o:[
    { l:'① 손끝 마력으로 제 정강이와 손목에 금을 긋는다.', k:'steady', dc:22, wake:1,
      ok:`걸음을 멈추고 손끝으로 제 정강이에 금을 그었다. 한 바퀴. 마력이 살갗에 스며 따끔하다. 손목에도. 목에도.<br><br>더듬던 손이 정강이 금에 닿았다. 멈칫. 위로 올라가지 못한다. 금 위쪽은 막혔다. 금 아래 발목만 더듬다가 내려갔다.<br><br>금은 바닥에 긋는 것이었다. 바닥이 없으면 몸에 긋는다. 몸이 금이 되면 이쪽이 어디 있든 거기가 금 안이다. 살갗이 마력을 오래 붙들었다. 턱을 다 건넌 뒤에도 정강이 금이 희미하게 빛났다.`,
      ng:`정강이에 금을 그었다. 그런데 금이 살갗에 안 붙고 땀에 번졌다.<br><br>번진 금 틈으로 손이 올라와 무릎을 쥐었다. 당긴다. 아래로. 벽을 손톱으로 긁으며 버텼다. 손톱 둘이 들렸다.<br><br>뒤 동료가 허리띠를 잡았다. 무릎이 풀렸다. 무릎에 손가락 자국 다섯이 번진 금 모양으로 찍혔다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-26, spirit:-22 } },
    { l:'② 동료들과 허리를 끈으로 이어 묶고 간다.', k:'fix', dc:22,
      ok:`끈을 꺼내 다섯의 허리를 한 줄로 이었다. 하나가 끌리면 넷이 버틴다.<br><br>가운데쯤에서 맨 뒤 동료 발목이 잡혔다. 끈이 팽팽해졌다. 넷이 벽에 붙어 버텼다. 끌던 손이 무게를 재더니 놓았다. 다섯은 무겁다.<br><br>건넌 뒤 끈을 풀었다. 맨 뒤 동료 발목에 손자국. 끈에도 손자국이 있다. 끈을 따라 이쪽까지 오다 멈춘 자국이다.`,
      ng:`묶었는데 끈 하나가 짧다. 사이가 좁아 서로 발을 밟는다. 한 사람이 휘청이자 다 휘청였다.<br><br>그 틈에 손이 올라와 끈을 쥐었다. 가운데를. 당긴다. 다섯이 한꺼번에 기운다.<br><br>칼로 끈을 끊었다. 손이 쥔 데만 끊겨 어둠으로 떨어졌다. 다들 벽에 붙어 숨을 몰아쉬었다. 끈 쥔 손이 끊긴 끈째 한참 아래서 흔들렸다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, mind:-16 } }
  ] },

{ at:'A1', t:'분장실 — 전구 거울의 테두리',
  x:`분장실 거울에 전구가 빙 둘러 박혔다. 몇 개만 켜졌다. 거울 앞에 의자 셋. 거울 속에는 넷이다.<br><br>
    거울 테두리도 금이다. 안과 밖을 나누는 네모난 금. 거울 속은 안이다.<br>
    거울 속 넷째 의자에 누가 앉아 있다. 분장을 한다. 하얀 분을 두드린다. 이쪽 얼굴 모양으로.<br><br>
    거울 속에서 그것이 고개를 돌려 테두리 쪽을 본다. 나올 데를 찾는다.`,
  o:[
    { l:'① 전구 테두리를 따라 금을 덧긋는다 — 안을 가둔다.', k:'steady', dc:22,
      ok:`거울 테두리 전구 사이를 손끝으로 따라 그었다. 네모난 금을 한 겹 더. 거울 속을 거울 속에 두는 금이다.<br><br>전구가 하나씩 켜졌다. 금이 이어질 때마다. 다 켜지자 거울 속 넷째 의자의 것이 손을 멈췄다. 테두리를 본다. 분첩을 내려놓는다.<br><br>거울 속에서 그것이 이쪽을 보며 하얀 얼굴을 다 칠했다. 이쪽 얼굴이다. 그래도 나오지 못한다. 분장실을 나서는데 거울 쪽에서 분첩 두드리는 소리가 오래 났다.`,
      ng:`덧긋는데 전구 하나가 터졌다. 금이 거기서 끊겼다.<br><br>거울 속의 것이 끊긴 자리로 손을 뻗었다. 거울 밖으로 하얀 손가락 끝이 나온다. 분이 묻었다. 이쪽 뺨에 닿았다. 톡.<br><br>물러섰다. 뺨에 하얀 분 자국이 남았다. 닦아도 안 닦인다. 그날 내내 일행이 이쪽 얼굴을 보다 눈을 피했다. 한쪽만 웃는 것 같다고.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-18, spirit:-24 } },
    { l:'② 마력을 묻힌 손바닥으로 거울을 짚어 금을 안쪽에 긋는다.', k:'gaze', dc:23, cost:{ mana:30 },
      doom:{ title:'넷째 의자', what:'거울 속으로 손목을 잡혀 끌려 들어갑니다', dc:18, sec:45,
        text:`손바닥에 마력을 묻혀 거울을 짚었다. 거울 속 쪽에 금을 그으려고. 차다. 유리가 아니다. 물처럼 차다.<br><br>손바닥이 거울에 빠졌다. 손목까지. 거울 속에서 그것이 이쪽 손목을 쥐었다. 분 묻은 손이다. 반갑다는 듯이 꽉.<br>당긴다. 거울 속 넷째 의자 쪽으로. 팔꿈치가 거울에 들어간다. 거울 속 이쪽 얼굴이 하얗게 칠해져 있다. 웃는다. 이쪽 입은 비명을 지르는데.`,
        dieText:`분장실 거울 앞에 의자가 셋이다. 거울 속에는 넷이다.<br><br>넷째 의자에 누가 앉아 분장을 한다. 이쪽 얼굴을 하고. 손에 마력이 희미하게 빛난다. 거울 안쪽에 금을 긋고 있다. 나오지 못하게. 아니면 아무도 들어오지 못하게.<br>전구가 하나씩 꺼졌다.` },
      ok:`손바닥에 마력을 묻혀 거울을 짚었다. 차다. 손이 빠지려 한다. 빠지기 전에 거울 면에 둥근 금을 하나 그었다. 넷째 의자를 둘러서.<br><br>거울 속의 것이 금 안에 갇혔다. 분첩을 든 채 굳었다. 손을 떼자 손바닥에 하얀 분이 묻어 나왔다.<br><br>나오면서 돌아봤다. 거울 속 넷째 의자 둘레에 이쪽이 그은 금이 빛난다. 그 안에서 그것이 금을 손가락으로 따라 그린다. 배우는 중이다.`,
      win:{ exp:20, dream:3 } }
  ] },

{ at:'A2', t:'3학년 2반 — 교단 앞 분필 금',
  x:`교실은 물이 허리까지다. 책상마다 무엇이 앉아 있다. 물에 반쯤 잠긴 등이 반듯하다. 수업 중이다.<br><br>
    칠판 앞 교단 아래 바닥에 분필 금이 그어져 있다. 물속에서도 하얗다. 학생은 넘지 않는 금이다.<br>
    건너편 창문으로 나가려면 교단 위를 지나야 한다. 교단은 금 안쪽이다.<br><br>
    칠판에 분필이 혼자 움직인다. 오늘의 숙제. 자리를 지키세요.`,
  o:[
    { l:'① 분필 금을 읽고 교단 위로만 걷는다.', k:'sense', dc:22,
      ok:`분필 금을 봤다. 교사가 그은 금이다. 교단과 교실을 나눈다. 교단 쪽은 가르치는 자리, 교실 쪽은 앉는 자리.<br><br>일행을 데리고 교단 위로만 걸었다. 교단은 금 안이다. 학생들은 이쪽을 교사로 셌다. 아무도 일어서지 않았다. 다 칠판을 본다.<br><br>창문에 닿았다. 넘으며 돌아보니 칠판 글씨가 바뀌어 있다. 선생님 안녕히 가세요. 등이 서늘했다.`,
      ng:`교단에 오르다 동료 하나가 미끄러졌다. 발이 금 밖, 책상 사이로 빠졌다.<br><br>앉아 있던 것들이 일제히 그쪽으로 고개를 돌렸다. 금 밖은 학생 자리다. 새 학생이 왔다. 옆자리 것이 동료 손을 잡아 빈 의자로 이끈다.<br><br>동료를 교단으로 끌어 올렸다. 동료 손에 분필이 쥐여 있다. 자기도 모르게 받아 쥐었다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-18, spirit:-22 } },
    { l:'② 마력을 써서 분필 금을 덧그어 학생들을 자리에 묶는다.', k:'steady', dc:22, cost:{ mana:28 },
      ok:`물속 분필 금 위에 손끝을 대고 마력으로 덧그었다. 물에 번지지 않게 아주 천천히. 하얀 금이 물속에서 은빛으로 바뀐다.<br><br>책상마다 앉은 것들 어깨가 조금 내려앉았다. 자리에 붙들렸다. 자리를 지키세요. 칠판 글씨와 금이 같은 말을 한다.<br><br>그 사이 교실 가운데를 곧장 가로질렀다. 책상 사이로. 누구도 일어서지 못했다. 손만 뻗었다. 뻗은 손끝이 이쪽 옷깃에 한 뼘씩 모자랐다.`,
      ng:`덧긋는데 물이 흔들려 금이 번졌다. 은빛이 물에 풀려 교실 전체로 퍼진다.<br><br>책상에 앉은 것들이 그 은빛을 맞고 일제히 일어섰다. 자리가 풀렸다. 물 헤치는 소리가 사방에서 온다.<br><br>창으로 뛰었다. 창틀을 넘는데 발목을 잡혔다. 걷어찼다. 발목에 분필 가루가 묻은 손자국이 하얗다. 물에 씻겨도 안 지워진다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-28, mind:-16 } }
  ] },

{ at:'A', t:'쉬는 자리 — 안에서 금을 지우는 손',
  x:`한밤에 사각사각 소리가 난다. 바닥 긁는 소리다.<br><br>
    금 안에서 동료 하나가 엎드려 있다. 눈을 감은 채. 손톱으로 금을 긁는다. 지우고 있다. 아주 천천히.<br>
    금 밖에서 무엇이 기다린다. 숨소리가 그 동료가 긁는 자리 바로 바깥에서 난다. 거기가 곧 열린다.<br><br>
    결계술사는 금이 밖에서는 안 깨진다는 걸 안다. 깨지는 건 늘 안에서다.`,
  o:[
    { l:'① 긁는 손을 붙잡고 깨운다.', k:'bond', dc:22,
      ok:`기어가서 동료 손목을 잡았다. 차다. 다른 손으로 어깨를 흔들었다. 이름을 불렀다. 낮게. 금 밖 숨소리가 그 이름을 따라 한다.<br><br>동료가 눈을 떴다. 자기 손톱 밑에 낀 마력 가루를 본다. 모른다고 한다. 꿈에 누가 문을 열어 달라고 했다고. 문 손잡이를 찾았다고.<br><br>긁힌 자리를 덧그었다. 금 밖 숨소리가 아쉽게 멀어졌다. 동료는 남은 밤 내내 손을 깔고 잤다.`,
      ng:`손목을 잡았다. 동료가 눈을 감은 채 뿌리친다. 힘이 세다. 사람 힘이 아니다.<br><br>손톱이 마지막 한 줄을 긁었다. 금이 열렸다. 찬바람이 들어온다. 무엇이 들어와 이쪽을 지나쳐 갔다. 금 안을 한 바퀴 돌고 나갔다. 무엇을 하나 들고.<br><br>아침에 보니 짐 하나가 없다. 먹을 것이 든 짐이다. 동료 손톱이 다 깨져 있었다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-22, mind:-18 } },
    { l:'② 마력을 써서 그 동료만 따로 작은 금으로 두른다.', k:'steady', dc:22, cost:{ mana:30 },
      ok:`긁는 동료 둘레에 작은 금을 그었다. 바깥 금 안의 또 하나. 동료가 긁는 손이 작은 금에 닿는다. 작은 금을 긁는다. 바깥 금은 무사하다.<br><br>밤새 긁었다. 작은 금이 닳으면 덧그었다. 마력이 바닥까지 갔다. 바깥 금 밖 숨소리는 밤새 기다렸다. 열리지 않는 문 앞에서.<br><br>동이 트자 동료가 손을 멈추고 잠들었다. 깨워서 물었다. 아무 기억이 없다. 손톱 밑이 은빛으로 반짝였다.`,
      ng:`작은 금을 그었다. 그런데 긁던 동료가 고개를 들었다. 눈을 감은 채 이쪽을 본다. 이쪽을 문으로 안다.<br><br>작은 금 안에서 동료가 이쪽 손을 긁는다. 손등을. 문 손잡이를 찾듯이. 손등 살갗이 벗겨진다.<br><br>새벽까지 손을 내주고 버텼다. 바깥 금은 무사했다. 손등이 엉망이 됐다. 동료는 아침에 이쪽 손을 보고 울었다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-26, spirit:-20 } },
    { l:'③ 물을 끼얹어 동료를 깨운다.', k:'fix', dc:21,
      ok:`물병을 열어 동료 얼굴에 끼얹었다. 동료가 컥 하고 깼다.<br><br>손톱 밑을 본다. 금을 본다. 반쯤 지워졌다. 금 밖에서 숨소리가 멈췄다. 기다리던 것이 들킨 줄 안다.<br><br>지워진 데를 덧그었다. 물이 아까웠다. 그래도 물보다 금이 먼저다. 금 밖에서 아주 작게 혀 차는 소리가 났다.`,
      ng:`물을 끼얹었다. 동료가 깨지 않는다. 물이 금 위로 흘렀다. 금이 번졌다.<br><br>물에 번진 금 틈으로 손이 들어왔다. 잠든 동료의 머리채를 쥔다. 당긴다. 금 밖으로.<br><br>다 같이 매달려 끌어당겼다. 머리카락이 한 줌 뽑혔다. 동료는 끝까지 깨지 않았다. 아침에 깨서 머리가 아프다고만 했다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-24, mind:-16 } }
  ] },

{ at:'A', t:'계단참 — 바깥에서 그은 금',
  x:`계단참에서 쉬려는데 바닥에 이미 금이 있다. 일행이 설 자리를 꼭 맞게 두른다.<br><br>
    손끝이 먼저 금을 읽는다. 이 금은 이상하다. 금의 결이 안쪽을 향한다. 밖에서 안으로 그었다. 밖을 막는 금이 아니다. 안을 가두는 금이다.<br>
    이쪽 일행이 오기 전에 그어졌다. 이쪽 일행 크기에 꼭 맞게.<br><br>
    금 밖 계단 위아래에서 기척이 난다. 가둔 것을 가지러 오는 기척이다.`,
  o:[
    { l:'① 금을 처음부터 끝까지 읽는다.', k:'gaze', dc:22, wake:1,
      ok:`금을 따라 손끝을 댔다. 손을 대지 않고 아주 가까이. 결이 느껴진다. 한 번에 그은 금이 아니다. 여러 번 덧그었다. 매번 조금씩 다른 손으로.<br><br>끝과 시작이 만나는 데를 찾았다. 거기가 매듭이다. 금은 매듭에서 제일 약하다. 매듭 바깥쪽에 서서 그 자리를 손톱 끝으로 한 번 그었다. 매듭이 풀렸다. 금이 열렸다.<br><br>남의 금을 읽는 것은 무늬를 보는 일인 줄 알았다. 금마다 매듭이 있다. 맺은 데를 찾으면 푸는 데도 안다. 눈이 금의 결을 따라 매듭으로 곧장 가는 법을 배웠다. 일행이 열린 틈으로 빠져나가는 동안 계단 위 기척이 멈췄다.`,
      ng:`읽는데 결이 자꾸 바뀐다. 보는 동안 누가 덧긋고 있다. 보이지 않는 손이 금을 따라 돈다. 한 바퀴. 또 한 바퀴.<br><br>금이 진해진다. 안의 공기가 무거워진다. 숨이 가쁘다. 계단 위아래 기척이 가까워진다.<br><br>금 밖으로 짐을 던졌다. 보이지 않는 손이 짐 쪽으로 갔다. 그 틈에 넘었다. 넘으며 정강이가 금에 데었다. 짐은 돌아오지 않았다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-22, mind:-16, spirit:-20 } },
    { l:'② 마력을 써서 금을 끊는다.', k:'break', dc:23, cost:{ mana:32 },
      ok:`마력을 손날에 모아 금을 내리그었다. 금과 금이 부딪혔다. 이쪽 마력이 저쪽 금을 자른다.<br><br>쩍. 금이 끊겼다. 끊긴 데서 하얀 연기가 오른다. 계단 위아래 기척이 동시에 멈췄다. 놀란 것이다.<br><br>일행을 데리고 끊긴 데로 빠져나왔다. 손날이 저리다. 마력이 반 넘게 빠졌다. 남이 그은 금은 무겁다. 남의 마음까지 같이 끊어야 해서.`,
      ng:`내리그었는데 저쪽 금이 이쪽 마력을 먹었다. 손날에서 마력이 빨려 나간다. 멈추지 않는다.<br><br>금이 더 진해졌다. 이쪽 마력으로. 이쪽이 이쪽 감옥을 단단하게 만들었다.<br><br>손을 떼고 주저앉았다. 머리가 하얗다. 동료들이 짐을 다 던져 기척을 끌어내고 금을 뛰어넘었다. 이쪽은 업혀서 넘었다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-22, mind:-20 } },
    { l:'③ 금 안에서 그대로 버틴다 — 가지러 오는 것을 기다린다.', k:'steady', dc:23,
      ok:`금 안에 앉았다. 일행을 붙였다. 기다렸다. 가두는 금이라면 열쇠도 있다. 가지러 오는 쪽이 들고 온다.<br><br>계단 위에서 무엇이 내려왔다. 키가 크다. 금 앞에 쪼그려 앉아 손가락으로 금을 지운다. 문을 여는 것이다. 지우는 순간 이쪽 손끝으로 그 자리에 바로 새 금을 그었다. 이쪽 금이다. 밖을 막는.<br><br>그것이 손을 멈췄다. 자기가 연 문이 다른 문이 됐다. 한참 쪼그려 있다가 올라갔다. 남은 밤 내내 계단 위에서 손가락 빠는 소리가 났다.`,
      ng:`기다렸다. 계단 위아래에서 동시에 왔다. 둘이다. 금 양쪽에서 지운다.<br><br>한쪽에 새 금을 그었다. 다른 쪽이 열렸다. 손이 들어와 맨 가장자리 동료를 쥐었다. 다 같이 매달렸다.<br><br>겨우 빼냈다. 동료 팔에 손자국이 길다. 열린 쪽으로 빠져나왔다. 뒤에서 둘이 서로 다투는 소리가 났다. 누구 몫이었는지를.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, spirit:-22 } }
  ] },

{ at:'A1', t:'송출 부스 앞 — 끊긴 소금 선',
  x:`7층 송출 부스 문 앞 바닥에 소금으로 그은 선이 있다. 하얗다. 누가 손으로 뿌렸다. 손 떨린 자국이 그대로다.<br><br>
    선 바깥에 인형탈들이 서 있다. 방글이, 뭉치, 삐뚤이. 선 앞에서 멈춰 있다. 하얀 장갑이 선 바로 위 허공을 쓰다듬는다.<br>
    선 한 군데가 끊겼다. 소금이 쓸려 나갔다. 손가락 셋 너비.<br><br>
    남의 금이라도 이을 수 있다. 소금은 마력을 잘 받는다.`,
  o:[
    { l:'① 마력을 써서 끊긴 데를 잇는다 — 손을 선 위에 대고.', k:'steady', dc:23, cost:{ mana:32 },
      doom:{ title:'끊긴 선', what:'틈으로 뻗은 장갑들에게 끌려 나갑니다', dc:19, sec:45,
        text:`끊긴 데에 무릎을 꿇고 손끝을 댔다. 마력을 흘렸다. 소금 알갱이들이 하얗게 빛나며 서로 붙는다. 한 손가락. 두 손가락.<br><br>셋째 손가락 너비에서 장갑이 이쪽 손목을 쥐었다. 틈은 아직 열려 있었다. 그 틈으로 들어왔다. 손가락 넷이 손목을 감는다. 다정하게.<br>당긴다. 선 밖으로. 이쪽 손이 이은 선 위를 질질 끌려 지나간다. 소금이 다시 쓸려 나간다. 방글이 웃는 얼굴이 내려다본다. 오늘의 친구.`,
        dieText:`송출 부스 앞 소금 선이 다시 끊겼다. 이번엔 손가락 넷 너비다. 사람 손 하나가 지나간 너비.<br><br>선 바깥 인형탈 줄에 하나가 늘었다. 무릎을 꿇은 자세로. 장갑 낀 손끝에 소금이 묻어 있다.<br>그 손이 허공에서 무엇을 계속 잇는 시늉을 한다. 선이 끊긴 데를.` },
      ok:`끊긴 데에 무릎을 꿇었다. 손끝을 대지 않았다. 한 뼘 위에서 마력을 흘렸다. 소금 알갱이가 빛나며 서로 끌려간다. 한 손가락. 두 손가락.<br><br>장갑이 틈으로 뻗어 왔다. 손 위를 지나 이쪽 손목을 노린다. 셋째 손가락 너비가 붙는 순간 장갑 끝이 선에 닿았다. 하얀 연기가 오른다. 장갑이 움찔 물러났다.<br><br>선이 이어졌다. 인형탈들이 한 발씩 물러선다. 웃는 얼굴 그대로. 소금 선 안쪽에서 송출 부스 문손잡이를 잡았다. 차다.`,
      win:{ exp:22, dream:3 } },
    { l:'② 소금 선을 읽는다 — 누가 어떻게 그었는지.', k:'gaze', dc:22,
      ok:`쪼그려 앉아 선을 봤다. 안에서 밖으로 뿌렸다. 부스 안에 있던 사람이 문을 열고 뿌렸다. 그리고 다시 들어갔다. 끊긴 데는 발로 쓸린 자국이다. 안에서 나간 발이다.<br><br>누가 안에서 나갔다. 선을 밟고. 겁이 나서. 그 사람이 장갑들 사이 어디쯤 서 있을 것이다.<br><br>끊긴 데 둘레에 작은 금을 그어 막았다. 소금 선은 안의 사람이 그은 것이다. 안의 사람이 끊었다. 금은 늘 안에서 깨진다.`,
      ng:`읽는데 선이 이쪽 쪽으로 휘어 있다. 선이 아니라 화살표다. 들어오라는.<br><br>고개를 드니 장갑들이 박수를 친다. 소리 없이. 끊긴 데로 손짓한다. 이쪽이 그 틈 바로 앞에 쪼그려 있다.<br><br>물러섰다. 등이 부스 문에 닿았다. 문 안쪽에서 누가 똑똑 두드렸다. 열어 달라고. 아니면 열지 말라고.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-18, spirit:-24 } }
  ] },

{ at:'A2', t:'수영장 — 레인 줄',
  x:`6층 수영장. 물속에 레인 줄이 길게 떠 있다. 하얀 부표가 줄줄이 꿰였다.<br><br>
    레인마다 무엇이 헤엄친다. 끝까지 가서 벽을 짚고 돌아온다. 쉬지 않는다. 레인을 넘지 않는다. 줄이 금이다.<br>
    레인 줄은 오래된 금이다. 물에 떠 있어도 줄은 흐르지 않는다.<br><br>
    건너편 배수로로 가려면 레인 여섯을 가로질러야 한다. 레인과 레인 사이, 줄 위로.`,
  o:[
    { l:'① 레인 줄을 붙잡고 줄 위로만 건넌다.', k:'steady', dc:23,
      doom:{ title:'일곱째 레인', what:'레인 안으로 끌려 들어갑니다', dc:18, sec:45,
        text:`첫 줄을 붙잡았다. 줄 위에 몸을 걸치고 다음 줄로 손을 뻗었다. 줄 위는 어느 레인도 아니다. 금 위다.<br><br>넷째 줄에서 부표 하나가 빠졌다. 줄이 처졌다. 이쪽 몸이 레인 안으로 미끄러졌다. 헤엄치던 것이 벽을 짚고 돌아온다. 이쪽 레인으로.<br>발목을 잡혔다. 레인 방향으로 당긴다. 끝 벽까지, 그리고 다시. 헤엄치는 속도로. 물이 코로 들어온다. 줄이 손끝에서 멀어진다.`,
        dieText:`수영장 레인 하나에 헤엄치는 것이 둘이 됐다.<br><br>나란히 간다. 끝 벽을 짚고 같이 돈다. 하나는 손에 레인 부표를 쥐고 있다.<br>배수로 쪽 물이 계속 당긴다. 레인 안의 것들은 그쪽을 보지 않는다. 벽, 그리고 다시 벽.` },
      ok:`줄을 붙잡았다. 줄 위에 몸을 걸치고 한 줄씩 건넜다. 줄 위는 어느 레인도 아니다. 헤엄치는 것들이 발 아래를 지난다. 줄 하나 사이로.<br><br>넷째 줄에서 부표 하나가 빠져 줄이 처졌다. 몸이 기울었다. 다섯째 줄로 바로 손을 옮겼다. 처진 줄은 금이 약하다.<br><br>여섯째 줄을 넘어 배수로 턱에 손을 짚었다. 돌아보니 헤엄치던 것들이 다 멈춰 있다. 레인 끝에서. 이쪽을 보고. 줄을 넘어온 것을 처음 본 모양이다.`,
      win:{ exp:22, dream:3 } },
    { l:'② 마력을 써서 레인 줄에 금을 입혀 헤엄치는 것들을 묶는다.', k:'fix', dc:22, cost:{ mana:30 },
      ok:`첫 레인 줄에 손을 대고 마력을 흘렸다. 줄을 따라 은빛이 달린다. 부표마다 하나씩 불이 켜진다. 줄이 진짜 금이 됐다. 둘째, 셋째.<br><br>헤엄치던 것들이 레인 한가운데서 멈췄다. 양쪽 금이 진해지자 레인이 좁아진다. 움직이지 못한다. 물속에서 둥둥 떠 있다.<br><br>그 사이 줄을 넘어 다 건넜다. 마력이 바닥났다. 배수로 앞에서 돌아보니 부표 불이 하나씩 꺼진다. 꺼진 레인부터 헤엄이 다시 시작됐다.`,
      ng:`마력을 흘렸는데 줄이 너무 길다. 셋째 줄에서 마력이 끊겼다.<br><br>넷째 레인의 것이 멈추지 않았다. 이쪽 쪽으로 방향을 바꿨다. 레인을 넘는다. 금이 안 된 줄이다.<br><br>물속에서 발을 잡혔다. 레인 줄을 잡고 버텼다. 손바닥이 줄에 쓸려 벗겨졌다. 동료들이 끌어 올렸다. 발목에 물에 불은 손자국이 레인 줄처럼 길게 났다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-30, mind:-16 } }
  ] },

{ at:'A', t:'문간 — 문지방',
  x:`쉬는 방에 문이 하나다. 문지방이 닳았다. 한가운데가 움푹하다. 많이들 넘었다.<br><br>
    밤중에 문 밖에서 노크가 난다. 세 번. 열어 달라는 노크가 아니다. 들어가도 되느냐는 노크다.<br>
    문지방은 오래된 금이다. 들어오라는 말 없이는 못 넘는 금.<br><br>
    노크가 다시 난다. 세 번. 대답을 기다린다. 대답 하나면 된다.`,
  o:[
    { l:'① 문지방에 금을 덧긋고 대답하지 않는다.', k:'steady', dc:22,
      ok:`문지방 움푹한 자리에 손끝을 대고 금을 덧그었다. 닳은 금이 다시 선다. 그리고 입을 다물었다.<br><br>노크가 밤새 났다. 세 번씩. 점점 공손해진다. 들어가도 될까요. 추워요. 하룻밤만. 대답하지 않았다.<br><br>새벽에 노크가 그쳤다. 문을 열었다. 문지방 바깥에 발자국이 가지런하다. 밤새 한 발짝도 안 넘었다. 물어봤을 뿐이다. 묻는 것들이 제일 오래 기다린다.`,
      ng:`덧긋는데 노크에 놀란 동료가 대답했다. 누구세요.<br><br>대답이다. 문지방 금이 흐려졌다. 문이 저절로 열린다. 아주 조금. 찬바람과 함께 무엇이 문지방을 넘었다. 공손하게. 신발을 벗는 소리가 났다.<br><br>그것은 방 구석에 앉아 밤새 있었다. 아무것도 하지 않았다. 아침에 갔다. 동료 신발 한 켤레를 신고.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-18, spirit:-24 } },
    { l:'② 문을 열고 문지방 너머를 직접 본다.', k:'gaze', dc:23,
      doom:{ title:'들어오세요', what:'문지방 너머로 끌려 나갑니다', dc:18, sec:45,
        text:`문을 열었다. 문지방 너머에 아무도 없다. 복도가 어둡다. 이쪽은 문지방 안쪽에 섰다.<br><br>복도 어둠에서 손이 나와 이쪽 손을 잡았다. 악수하듯이. 들어오지는 않는다. 문지방 너머에서 손만. 이쪽이 문을 열었다. 그게 대답이었다.<br>당긴다. 문지방 너머로. 이쪽 발끝이 움푹한 자리에 걸린다. 많이들 여기 걸렸다. 그래서 움푹하다. 발이 넘어간다.`,
        dieText:`문지방 움푹한 자리가 조금 더 깊어졌다.<br><br>밤중에 노크가 났다. 세 번. 들어가도 되느냐는 노크다. 목소리가 낯익다. 일행 중 하나의 목소리다.<br>아무도 대답하지 않았다. 대답하지 않는 법을 다들 그날 배웠다.` },
      ok:`문을 열되 문지방 안쪽 바닥에 손바닥을 짚고 있었다. 이쪽 금에 손을 대고.<br><br>문지방 너머에 아무도 없다. 복도 어둠에서 손이 나왔다. 이쪽 손을 잡으려다 멈췄다. 이쪽 손은 금 위에 있다. 잡으면 금을 잡는다.<br><br>손이 거둬졌다. 문을 닫았다. 노크는 다시 나지 않았다. 문을 열어 줬는데 안 들어왔다. 그쪽도 그건 처음인 모양이다.`,
      win:{ exp:20, dream:3 } }
  ] },

{ at:'A1', t:'부조정실 — 화면 테두리',
  x:`5층 부조정실 벽이 모니터로 덮였다. 화면마다 스튜디오 다른 자리가 나온다. 빈 방청석, 빈 무대, 빈 복도.<br><br>
    한 화면에 이쪽 일행이 나온다. 부조정실 안. 뒤에서 찍었다. 화면 속 일행 뒤에 누가 서 있다. 키가 크다. 고개를 숙였다.<br>
    화면 테두리도 금이다. 안의 것은 안에 있다. 테두리를 넘지 않으면.<br><br>
    화면 유리가 볼록해진다. 안쪽에서 무엇이 얼굴을 대고 민다.`,
  o:[
    { l:'① 화면마다 테두리를 따라 금을 덧긋는다.', k:'fix', dc:22,
      ok:`볼록한 화면부터 테두리를 손끝으로 따라 그었다. 하나, 둘. 모니터가 많다. 볼록해지는 것부터 골라 그었다.<br><br>그은 화면은 볼록함이 가라앉았다. 얼굴이 유리 안쪽에서 미끄러져 내려간다. 아직 안 그은 화면이 대신 볼록해진다. 그쪽으로 손을 옮겼다.<br><br>마지막 화면을 그었을 때 일행이 나오는 화면 속에서 뒤에 서 있던 것이 사라졌다. 고개를 돌렸다. 진짜 뒤에는 아무도 없다. 화면 밖으로 나오지 못했다.`,
      ng:`긋는데 화면이 너무 많다. 하나 그으면 둘이 볼록해진다.<br><br>한 화면 유리가 깨졌다. 안에서 손이 나와 이쪽 손목을 쥐었다. 화면 속으로 당긴다. 손끝이 유리 조각에 베인다.<br><br>모니터 전원선을 뽑았다. 화면이 꺼지며 손이 사라졌다. 손목에 화면 주사선 같은 가는 줄무늬 멍이 남았다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-24, spirit:-20 } },
    { l:'② 화면을 등지고 일행 둘레에 금을 하나 긋는다.', k:'steady', dc:22,
      ok:`화면을 보지 않기로 했다. 등을 돌리고 일행 둘레에 둥근 금을 하나 그었다. 화면 속에서 무엇이 나오든 이 금 안은 이쪽이다.<br><br>등 뒤에서 유리 깨지는 소리가 났다. 하나. 둘. 발소리가 금 앞에서 멈춘다. 숨소리가 목덜미 바로 뒤다. 금 한 뼘 바깥이다.<br><br>다들 앞만 봤다. 금 안에서 부조정실 문까지 금째 옮겨 가며 나왔다. 문을 닫자 안에서 화면들이 다시 켜지는 소리가 났다. 하나씩. 다시 기다린다.`,
      ng:`등을 돌리고 금을 그었다. 그런데 일행 하나가 돌아봤다. 화면을 봤다.<br><br>화면 속 그 동료 뒤에 서 있던 것이 고개를 든다. 화면 밖 동료를 본다. 마주 보는 순간 금 안이 차가워졌다. 무엇이 화면을 타고 그 동료 눈으로 들어왔다.<br><br>동료가 한참 멍하게 서 있었다. 흔들어 깨웠다. 동료는 그 뒤로 화면 비슷한 것만 보면 고개를 돌렸다. 뒤에 누가 있다고.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-20, spirit:-22 } }
  ] },

{ at:'A2', t:'강당 — 이름과 사람 사이',
  x:`강당 관람석 위 마른 줄을 따라 걷는다. 아래 물속에 의자마다 명찰이 떠 있다. 줄이 반듯하다.<br><br>
    명찰 하나가 물 위로 떠올랐다. 줄을 벗어나 이쪽으로 흘러온다. 동료 이름이 수놓였다. 바늘이 꽂혔다. 실 끝이 동료 소매에 닿아 있다.<br>
    무대에서 출석을 부른다. 곧 그 동료 차례다. 명찰이 있으면 대답하게 된다.<br><br>
    금은 늘 땅과 물건 사이에 그었다. 사람과 이름 사이에 그어 본 적은 없다.`,
  o:[
    { l:'① 동료 소매와 명찰 사이 실 위에 금을 긋는다.', k:'steady', dc:22, wake:1,
      ok:`손끝을 실 바로 위에 댔다. 닿지 않게. 실을 가로질러 아주 짧은 금을 그었다. 손가락 한 마디 길이. 이름 쪽과 사람 쪽을 나누는 금.<br><br>실이 금에서 끊기지 않았다. 그런데 금 이쪽의 실이 색이 빠진다. 하얗게. 이름이 사람한테 닿지 않는다. 출석이 그 동료 이름을 불렀다. 동료 입이 열리려다 닫혔다. 대답이 실을 타고 가다 금에서 멈췄다.<br><br>금은 자리와 자리 사이에만 긋는 것이 아니었다. 이름과 사람 사이, 부르는 것과 불리는 것 사이에도 그어진다. 손끝이 그 가는 틈을 찾았다. 명찰은 대답 없이 물속으로 가라앉았다.`,
      ng:`실 위에 금을 그었다. 그런데 금이 실이 아니라 동료 손목을 가로질렀다. 너무 가까웠다.<br><br>동료 손목에 하얀 금이 감겼다. 동료가 이쪽을 낯선 사람 보듯 본다. 이름과 사람 사이가 아니라 사람과 일행 사이를 갈랐다.<br><br>금을 지웠다. 동료가 한참 뒤에야 이쪽 이름을 기억했다. 그 사이 출석이 동료를 불렀다. 동료가 작게 대답했다. 네. 명찰이 동료 가슴에 붙었다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-20, spirit:-24 } },
    { l:'② 마른 줄 맨 끝으로 돌아가 명찰을 피한다.', k:'sense', dc:22,
      ok:`실을 칼로 끊지 않았다. 대신 동료를 데리고 마른 줄 맨 끝으로 돌아갔다. 명찰이 실에 끌려 따라온다. 물살을 거슬러서는 느리다.<br><br>관람석 끝 기둥을 돌았다. 실이 기둥에 걸렸다. 명찰이 기둥 너머에 멈춘다. 동료와 이름 사이에 기둥이 섰다.<br><br>출석이 그 동료를 불렀다. 대답이 기둥에 막혔다. 무대에서 결석이라고 했다. 실은 그대로 기둥에 감겨 남았다.`,
      ng:`돌아가는데 실이 짧아진다. 명찰 쪽에서 감고 있다. 동료가 명찰 쪽으로 끌린다.<br><br>실을 끊었다. 끊긴 실 끝이 동료 소매 안으로 쑥 들어갔다. 살갗 밑으로. 동료가 팔을 긁는다. 실이 지나간 자리가 붉게 부푼다.<br><br>출석이 동료를 불렀다. 동료 팔 속에서 대답이 났다. 네. 동료 입은 닫혀 있었다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-22, spirit:-22 } }
  ] },

{ at:'A', t:'불침번 — 금 위에 앉은 것',
  x:`불침번이다. 금 안에서 일행이 잔다. 금은 밤새 빛을 조금씩 잃는다.<br><br>
    한밤에 금 위에 무엇이 앉았다. 정확히 금 위에. 안도 밖도 아닌 자리에. 무릎을 끌어안고.<br>
    금은 안과 밖을 가른다. 금 위는 모른다. 금 위에 앉은 것은 처음 본다.<br><br>
    그것이 안쪽으로 한 뼘 기운다. 잠든 동료 쪽으로.`,
  o:[
    { l:'① 마력을 써서 금을 한 뼘 안쪽에 다시 긋는다 — 그것을 바깥에 남긴다.', k:'steady', dc:22, cost:{ mana:29 }, wake:1,
      ok:`옛 금 한 뼘 안쪽에 새 금을 그었다. 그것을 사이에 두고. 이제 그것이 앉은 자리는 금 위가 아니다. 새 금 바깥이다.<br><br>그것이 고개를 든다. 자리가 바뀌었다. 안도 밖도 아니던 자리가 그냥 밖이 됐다. 기울던 몸이 새 금에 닿아 멈춘다.<br><br>금은 그어 놓으면 끝인 줄 알았다. 금은 옮길 수 있다. 무엇이 금 위에 올라앉으면 금을 그것 밑에서 빼면 된다. 금을 긋는 자리는 늘 이쪽이 정한다. 그 감각이 손끝에 남았다. 그것은 새벽까지 바깥에 앉아 무릎을 끌어안고 있었다.`,
      ng:`안쪽에 다시 그었다. 그런데 그것이 같이 옮겨 앉았다. 새 금 위에. 정확히.<br><br>금을 긋는 대로 따라 앉는다. 금을 아는 것이다. 이쪽보다 더. 세 번 옮겼다. 세 번 따라왔다. 금 안이 점점 좁아진다. 일행 발끝이 금에 닿는다.<br><br>그만뒀다. 그것과 마주 앉아 새벽을 기다렸다. 그것이 이쪽 무릎에 무릎을 붙였다. 아주 차게.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-20, spirit:-24 } },
    { l:'② 그대로 둔다 — 그것을 마주 보며 지킨다.', k:'steady', dc:23,
      ok:`금을 고치지 않았다. 그것 맞은편에 앉아 눈을 맞췄다. 금 위의 것과 금 안의 것.<br><br>그것이 기울다 멈춘다. 지켜보는 눈이 있으면 기울지 못한다. 한 뼘이 반 뼘이 되고, 반 뼘이 다시 한 뼘이 됐다. 밤새 그렇게 오갔다.<br><br>새벽에 그것이 일어섰다. 금을 따라 한 바퀴 걸었다. 금 위를. 그리고 바깥으로 내려섰다. 금이 어디서 약한지 다 밟아 보고 갔다.`,
      ng:`그대로 두고 지켰다. 그런데 졸았다. 한순간이다.<br><br>눈을 뜨니 그것이 금 안쪽에 있다. 잠든 동료 머리맡에. 동료 얼굴을 들여다본다. 숨이 닿을 거리다.<br><br>소리를 지르자 그것이 금 위로 돌아가 앉았다. 동료가 깼다. 꿈에 누가 얼굴을 쓰다듬었다고 한다. 뺨이 하얗게 얼어 있었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-22, spirit:-26 } }
  ] },

{ at:'A', t:'쉬는 자리 — 마력이 바닥난 밤',
  x:`마력이 바닥났다. 손끝을 바닥에 대도 아무것도 안 나온다. 마른 우물이다.<br><br>
    밤이 온다. 금 없이 밤을 나 본 적이 없다.<br>
    어둠 속에서 기척이 모인다. 이쪽에 금이 없는 걸 안다. 금 긋는 소리가 안 났으니까.<br><br>
    결계술사는 마력으로 금을 긋는다. 마력이 아니면 무엇으로 긋는지는 아무도 가르쳐 주지 않았다.`,
  o:[
    { l:'① 칼끝으로 손가락을 그어 피로 금을 긋는다.', k:'steady', dc:23, wake:1,
      ok:`칼끝으로 손가락 끝을 그었다. 피가 맺힌다. 그 손가락으로 바닥에 둥글게 그었다. 피가 모자라 몇 번 더 짰다.<br><br>마력으로 그은 금처럼 빛나지는 않는다. 그런데 기척들이 금 앞에서 멈췄다. 냄새를 맡는다. 이쪽 냄새다. 이쪽이 그은 것이다. 금은 마력이 아니라 긋는 사람이 정하는 거였다.<br><br>손가락이 욱신거린다. 그 욱신거림으로 금이 어디 있는지 안다. 마력이 없어도 금은 그어진다. 몸에서 나오는 것이면 무엇이든. 그걸 안 뒤로 마력이 바닥나는 밤이 두렵지 않았다.`,
      ng:`피로 그었다. 그런데 피 냄새가 기척들을 더 불렀다. 금 앞에 빽빽하다.<br><br>금은 버틴다. 그런데 피가 마르면서 금이 갈라진다. 갈라진 데로 손톱이 들어온다. 손가락을 다시 그었다. 또 그었다.<br><br>새벽까지 손가락 다섯을 다 그었다. 금은 버텼다. 손이 퉁퉁 부었다. 바닥에 그은 금이 이쪽 손금 모양으로 말라붙었다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-28, mind:-16 } },
    { l:'② 남은 소금을 뿌려 금을 친다.', k:'fix', dc:22,
      ok:`짐 밑바닥에서 소금을 털었다. 한 줌도 안 된다. 아껴서 가늘게 뿌렸다. 둥글게. 끊기지 않게.<br><br>소금 금은 마력을 안 먹었어도 금이다. 짠 것을 싫어하는 것들이 있다. 기척 몇이 금 앞에서 물러났다.<br><br>물러나지 않은 기척 하나가 있었다. 소금을 손가락으로 찍어 맛본다. 맛있다는 듯이 쩝쩝거린다. 밤새 금 한쪽을 핥았다. 다 핥기 전에 새벽이 왔다.`,
      ng:`뿌렸는데 바람이 분다. 소금이 날린다. 금이 군데군데 끊긴다.<br><br>끊긴 데로 무엇이 들어와 이쪽 등에 붙었다. 차갑고 축축하다. 떨어지지 않는다. 밤새 등에 업고 앉아 있었다.<br><br>새벽에 떨어졌다. 등이 얼어 감각이 없다. 남은 소금은 다 날아갔다.`,
      win:{ exp:16, dream:2, item:'소금 덩이' }, lose:{ hp:-24, spirit:-22 } },
    { l:'③ 금 없이 버틴다 — 일행을 붙여 앉히고 깨어 있는다.', k:'steady', dc:22,
      ok:`금을 긋지 않았다. 일행을 등과 등을 붙여 둥글게 앉혔다. 다들 바깥을 보게. 사람으로 금을 만든다.<br><br>기척들이 다가왔다. 둥근 사람 금 앞에서 멈춘다. 눈이 열 개다. 다 깨어 있다. 깨어 있는 눈 앞에서는 넘어오지 못한다.<br><br>새벽까지 아무도 자지 않았다. 다들 눈이 붉다. 그래도 다섯이 그대로 다섯이다. 금은 사람이 그었다. 이번엔 사람이 금이었다.`,
      ng:`붙여 앉혔다. 그런데 하나가 졸았다. 둥근 금에 틈이 생겼다.<br><br>틈으로 손이 들어와 조는 동료 어깨를 두드린다. 일어나. 같이 가자. 동료가 일어나려 한다.<br><br>양옆에서 붙잡았다. 동료가 눈을 감은 채 버둥거린다. 새벽에 겨우 깼다. 어깨에 손자국 셋이 하얗게 얼어 있었다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-18, spirit:-22 } }
  ] },

{ at:'A', t:'나가는 길 — 지나온 금들',
  x:`나가는 문이 보인다. 뒤를 돌아봤다.<br><br>
    지나온 길에 이쪽이 그은 금들이 남아 있다. 쉬던 자리마다 둥근 금. 희미하게 빛난다.<br>
    금 안에 무엇이 앉아 있다. 하나씩. 이쪽이 떠난 금 안에. 이쪽이 앉았던 자세로.<br><br>
    금은 긋는 사람이 떠나도 남는다. 남은 금은 다음에 오는 것을 들인다.`,
  o:[
    { l:'① 마지막 문지방에 금을 긋는다 — 아무것도 따라 나오지 못하게.', k:'steady', dc:22, wake:1,
      ok:`나가는 문 문지방에 손끝을 댔다. 남은 마력을 다 모아 금을 그었다. 안에서 밖으로 나오는 것을 막는 금. 처음 긋는 방향이다.<br><br>뒤의 금들 안에 앉아 있던 것들이 일어섰다. 따라오려 한다. 문지방 금 앞에서 멈췄다. 일행은 이미 밖이다.<br><br>금은 늘 이쪽을 지키려고 그었다. 오늘은 바깥을 지키려고 그었다. 이쪽이 지나온 곳을 이쪽이 데리고 나가지 않게. 무엇을 안에 두고 무엇을 밖에 둘지, 그 선을 이제 이쪽이 정한다. 문을 닫았다. 안쪽에서 금 위를 손가락으로 쓰다듬는 소리가 났다.`,
      ng:`문지방에 금을 그었다. 그런데 마력이 모자라 금이 반만 섰다.<br><br>반쪽 금 틈으로 무엇이 따라 나왔다. 이쪽 그림자에 붙어서. 그림자가 조금 진해졌다.<br><br>밖에 나와서도 그림자가 무겁다. 해가 비켜도 그림자가 늦게 따라 움직인다. 반 박자. 금 반쪽만큼.`,
      win:{ exp:22, dream:4 }, lose:{ mind:-18, spirit:-26 } },
    { l:'② 돌아가 지나온 금을 하나씩 끊는다.', k:'break', dc:23,
      ok:`문 앞에 일행을 세워 두고 가까운 금부터 돌아갔다. 신발로 금을 끊었다. 금 안의 것이 이쪽을 올려다본다. 끊기는 순간 연기처럼 흩어진다.<br><br>셋을 끊었다. 넷째 금 안의 것은 흩어지지 않았다. 이쪽을 보고 웃는다. 그 금은 이쪽이 그은 것이 아니었다. 이쪽 금을 흉내 낸 금이다.<br><br>그건 두고 돌아왔다. 문을 나서며 뒤를 봤다. 흉내 낸 금 안에서 그것이 손끝으로 바닥에 새 금을 긋고 있었다.`,
      ng:`돌아가 금을 끊었다. 하나. 끊긴 금 안의 것이 흩어지지 않고 이쪽 다리에 감긴다. 갈 데가 없어진 것이다.<br><br>둘째도, 셋째도. 금을 끊을 때마다 다리에 무게가 늘었다. 걸음이 무거워진다.<br><br>문까지 기다시피 왔다. 문지방을 넘자 무게가 떨어졌다. 뒤에서 금 없는 것들이 문 앞에 모여 섰다. 이쪽이 집을 빼앗은 것들이다.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-24, spirit:-22 } }
  ] }

]);

// ── 외공 수련생 (ironbody) · 내공
kJob('ironbody', 'A', [

{ at:'A', t:'들어가는 길 — 마주 치는 벽',
  x:`들어서기 전에 벽 앞에 섰다. 하루는 몸을 치는 걸로 시작한다. 등으로 벽을 친다. 쿵. 쿵.<br><br>
    열 번째에 벽 너머에서 같은 박자로 쳤다. 쿵. 이쪽이 멈추면 저쪽도 멈춘다. 이쪽이 치면 저쪽도 친다.<br>
    외공 수련생은 맞아야 단단해진다는 걸 안다. 저쪽도 단련하는 모양이다. 이쪽을 상대로.<br><br>
    스무 번째에 등에 닿는 벽이 조금 물렁해졌다. 저쪽에서 민 만큼.`,
  o:[
    { l:'① 박자를 바꿔 친다 — 저쪽이 따라오지 못하게.', k:'steady', dc:22, wake:1,
      ok:`박자를 흐트렸다. 쿵, 쉬고, 쿵쿵, 길게 쉬고. 몸이 정한 박자가 아니라 숨이 정한 박자다.<br><br>저쪽이 따라오다 엇나갔다. 이쪽이 쉴 때 저쪽이 쳤다. 이쪽 등이 벽에 닿지 않은 순간이다. 저쪽 힘이 벽만 밀었다. 물렁하던 벽이 저쪽으로 불룩 밀려나갔다. 너머에서 무엇이 휘청이는 소리가 났다.<br><br>맞는 것은 박자다. 언제 맞을지를 이쪽이 정하면 맞는 쪽이 이긴다. 그 박자를 숨으로 쥐는 법을 등이 알아들었다. 벽 너머는 그 뒤로 조용했다. 등 한가운데가 따뜻했다.`,
      ng:`박자를 바꿨다. 저쪽이 바로 따라왔다. 이쪽보다 먼저. 이쪽이 칠 박자를 이쪽보다 먼저 안다.<br><br>등이 벽에 닿는 순간 저쪽이 세게 밀었다. 벽이 물렁하게 등을 감싼다. 견갑골 사이가 빨려 들어간다. 몸을 앞으로 던져 빠져나왔다.<br><br>등 살갗에 벽 결 자국이 찍혔다. 그날 내내 등이 벽 쪽으로 당겼다. 쉬려고 기댈 때마다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-26, spirit:-20 } },
    { l:'② 내공을 끌어올려 몸을 데우고 벽에서 물러난다.', k:'fix', dc:21, cost:{ qi:25 },
      ok:`단련을 멈췄다. 가부좌를 틀고 숨을 아랫배에 모았다. 내공이 돈다. 등에 남은 벽의 찬 기운을 손끝으로 밀어냈다.<br><br>벽 너머에서 한 번 더 쳤다. 쿵. 이쪽이 대답하지 않았다. 또 쳤다. 쿵. 기다린다.<br><br>일어서서 벽에서 세 걸음 물러났다. 쳐 주지 않으니 저쪽이 혼자 쳤다. 한참. 박자가 점점 빨라졌다. 조급한 소리였다.`,
      ng:`숨을 모으는데 벽에 붙은 등이 안 떨어진다. 찬 기운이 등에서 단전으로 내려온다. 내공이 그 찬 것을 같이 돌린다.<br><br>몸 안이 얼었다. 손끝까지. 이가 맞부딪힌다. 데우려고 돌린 것이 식혔다.<br><br>동료들이 와서 등을 벽에서 떼어 냈다. 살갗이 조금 남았다. 벽에 이쪽 등 모양이 하얗게 얼어 있었다.`,
      win:{ exp:16, dream:2, hp:6 }, lose:{ hp:-24, mind:-16 } },
    { l:'③ 벽에 손바닥을 대고 저쪽을 들어 본다.', k:'sense', dc:23,
      doom:{ title:'벽 너머의 단련', what:'벽 속으로 손목을 잡혀 끌려 들어갑니다', dc:18, sec:50,
        text:`손바닥을 벽에 댔다. 차다. 귀도 댔다. 저쪽에서 숨소리가 난다. 이쪽처럼 고르게. 단련하는 숨이다.<br><br>손바닥 밑 벽이 물렁해졌다. 저쪽에서도 손바닥을 댔다. 맞붙었다. 손가락이 손가락 사이로 들어온다. 벽을 통해서.<br>깍지를 낀 손이 당긴다. 벽 속으로. 팔꿈치가 벽에 잠긴다. 어깨가 벽에 닿는다. 벽이 받아들인다. 저쪽에서 숨소리가 가까워진다. 같이 단련하자는 숨이다.`,
        dieText:`벽에 사람 모양 자국이 남았다. 손바닥을 댄 자세로.<br><br>밤마다 그 벽에서 소리가 난다. 쿵. 쿵. 둘이 같은 박자로 친다.<br>일행 중 누구도 그 벽에 등을 대지 않았다. 박자가 가끔 이쪽을 부르듯 느려졌다.` },
      ok:`손바닥을 대고 귀도 댔다. 저쪽 숨이 고르다. 단련하는 숨이다. 손바닥 밑 벽이 물렁해지려는 순간 손을 뗐다.<br><br>손바닥 자국이 벽에 남았다. 저쪽에서도 대고 있었다. 자국이 둘 겹쳤다. 하나는 이쪽보다 크다.<br><br>그 벽을 피해 쉬었다. 밤새 벽 너머에서 혼자 치는 소리가 났다. 맞아 줄 상대가 없는 단련이 얼마나 지루한지 이쪽은 안다.`,
      win:{ exp:20, dream:3 } }
  ] },

{ at:'A1', t:'분장실 — 분을 바르는 손',
  x:`분장실 의자에 앉아 숨을 골랐다. 다리가 풀렸다. 잠깐만 앉기로 했다.<br><br>
    등 뒤에서 손이 온다. 하얀 장갑이다. 분첩을 들었다. 이쪽 뺨을 두드린다. 톡톡. 분이 하얗게 앉는다.<br>
    거울 속 이쪽 얼굴이 점점 하얘진다. 장갑 낀 다른 손이 입꼬리를 위로 민다. 웃는 얼굴로 만든다.<br><br>
    얼굴도 몸이다. 몸은 단련하면 굳는다.`,
  o:[
    { l:'① 얼굴 근육을 굳혀 밀리지 않는다.', k:'steady', dc:22,
      ok:`이를 물고 얼굴에 힘을 모았다. 뺨, 입꼬리, 눈가. 밀어도 안 밀리게. 몸을 굳히듯 얼굴을 굳혔다.<br><br>장갑이 입꼬리를 민다. 안 올라간다. 다시 민다. 분이 갈라진다. 굳은 살갗 위에서 분이 버티지 못하고 금이 가 떨어진다. 하얀 가루가 무릎에 쌓인다.<br><br>장갑이 멈췄다. 분첩을 내려놓는다. 이 얼굴은 못 웃긴다. 일어서서 거울을 봤다. 분이 다 떨어졌다. 볼에 장갑 손가락 자국 넷이 빨갛다.`,
      ng:`얼굴에 힘을 줬다. 그런데 얼굴은 등보다 약하다. 입꼬리가 조금씩 밀려 올라간다.<br><br>거울 속 이쪽이 웃는다. 웃는 얼굴이 굳는다. 분이 마르면서 그 모양으로. 장갑이 만족스러운 듯 이쪽 머리를 쓰다듬는다.<br><br>동료가 물을 끼얹어 분을 씻어 냈다. 입꼬리가 한참 내려오지 않았다. 볼이 당긴다. 웃음이 얼굴 밑에 남은 느낌이다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-18, spirit:-24 } },
    { l:'② 볼에 닿은 손목을 잡아 꺾는다.', k:'break', dc:22,
      ok:`볼에 닿은 장갑 손목을 낚아챘다. 꺾었다. 장갑 안이 비었다. 천이 접히는 감촉. 그런데 꺾이는 소리는 뼈 소리다.<br><br>분첩이 떨어졌다. 장갑이 꺾인 채 축 늘어진다. 다른 장갑이 그걸 끌고 등 뒤 어둠으로 물러갔다.<br><br>얼굴의 분을 털었다. 꺾은 손에 하얀 실밥이 엉겨 있다. 털어도 손가락 사이에 붙어 있다.`,
      ng:`낚아채려는데 장갑이 먼저 이쪽 손목을 잡았다. 다정하게. 무릎 위에 도로 올려놓는다. 착하지.<br><br>힘을 줘도 손이 안 들린다. 무릎 위에 붙었다. 장갑이 분을 계속 두드린다. 얼굴이, 목이, 손등이 하얘진다.<br><br>동료가 의자째 뒤로 넘어뜨렸다. 손이 풀렸다. 손목에 장갑 자국이 하얗게 얼어 붙었다. 분이 아니다. 서리다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-24, spirit:-20 } }
  ] },

{ at:'A2', t:'종탑 — 찬물에 드는 몸',
  x:`나선 계단이 물에 잠기는 데까지 왔다. 여기서부터는 물속으로 간다. 물이 차다. 손을 넣으니 뼈가 시리다.<br><br>
    찬물은 단련이다. 폭포 밑에서 하는 수련이 있다. 이 물은 폭포보다 차다. 흐르지 않고 고였다.<br>
    물 밑에서 무엇이 위를 본다. 수면 아래 얼굴들이 하얗다. 물에 드는 것을 기다린다.<br><br>
    찬물에 든 몸은 먼저 굳는다. 굳은 몸은 붙잡히기 쉽다.`,
  o:[
    { l:'① 내공을 돌려 찬기를 받아들이고 도로 밀어낸다.', k:'steady', dc:22, cost:{ qi:28 }, wake:1,
      ok:`물에 들기 전에 숨을 단전에 모았다. 들어갔다. 찬 것이 살갗을 뚫고 들어온다. 막지 않았다. 받아들였다. 내공이 그 찬 것을 싣고 한 바퀴 돌아 손끝, 발끝으로 내보낸다.<br><br>몸이 굳지 않는다. 찬물이 들어왔다 나간다. 물 밑 얼굴들이 다가오다 멈칫한다. 굳지 않은 몸, 떨지 않는 몸. 잡기 좋은 몸이 아니다.<br><br>찬 것을 막는 줄만 알았다. 들여서 돌려 내보내는 법이 있다. 몸이 물길이 되면 물은 몸을 얼리지 못한다. 그 돌림이 숨에 붙었다. 계단 끝까지 이가 한 번도 맞부딪히지 않았다.`,
      ng:`숨을 모아 들어갔다. 찬 것이 들어온다. 내공이 돌린다. 그런데 너무 차다. 돌리는 속도보다 들어오는 속도가 빠르다.<br><br>단전이 얼었다. 내공이 멈췄다. 몸이 그대로 굳는다. 물 밑 손들이 굳은 다리를 쥐고 쓰다듬는다. 차갑게. 반가운 듯이.<br><br>동료들이 겨드랑이를 끼고 끌어올렸다. 계단참에서 한참 몸을 두드려 녹였다. 다리에 쥔 자국이 파랗다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-28, spirit:-22 } },
    { l:'② 숨을 크게 참고 단번에 뛰어든다.', k:'evade', dc:22,
      ok:`숨을 크게 들이쉬고 단번에 뛰어들었다. 물이 온몸을 때린다. 찬 것이 다 한꺼번에 왔다. 한꺼번에 오면 한 번만 견디면 된다.<br><br>물 밑 얼굴들이 놀라 흩어졌다. 천천히 드는 것에 익숙한 모양이다. 그 사이를 곧장 헤엄쳐 다음 층 문까지 갔다.<br><br>문 너머에서 머리를 내밀었다. 숨이 터진다. 몸이 덜덜 떨린다. 그래도 붙잡히지는 않았다.`,
      ng:`뛰어들었다. 찬물에 심장이 한 번 멎었다. 숨을 놓쳤다. 입에서 거품이 쏟아진다.<br><br>거품을 따라 얼굴들이 몰려온다. 숨이 있는 데로. 손이 이쪽 입을 더듬는다. 남은 숨을 찾는다.<br><br>얼굴을 휘저어 뿌리치고 위로 솟았다. 계단참에 엎어져 물을 토했다. 입술에 남의 손가락 감촉이 오래 남았다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-30, mind:-16 } }
  ] },

{ at:'A', t:'어두운 복도 — 꼬집는 손가락',
  x:`불이 꺼졌다. 다시 켤 때까지 그대로 서 있기로 했다.<br><br>
    어둠 속에서 손가락이 팔을 꼬집는다. 살짝. 살이 있는지 보는 것이다. 앞에서 동료 하나가 소리를 질렀다. 그 소리 쪽으로 무엇이 몰려가는 기척이 난다.<br>
    아파서 소리 내는 것은 살아 있다는 뜻이다. 살아 있는 것을 고르는 손가락이다.<br><br>
    이쪽 팔뚝을 다시 꼬집는다. 이번엔 세게. 비틀어서.`,
  o:[
    { l:'① 아파도 움직이지 않는다 — 소리도 숨도 그대로 둔다.', k:'steady', dc:22, wake:1,
      ok:`아프다. 꼬집힌 데가 타는 것 같다. 그대로 두었다. 숨도 바꾸지 않았다. 근육도 움찔하지 않게 했다.<br><br>매일 맞았다. 맞을 때 몸이 움찔하는 것을 오래 지웠다. 그 지운 것이 지금 쓰인다. 손가락이 더 비튼다. 팔뚝은 그냥 살덩이다. 반응이 없다.<br>손가락이 놓았다. 다음 사람에게 갔다. 이쪽은 고르지 않았다.<br><br>아픔을 받되 움직이지 않는 법. 아픔이 몸에 들어와도 몸이 대답하지 않는다. 맞는 일과 반응하는 일이 둘로 갈라졌다. 불이 다시 켜졌을 때 팔뚝에 꼬집힌 멍이 셋 있었다. 하나도 기억나지 않았다.`,
      ng:`참았다. 그런데 세 번째 비틀 때 숨이 한 번 걸렸다. 아주 작게.<br><br>손가락이 멈췄다. 그리고 다른 손가락들이 왔다. 열, 스물. 팔을, 목을, 옆구리를 꼬집는다. 살아 있는 것을 찾았다.<br><br>불이 켜질 때까지 버텼다. 소리는 끝내 안 냈다. 온몸에 손톱 멍이 촘촘하다. 하나하나가 작은 반달이다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-24, mind:-16, spirit:-20 } },
    { l:'② 내공을 살갗에 모아 손가락을 튕겨 낸다.', k:'fix', dc:22, cost:{ qi:27 },
      ok:`꼬집힌 자리에 내공을 모았다. 살갗이 팽팽해진다. 손가락이 집을 데가 없다. 미끄러진다.<br><br>손가락이 다시 집는다. 미끄러진다. 또. 집히지 않는 살은 살이 아닌 모양이다. 손가락이 망설이다 갔다.<br><br>불이 켜졌다. 팔뚝에 손톱 자국이 하얗게 그어져 있다. 집지 못하고 긁기만 한 자국이다. 피는 안 났다.`,
      ng:`내공을 모으는데 그 열기가 손가락에 닿았다. 따뜻하다. 손가락이 그 따뜻한 데에 멈춘다.<br><br>집지 않는다. 대신 손바닥 전체를 얹는다. 따뜻한 것을 쬐듯이. 손이 여럿 모인다. 이쪽 팔에 손바닥이 겹겹이 쌓인다. 차다. 내공이 빨려 나간다.<br><br>불이 켜질 때까지 팔을 내주고 섰다. 팔이 하얗게 얼었다. 단전이 텅 비었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-22, mind:-18 } },
    { l:'③ 돌아서서 손가락 쪽을 친다.', k:'break', dc:23,
      ok:`꼬집는 손가락 쪽으로 몸을 틀며 팔꿈치를 꽂았다. 무엇에 맞았다. 단단하고 차다. 뼈다.<br><br>어둠 속에서 무엇이 물러난다. 아픈 소리를 내지 않는다. 아픔을 모르는 것이다. 다만 놀랐다. 꼬집은 것이 친 적은 없었던 모양이다.<br><br>불이 켜졌다. 바닥에 손가락 하나가 떨어져 있다. 하얗고 길다. 손톱이 이쪽 살을 머금고 있다.`,
      ng:`팔꿈치를 꽂았다. 허공이다. 몸이 앞으로 쏠렸다.<br><br>쏠린 몸을 손가락들이 받았다. 여럿이. 꼬집지 않는다. 쥔다. 살아 있다는 걸 확인했다. 들어 올린다.<br><br>동료들이 소리를 듣고 끌어내렸다. 옆구리에 손자국이 줄줄이 찍혔다. 들어 올리던 손이다. 어디로 데려가려던 손인지 모른다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, spirit:-20 } }
  ] },

{ at:'A', t:'쉬는 자리 — 손 모양 멍',
  x:`아침에 일어나니 몸에 멍이 새로 생겼다. 맞은 기억이 없는 멍이다.<br><br>
    외공 수련생은 멍을 읽는다. 어디를 어떻게 맞았는지. 무엇으로.<br>
    이 멍은 손 모양이다. 발목, 손목, 목. 쥔 자국이다. 밤새 누가 쥐었다. 잡아끌지는 않았다. 쥐고만 있었다.<br><br>
    동료들 몸에는 없다. 이쪽에만 있다.`,
  o:[
    { l:'① 멍을 하나씩 읽는다.', k:'gaze', dc:22,
      ok:`손목 멍을 봤다. 손가락 넷, 엄지 하나. 엄지가 안쪽이다. 마주 보고 쥔 것이다. 이쪽 얼굴 앞에서.<br><br>목의 멍은 손 둘이다. 세게 쥐지 않았다. 살짝. 숨을 재듯이. 발목 멍은 작다. 아이 손이다.<br><br>밤새 셋이 왔다. 얼굴 앞에 하나, 머리맡에 하나, 발치에 하나. 숨을 재고, 맥을 재고, 다리를 쟀다. 무엇에 맞는지 재는 것이다. 그 밤 잠자리를 옮기고 단전에 숨을 모은 채 잤다.`,
      ng:`읽는데 멍이 움직인다. 보는 동안 손목 멍의 손가락이 조금 조인다. 살갗 밑에서.<br><br>멍이 아니다. 아직 쥐고 있다. 보이지 않는 손이 지금도 손목을 쥐고 있다.<br><br>손목을 털었다. 안 털린다. 반나절 뒤에 손가락 하나씩 풀렸다. 풀린 자리마다 멍이 노랗게 빠졌다. 마지막 엄지만 저녁까지 남았다.`,
      win:{ exp:16, dream:3 }, lose:{ mind:-18, spirit:-24 } },
    { l:'② 내공을 돌려 멍을 풀어 낸다.', k:'fix', dc:22, cost:{ qi:26 },
      ok:`가부좌를 틀고 내공을 멍 자리로 보냈다. 손목, 목, 발목. 뭉친 피를 풀었다. 멍이 퍼런색에서 노란색으로, 다시 살색으로.<br><br>목의 멍이 풀릴 때 무엇이 귓가에서 아쉬운 숨을 쉬었다. 쥐어 둔 자리가 지워진다. 다음에 쥘 자리를 못 찾게.<br><br>멍이 다 풀렸다. 그날 밤 아무도 이쪽을 쥐지 않았다. 다른 동료 손목에 멍이 하나 생겼다. 손가락 넷, 엄지 하나.`,
      ng:`내공을 보냈다. 그런데 멍이 풀리지 않고 번진다. 손 모양이 커진다. 손바닥이, 팔이.<br><br>내공이 멍을 데우자 멍 속의 손도 데워졌다. 손이 살아난다. 손목을 쥐는 힘이 진짜 힘이 된다.<br><br>내공을 멈췄다. 손이 식으며 다시 멍이 됐다. 크기만 두 배가 됐다. 한동안 손목을 천으로 감고 다녔다.`,
      win:{ exp:18, dream:2, hp:6 }, lose:{ hp:-22, spirit:-22 } }
  ] },

{ at:'A1', t:'방청석 — 바람잡이',
  x:`4층 방청석. 바람잡이가 객석 줄 사이를 돈다. 큰 나비넥타이. 얼굴은 그려 넣은 웃음이다.<br><br>
    바람잡이는 앉은 사람마다 볼을 꼬집고 어깨를 친다. 반응을 본다. 움찔하는 사람, 웃는 사람. 그런 사람을 일으켜 세운다. 앞으로 나와 볼 친구.<br>
    반응 없는 사람은 지나간다. 인형처럼 앉은 사람은.<br><br>
    바람잡이가 이쪽 줄에 들어섰다. 셋 앞이다.`,
  o:[
    { l:'① 맞아도 꿈쩍 않는다 — 인형처럼 앉아 있다.', k:'steady', dc:22, wake:1,
      ok:`등을 펴고 손을 무릎에 얹었다. 눈은 무대 쪽. 깜빡이는 것도 늦췄다. 몸을 의자의 일부로 두었다.<br><br>바람잡이가 볼을 꼬집었다. 비틀었다. 어깨를 쳤다. 세게. 또. 이쪽은 아무것도 안 했다. 맞는 것은 몸이 할 일이다. 대답은 안 해도 된다.<br>바람잡이가 고개를 갸웃하고 지나갔다. 다음 동료 볼을 꼬집는다. 동료도 버텼다. 이쪽을 보고 배운 것이다.<br><br>맞는 동안 몸을 가구처럼 두는 법. 받되 내주지 않는다. 몸이 그걸 하나의 자세로 외웠다. 앉은 채로, 선 채로, 누운 채로. 바람잡이가 줄 끝에서 돌아보고 한참 이쪽을 봤다. 끝내 다시 오지 않았다.`,
      ng:`볼을 꼬집혔다. 버텼다. 어깨를 맞았다. 버텼다. 그런데 바람잡이가 귀에 대고 속삭였다. 이쪽 이름을.<br><br>고개가 돌아갔다. 한 치. 바람잡이 그려 넣은 웃음이 더 커졌다. 찾았다. 손을 잡아 일으킨다. 힘이 세다.<br><br>동료 둘이 허리띠를 붙잡고 끌어 앉혔다. 바람잡이가 손을 놓고 아쉬운 듯 손뼉을 쳤다. 볼에 꼬집힌 자리가 퍼렇다. 이름을 들은 귀가 오래 울렸다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-20, spirit:-24 } },
    { l:'② 다가오는 손을 손등으로 쳐 막는다.', k:'evade', dc:22,
      ok:`볼로 오는 손을 손등으로 툭 쳐 냈다. 가볍게. 어깨로 오는 손도. 바람잡이가 웃는다. 장난치는 친구다.<br><br>바람잡이가 다시 손을 뻗는다. 또 쳐 냈다. 세 번. 네 번. 바람잡이 손이 멈췄다. 반응은 반응이지만 웃음이 아니다. 고를 수가 없다.<br><br>바람잡이가 애매한 얼굴로 지나갔다. 손등이 얼얼하다. 친 자리에 하얀 장갑 실밥이 묻었다.`,
      ng:`쳐 냈다. 바람잡이가 손뼉을 친다. 반응이다. 신났다. 다들 보세요, 이 친구 힘이 세요.<br><br>객석 빈 의자에서 박수가 터진다. 조명이 이쪽에 꽂힌다. 바람잡이가 이쪽 손목을 잡아 번쩍 들었다. 이긴 사람 손처럼.<br><br>동료들이 매달려 끌어내렸다. 손목이 꺾였다. 조명이 꺼질 때까지 객석 바닥에 엎드려 있었다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-24, mind:-16 } }
  ] },

{ at:'A2', t:'세탁실 — 감기는 교복',
  x:`4층 세탁실. 젖은 교복이 빨랫줄에 줄줄이 걸렸다. 물이 가슴까지라 아랫단은 물속에서 흔들린다.<br><br>
    지나가는데 교복 소매가 팔에 감긴다. 젖은 천이 살에 붙는다. 하나, 둘. 치마가 다리에 감긴다.<br>
    젖은 천은 마르면서 조인다. 물속에서는 더 무겁다.<br><br>
    교복들이 이쪽으로 몰려든다. 빨랫줄에서 내려와 물속을 미끄러져 온다.`,
  o:[
    { l:'① 근육을 부풀려 감긴 천을 찢는다.', k:'break', dc:22,
      ok:`팔에 감긴 소매를 내버려 두고 숨을 크게 들이켰다. 온몸 근육을 한꺼번에 부풀렸다. 단련으로 키운 몸이 천을 밀어낸다.<br><br>찌익. 소매가 터졌다. 치마 솔기가 터졌다. 젖은 천은 무겁지만 질기지는 않다. 오래 물에 있었다.<br><br>찢어진 교복들이 물속으로 가라앉는다. 천천히. 단추가 떨어져 바닥으로 굴러간다. 단추마다 학교 휘장. 한참 찢었다. 다 찢고 보니 교복 안에 아무것도 없었다.`,
      ng:`부풀렸다. 천이 버틴다. 오히려 더 조인다. 숨을 내쉬자 그만큼 조였다. 다시 들이쉴 데가 없다.<br><br>교복이 겹겹이 감긴다. 가슴, 목. 젖은 깃이 턱 밑을 조인다. 물속으로 끈다. 같이 빨랫줄에 걸리자는 것이다.<br><br>동료가 칼로 천을 갈랐다. 겨우 숨을 쉬었다. 목에 깃 모양 자국이 둘렸다. 단추 자국까지.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, mind:-16 } },
    { l:'② 힘을 빼고 미끄러져 빠져나온다.', k:'evade', dc:22,
      ok:`버티지 않았다. 숨을 내쉬고 몸에서 힘을 다 뺐다. 부풀렸던 근육이 가라앉는다. 몸이 작아진다.<br><br>감긴 소매가 헐거워졌다. 젖은 천은 단단한 것을 조인다. 무른 것은 놓친다. 팔을 비틀어 빼냈다. 다리도.<br><br>빠져나와 빨랫줄 밑으로 지났다. 뒤에서 빈 교복들이 서로 감겨 엉켰다. 이쪽 모양을 한 채로.`,
      ng:`힘을 뺐다. 천이 헐거워진다. 그런데 몸이 같이 가라앉는다. 힘을 뺀 몸이 물에 눕는다.<br><br>그 위로 교복들이 덮인다. 이불처럼. 차고 무겁다. 위로 올라갈 수가 없다. 숨이 끊긴다.<br><br>발로 바닥을 차고 솟구쳤다. 천을 뚫고. 머리가 물 밖으로 나왔다. 교복 한 벌이 등에 붙어 따라 올라왔다. 떼어 내는 데 오래 걸렸다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-26, spirit:-20 } }
  ] },

{ at:'A', t:'계단 — 내려오는 무게',
  x:`좁은 계단을 오른다. 위에서 소리가 난다. 쿵. 쿵. 한 칸씩. 무거운 것이 내려온다.<br><br>
    피할 데가 없다. 계단 폭이 한 사람이다. 위에서 오는 것은 계단을 꽉 채운다.<br>
    외공 수련생은 피할 수 없을 때 하는 일을 안다. 맞을 준비를 한다.<br><br>
    불빛에 발이 보였다. 사람 발이다. 셋. 넷. 발이 계속 늘어난다. 무엇이 사람을 겹겹이 업고 온다.`,
  o:[
    { l:'① 내공을 어깨에 모아 받아 낸다.', k:'steady', dc:23, cost:{ qi:30 },
      doom:{ title:'업힌 무게', what:'내려오는 무게에 깔리고 있습니다', dc:18, sec:45,
        text:`숨을 멈추고 내공을 어깨와 등에 모았다. 일행을 뒤에 두고 맨 앞에 섰다. 받았다.<br><br>무겁다. 사람 무게가 아니다. 겹겹이 업힌 것들이 다 이쪽에게로 내려앉는다. 등에 업히려 한다. 무릎이 한 칸 꺾였다.<br>업힌 것들의 손이 이쪽 어깨를 쥔다. 목을 감는다. 이제 이쪽이 업고 있다. 내려온 것이 이쪽 등에 올라탔다. 무릎이 또 꺾인다. 계단 모서리가 정강이를 판다.`,
        dieText:`계단에서 쿵. 쿵. 소리가 난다. 한 칸씩. 무거운 것이 내려간다.<br><br>불빛에 발이 보인다. 셋. 넷. 다섯. 맨 아래 발이 낯익은 신발이다.<br>그 발은 아주 단단히 계단을 디딘다. 업힌 것들을 다 받고도.` },
      ok:`숨을 멈추고 내공을 어깨와 등에 모았다. 맨 앞에 섰다. 받았다.<br><br>무겁다. 무릎이 한 칸 꺾였다. 거기서 멈췄다. 무게가 등뼈를 타고 허리, 다리, 발로 내려간다. 계단이 받는다. 이쪽은 길이 됐을 뿐이다. 그것이 이쪽에게 업히려고 손을 뻗었다. 등이 단단해서 손이 붙지 않는다.<br><br>무게가 이쪽을 넘어 지나갔다. 위로. 머리 위로 쿵. 쿵. 계속 올라간다. 내려오던 게 아니라 올라갈 데를 찾던 것이다. 이쪽은 계단 한 칸이었다.`,
      win:{ exp:20, dream:3 } },
    { l:'② 일행을 계단참 구석으로 몰고 앞을 막는다.', k:'bond', dc:22,
      ok:`두 칸 아래 계단참으로 일행을 밀어 넣었다. 구석에 붙였다. 앞에 이쪽이 섰다. 등으로 일행을 덮었다.<br><br>무게가 계단참에 내려왔다. 지나간다. 이쪽 등을 스친다. 차고 축축한 발들이 줄지어. 하나가 이쪽 어깨를 밟고 지나갔다. 버텼다.<br><br>다 지나갔다. 어깨에 발자국이 찍혔다. 작은 발이다. 아이 발 위에 어른 발, 그 위에 또. 계단 아래로 쿵. 쿵. 멀어졌다.`,
      ng:`몰아넣는데 계단참이 좁다. 하나가 밖에 남았다. 그 앞에 섰다.<br><br>무게가 내려와 이쪽을 덮쳤다. 등에 매달린다. 손이 목을 감는다. 무겁다. 무릎이 바닥에 닿았다.<br><br>동료들이 같이 떼어 냈다. 하나씩. 손이 많다. 다 떼고 나니 목에 손자국이 겹겹이 남았다. 숨 쉴 때마다 목이 쉭쉭거렸다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-30, mind:-14 } }
  ] },

{ at:'A1', t:'놀이 세트 — 미끄럼틀 탑',
  x:`6층 놀이 세트 가운데 미끄럼틀 탑이 섰다. 노란 관이 빙빙 돌아 내려간다. 다음 계단은 탑 밑 출구 옆이다.<br><br>
    탑 위가 내려가는 유일한 길이다. 관 입구에 그림판. 한 사람씩. 손은 몸에 붙이고.<br>
    관 안에서 아이 웃음소리가 난다. 아래로 아래로 멀어진다. 끝나지 않는다.<br><br>
    관은 좁다. 팔다리를 벌리면 벽에 닿는다.`,
  o:[
    { l:'① 팔다리로 관 벽을 짚어 버티며 천천히 내려간다.', k:'steady', dc:23,
      doom:{ title:'노란 관', what:'미끄럼틀 아래 어둠으로 빨려 내려갑니다', dc:18, sec:45,
        text:`관에 들어갔다. 손바닥과 발바닥으로 벽을 짚었다. 등도. 몸을 버팀목처럼 세웠다. 한 뼘씩 내려간다.<br><br>둘째 굽이에서 발목을 잡혔다. 관 아래에서 작은 손이. 놀자고. 당긴다. 손바닥이 플라스틱에 미끄러진다. 땀이 나서.<br>몸이 미끄러진다. 굽이를 돈다. 또 돈다. 아이 웃음소리가 바로 옆이다. 이쪽도 웃는 것 같다. 관이 어두워진다. 출구는 아까 지났다.`,
        dieText:`미끄럼틀 출구로 공 하나가 굴러 나왔다. 노란색이다.<br><br>관 안에서 웃음소리가 났다. 아래로 아래로. 둘이다.<br>그림판 아래 이름표 칸에 새 이름이 붙었다. 손은 몸에 붙이고.` },
      ok:`관에 들어가 손발과 등으로 벽을 짚었다. 단련한 다리가 버틴다. 한 뼘씩 내려갔다.<br><br>둘째 굽이에서 작은 손이 발목을 잡았다. 당긴다. 버텼다. 벽을 짚은 발에 힘을 더 줬다. 플라스틱이 끽 운다. 손이 한참 당기다 놓았다. 무거운 것은 재미없다.<br><br>출구로 기어 나왔다. 손바닥이 벗겨졌다. 관 안에서 웃음소리가 멀어진다. 아래로. 관이 출구보다 더 밑으로 이어져 있었다.`,
      win:{ exp:20, dream:3 } },
    { l:'② 관 바깥을 타고 내려간다.', k:'evade', dc:22,
      ok:`관에 들어가지 않았다. 관 바깥을 끌어안고 기어 내려갔다. 노란 관이 미끄럽다. 이음새마다 손가락을 걸었다.<br><br>관 안에서 웃음소리가 이쪽을 따라 내려온다. 관 벽 너머에서 손바닥이 플라스틱을 두드린다. 똑똑. 안으로 들어오라고.<br><br>바닥에 발이 닿았다. 관 출구에서 웃음소리가 멎었다. 아무도 나오지 않았다. 출구 안쪽에 작은 손바닥 자국이 줄줄이 찍혀 있다. 다 안에서 밖으로.`,
      ng:`관 바깥을 타다가 이음새에서 손이 미끄러졌다. 떨어졌다. 공 바다 위로.<br><br>공이 받았다. 그런데 공 밑에서 손들이 받았다. 놀자고. 다리를 잡는다. 공 밑으로.<br><br>동료들이 공을 헤치고 끌어냈다. 허리를 바닥 모서리에 찧었다. 일어날 때마다 허리가 끊어질 듯했다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-28, mind:-16 } }
  ] },

{ at:'A2', t:'교실동 — 떠다니는 의자',
  x:`교실동 복도는 물이 허리까지다. 의자가 떠다닌다. 수십 개. 물살도 없는데 움직인다.<br><br>
    의자가 사람 쪽으로 온다. 의자 다리로 들이받는다. 넘어뜨리려는 것이다. 넘어지면 물속이다. 물속에서 의자가 등을 누른다. 앉히듯이.<br>
    몸으로 받으면 받아진다. 받는 것은 몸이 할 줄 안다.<br><br>
    복도 끝까지 의자가 빽빽하다. 일행 맨 뒤 동료가 이미 비틀거린다.`,
  o:[
    { l:'① 맨 앞에서 몸으로 받아 일행 길을 낸다.', k:'steady', dc:22,
      ok:`맨 앞으로 나갔다. 의자가 들이받는다. 가슴으로 받았다. 숨을 내쉬며. 의자 다리가 가슴에 박혔다가 튕겨 나간다.<br><br>다음 의자. 어깨. 다음. 허벅지. 한 걸음에 하나씩 받았다. 받은 의자는 옆으로 밀어 냈다. 뒤에 길이 생긴다. 일행이 그 길로 붙어 온다.<br><br>복도 끝에 닿았다. 가슴과 어깨가 멍투성이다. 멍이 다 의자 다리 네 개 모양이다. 네 개씩 줄지어.`,
      ng:`받았다. 그런데 의자가 하나가 아니다. 둘이 동시에 왔다. 앞과 옆. 옆구리에 박혔다. 숨이 끊겼다.<br><br>무릎이 꺾이며 물에 잠겼다. 등 위로 의자가 올라탄다. 누른다. 바닥 쪽으로. 앉으라는 듯이.<br><br>팔꿈치로 의자를 쳐 내고 솟았다. 갈비뼈가 결린다. 숨을 쉴 때마다 옆구리에서 소리가 난다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-32, mind:-14 } },
    { l:'② 의자를 하나 붙잡아 앉아 띄운다 — 그 위에 올라탄다.', k:'fix', dc:22,
      ok:`들이받는 의자를 붙잡았다. 뒤집어 물 위에 띄우고 올라탔다. 무릎을 꿇고. 균형을 잡았다.<br><br>다른 의자들이 멈칫한다. 의자에 앉은 사람은 들이받지 않는다. 자리에 앉았으니까. 일행에게도 의자 하나씩 붙잡게 했다.<br><br>의자를 타고 손으로 물을 저어 복도를 지났다. 끝에서 내리자 타고 온 의자들이 천천히 교실 쪽으로 떠갔다. 자기 자리로.`,
      ng:`붙잡아 올라탔다. 의자가 기울었다. 이쪽을 앉히려고 바로 선다. 엉덩이가 의자에 붙었다.<br><br>의자가 교실 쪽으로 떠간다. 이쪽을 태우고. 교실 문이 열려 있다. 빈자리가 하나.<br><br>뛰어내렸다. 물에 처박혔다. 의자가 혼자 교실로 들어갔다. 엉덩이가 차다. 젖은 의자 자국이 바지에 남았다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-24, spirit:-22 } }
  ] },

{ at:'A', t:'쉬는 자리 — 끌어안는 잠',
  x:`자다가 깼다. 등 뒤에서 누가 끌어안고 있다. 팔이 가슴을 둘렀다. 차다.<br><br>
    동료가 아니다. 동료들은 앞에서 잔다. 숨소리가 들린다.<br>
    팔이 조인다. 아주 조금씩. 숨을 내쉴 때마다 그만큼. 들이쉴 자리가 줄어든다.<br><br>
    몸은 조이는 것을 버티라고 단련했다. 누가 등 뒤에서 조이는 건 단련한 적이 없다.`,
  o:[
    { l:'① 숨을 다 내쉬고 몸을 줄여 빠져나온다.', k:'evade', dc:22,
      ok:`숨을 끝까지 내쉬었다. 가슴이 줄었다. 팔이 그만큼 따라 조였다. 그 순간 몸을 아래로 미끄러뜨렸다. 어깨를 접고 무릎을 끌어당겨.<br><br>팔 아래로 빠져나왔다. 팔이 빈 데를 조였다. 아무것도 없는 데를 꽉. 그리고 천천히 풀렸다.<br><br>돌아봤다. 아무도 없다. 이쪽이 누웠던 자리에 사람 모양으로 서리가 앉았다. 둘이 겹쳐 누운 모양이다.`,
      ng:`내쉬었다. 팔이 조였다. 빠져나가려 했다. 그런데 팔이 하나 더 있다. 아래쪽에. 허리를 감았다.<br><br>둘이 조인다. 숨이 반밖에 안 들어간다. 소리를 지르려는데 소리가 안 나온다. 숨이 없다.<br><br>앞의 동료가 뒤척이다 이쪽을 봤다. 일어나 이쪽 손을 잡고 끌어냈다. 팔은 없었다. 가슴과 허리에 팔 자국이 하얗게 둘렸다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-26, spirit:-20 } },
    { l:'② 내공을 가슴에 모아 근육을 부풀려 팔을 밀어낸다.', k:'steady', dc:22, cost:{ qi:30 }, wake:1,
      ok:`숨을 들이켜 단전에 모았다. 내공을 가슴과 등으로 밀어 올렸다. 근육이 부푼다. 조이던 팔이 밀린다. 한 치, 두 치.<br><br>팔이 다시 조인다. 그때 숨을 내쉬지 않았다. 내쉬지 않고도 버티는 숨을 썼다. 들이쉰 숨을 아랫배에 붙들어 두고 가슴을 부풀린 채 굳혔다. 조일 틈을 주지 않는다.<br>팔이 한참 버티다 풀렸다. 등 뒤가 비었다.<br><br>조이는 것은 숨을 노린다. 내쉬는 순간을 노린다. 숨을 아랫배에 묶어 두면 가슴은 숨과 상관없이 버틴다. 숨과 몸을 따로 쓰는 법이 생겼다. 다시 누웠다. 숨을 묶은 채로 잤다.`,
      ng:`부풀렸다. 팔이 밀린다. 그런데 부푼 가슴을 팔이 더 반긴다. 꽉 끌어안는다. 큰 것을 안는 것이 좋은 모양이다.<br><br>내공이 빠져나간다. 팔이 내공을 마신다. 따뜻해진다. 이쪽은 식는다.<br><br>새벽에 팔이 풀렸다. 내공이 바닥났다. 손끝이 하얗다. 팔은 다음 날 밤에도 왔다. 따뜻한 데를 기억하고.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-24, mind:-18 } },
    { l:'③ 앞의 동료를 깨워 같이 떼어 낸다.', k:'bond', dc:22,
      ok:`발로 앞 동료 등을 툭 찼다. 동료가 깼다. 이쪽 얼굴을 보고 바로 알았다. 이쪽 가슴에 손을 넣어 보이지 않는 팔을 더듬어 잡았다.<br><br>둘이 같이 당겼다. 팔이 풀린다. 차고 미끄럽다. 동료가 그 팔을 잡은 채 바닥에 눌렀다. 팔이 버둥거리다 사라졌다.<br><br>동료 손바닥이 하얗게 얼었다. 둘이 등을 맞대고 다시 잤다. 등 뒤가 막히니 아무것도 안 왔다.`,
      ng:`동료를 깨웠다. 동료가 일어나 이쪽을 본다. 그리고 이쪽 등 뒤를 본다. 얼굴이 하얘진다. 뒷걸음질 친다.<br><br>무엇을 봤는지 말하지 않는다. 다른 동료들을 깨워 멀리 데려간다. 이쪽은 혼자 남았다. 팔이 더 조인다.<br><br>새벽까지 혼자 버텼다. 동료는 끝내 말해 주지 않았다. 이쪽 등에 업힌 것이 이쪽 얼굴을 하고 있었다는 것을. 나중에 다른 동료가 말해 줬다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-20, spirit:-24 } }
  ] },

{ at:'A', t:'복도 — 이름을 부르는 소리와 아픔',
  x:`복도 저편에서 이쪽 이름을 부른다. 다정한 목소리다. 오래 듣고 싶은 목소리다.<br><br>
    발이 그쪽으로 간다. 한 걸음. 생각하기 전에. 머리가 멍해진다. 따뜻한 물에 잠기는 느낌.<br>
    앞서 간 동료 하나가 이미 저편으로 걷고 있다. 눈이 반쯤 감겼다.<br><br>
    멍한 머리를 깨우는 법을 하나 안다. 아픔이다. 몸에 익은 것.`,
  o:[
    { l:'① 제 허벅지를 주먹으로 친다 — 아픔으로 깨어난다.', k:'steady', dc:22, wake:1,
      ok:`주먹으로 허벅지를 쳤다. 세게. 단련할 때처럼. 아픔이 다리를 타고 올라와 머리를 친다. 멍한 것이 갈라진다.<br><br>목소리가 또 부른다. 또 쳤다. 부를 때마다 쳤다. 아픔이 목소리보다 크다. 목소리가 아픔을 뚫지 못한다.<br>정신이 맑아졌다. 앞서 가던 동료를 뛰어가 붙잡았다. 동료 허벅지도 쳤다. 동료가 비명을 지르며 깼다.<br><br>아픔은 견디는 것이었다. 붙잡는 것이기도 하다. 몸에 아픔을 주면 정신이 몸으로 돌아온다. 아픔을 닻처럼 쓰는 법을 주먹이 알았다. 허벅지가 퍼렇게 부었다. 목소리는 끝내 이쪽을 데려가지 못했다.`,
      ng:`쳤다. 아프다. 그런데 목소리가 그 아픔을 쓰다듬는다. 아프지? 이리 와. 호 해 줄게.<br><br>아픔이 목소리 쪽으로 이쪽을 민다. 더 아프면 더 가고 싶다. 주먹을 멈췄다. 이미 열 걸음 갔다.<br><br>동료 하나가 뒤에서 목덜미를 잡아끌었다. 넘어졌다. 허벅지가 부어 걷지 못했다. 목소리가 한참 아쉬워했다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-22, mind:-18, spirit:-20 } },
    { l:'② 앞서 가는 동료를 뛰어가 붙잡는다.', k:'bond', dc:22,
      ok:`이쪽 발도 끌리는데 뛰었다. 목소리 쪽으로. 동료를 따라잡아 허리를 감았다. 뒤로 당겼다.<br><br>동료가 버둥거린다. 눈을 감은 채. 목소리가 둘을 같이 부른다. 동료를 땅에 눕히고 그 위에 엎드렸다. 무게로 눌렀다.<br><br>목소리가 그쳤다. 동료가 눈을 떴다. 무거우니 비키라고 한다. 이쪽이 아직 이쪽인 걸 그 말로 알았다.`,
      ng:`뛰어가 붙잡았다. 동료가 돌아본다. 눈을 뜨고. 웃는다. 같이 가자.<br><br>동료 손이 이쪽 손목을 쥔다. 힘이 세다. 둘이 같이 목소리 쪽으로 걷는다. 이쪽 발이 이쪽 말을 안 듣는다.<br><br>뒤에서 남은 동료들이 둘을 끌어냈다. 다섯이 뒤엉켜 넘어졌다. 동료 손이 이쪽 손목에서 떨어질 때 살갗이 같이 벗겨졌다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-24, spirit:-22 } },
    { l:'③ 귀를 막고 마보로 서서 버틴다.', k:'steady', dc:22,
      ok:`손바닥으로 귀를 막고 다리를 벌려 앉았다. 마보다. 허벅지가 바닥과 나란하다. 발이 땅에 박혔다.<br><br>목소리가 손바닥을 넘어 들어온다. 작게. 발은 안 움직인다. 마보는 움직이지 않으려고 하는 자세다. 그걸 몇 해 했다.<br><br>다리가 떨릴 때쯤 목소리가 지쳤다. 저편에서 앞서 간 동료가 돌아왔다. 멍하게. 저편에 아무것도 없었다고 했다. 아무것도 없는 데 가 섰다고.`,
      ng:`귀를 막고 마보로 섰다. 발이 박혔다. 그런데 목소리가 발밑에서 난다. 바닥에서.<br><br>발바닥으로 목소리가 올라온다. 다리가 저린다. 마보가 무너진다. 무릎이 바닥에 닿았다. 기었다. 목소리 쪽으로.<br><br>동료가 다리를 붙잡아 끌었다. 손톱이 바닥을 긁었다. 정신이 들었을 때 손톱 셋이 부러져 있었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, mind:-16 } }
  ] },

{ at:'A1', t:'무대 옆 — 빈 인형탈',
  x:`7층 무대 옆에 인형탈이 줄 서 있다. 방글이, 뭉치, 삐뚤이. 다음 순서를 기다린다.<br><br>
    줄 맨 끝 탈 하나가 비었다. 몸통이 축 늘어졌다. 머리는 옆에 놓였다.<br>
    하얀 장갑들이 이쪽 어깨를 잡는다. 빈 탈 쪽으로 데려간다. 탈의 지퍼가 열려 있다. 사람 하나 들어갈 크기다.<br><br>
    장갑들이 이쪽 팔을 접어 소매에 넣으려 한다.`,
  o:[
    { l:'① 몸을 굳혀 접히지 않는다.', k:'steady', dc:22,
      ok:`팔에 힘을 줘 굳혔다. 팔꿈치가 접히지 않는다. 허리도. 무릎도. 몸 전체를 막대처럼 세웠다.<br><br>장갑들이 접으려 한다. 안 접힌다. 소매에 팔이 안 들어간다. 지퍼가 안 닫힌다. 장갑들이 서로 쳐다본다. 손가락을 접었다 폈다 한다.<br><br>빈 탈이 이쪽 몸에 반쯤 걸친 채 미끄러져 떨어졌다. 장갑들이 탈을 주워 줄 끝에 도로 세웠다. 다음 사람을 기다린다. 덜 단단한 사람을.`,
      ng:`굳혔다. 그런데 장갑이 겨드랑이를 간지럽힌다. 힘이 빠졌다. 웃음이 터졌다.<br><br>팔이 접혔다. 소매에 들어갔다. 털 안쪽이 따뜻하다. 머리를 씌우려 한다. 웃음이 멈추지 않는다.<br><br>동료가 지퍼를 찢어 열었다. 굴러 나왔다. 웃음이 한참 뒤에야 그쳤다. 그쳤을 때 배가 아팠다. 웃은 기억이 없었다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-20, spirit:-22 } },
    { l:'② 빈 탈을 찢어 버린다.', k:'break', dc:22,
      ok:`장갑을 뿌리치고 빈 탈 몸통을 두 손으로 쥐었다. 찢었다. 솔기를 따라. 털이 쏟아진다.<br><br>안에서 쪽지가 떨어졌다. 출연자 명단이다. 맨 아래 칸이 비었다. 이쪽 이름을 쓸 칸이다.<br><br>쪽지도 찢었다. 장갑들이 멈췄다. 줄 선 탈들이 일제히 찢긴 탈을 내려다본다. 웃는 얼굴로. 그 틈에 무대 뒤로 빠졌다.`,
      ng:`찢으려 쥐었는데 털 속에서 손이 이쪽 손을 마주 쥐었다. 비었던 탈이 아니다.<br><br>안에 누가 있었다. 아주 마른 것이. 이쪽 손을 잡고 탈 안으로 끈다. 같이 있자고.<br><br>동료들이 뒤에서 당겼다. 손이 빠졌다. 손등에 털이 박혔다. 뽑으니 털이 아니라 머리카락이다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-24, spirit:-22 } }
  ] },

{ at:'A2', t:'체육관 — 줄 선 자리',
  x:`체육관 바닥에 무엇이 줄 서 있다. 물속에서. 학생들이 반듯하게. 체육 시간 차렷 자세다.<br><br>
    호루라기 소리가 물을 울린다. 교사가 줄을 따라 걷는다. 움직이는 학생 앞에서 멈춘다. 그 학생은 물 밑으로 데려간다.<br>
    일행은 철골 아래 공기 줄을 따라가는 중이다. 머리만 내놓고. 몸은 물속이다. 학생들 줄 바로 위다.<br><br>
    교사가 이쪽 아래로 온다. 움직이면 안 된다. 숨도.`,
  o:[
    { l:'① 차렷 자세로 숨을 아랫배에 가두고 멈춘다.', k:'steady', dc:23, wake:1,
      ok:`철골을 붙잡은 채 몸을 곧게 폈다. 차렷. 숨을 한 번 깊이 들이켜 아랫배에 내렸다. 그리고 가뒀다. 가슴이 움직이지 않는다. 수면에 물결 하나 안 인다.<br><br>교사가 바로 아래를 지난다. 고개를 든다. 이쪽 발을 본다. 움직이지 않는 발. 학생 줄과 같다. 지나갔다.<br>한참 뒤에야 숨을 놓았다. 아주 조금씩.<br><br>숨을 아랫배에 가둬 두면 몸은 물건이 된다. 숨 쉬는 몸이 숨 쉬지 않는 몸처럼 선다. 그 멈춤을 원하는 만큼 늘이는 법을 몸이 찾았다. 교사가 줄 끝에서 호루라기를 불었다. 이쪽은 셈에 안 들었다.`,
      ng:`숨을 가뒀다. 그런데 찬물에 몸이 떨린다. 단련으로도 못 막는 떨림이다. 수면에 잔물결이 인다.<br><br>교사가 멈췄다. 고개를 든다. 이쪽 발목을 본다. 손을 뻗었다. 발목을 쥐었다. 아주 정중하게.<br><br>철골을 끌어안고 버텼다. 동료들이 팔을 붙잡았다. 교사 손이 미끄러져 놓였다. 호루라기가 길게 울었다. 발목에 쥔 자국. 그리고 손가락 사이에 낀 듯한 호루라기 줄 자국.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-26, spirit:-22 } },
    { l:'② 줄 끝 쪽 철골로 옮겨 교사를 비켜 간다.', k:'hide', dc:22,
      ok:`교사가 오는 반대쪽 철골로 손을 옮겼다. 천천히. 물결이 안 일게. 일행에게 손짓했다. 하나씩.<br><br>줄 끝 쪽은 공기가 얇다. 코만 내놓고 숨을 쉬었다. 교사가 줄 가운데에서 멈췄다. 누구를 봤다. 물 밑으로 데려간다. 이쪽 일행이 아니다. 원래 줄에 있던 것이다.<br><br>그 틈에 탈의실 문까지 갔다. 돌아보니 줄 하나가 비었다. 그 빈자리 바로 위가 이쪽이 지나온 철골이었다.`,
      ng:`옮기다 손이 미끄러졌다. 물결이 크게 인다.<br><br>호루라기가 짧게 울었다. 교사가 고개를 든다. 줄 선 학생들이 일제히 고개를 든다. 다 이쪽을 본다.<br><br>탈의실 문까지 헤엄쳤다. 물속에서 손들이 발을 스쳤다. 문을 닫았다. 문 너머에서 호루라기가 계속 울렸다. 출석을 부르듯이.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-18, spirit:-24 } }
  ] },

{ at:'A', t:'물웅덩이 — 바닥의 손',
  x:`복도 바닥에 물이 고였다. 발목 깊이다. 넓다. 건너야 한다.<br><br>
    물 밑 바닥에 손이 있다. 바닥에서 자란 것처럼. 손바닥이 위를 본다. 디디는 발을 기다린다.<br>
    앞서 던진 돌 하나를 손이 쥐었다. 바닥 속으로 끌고 들어갔다. 바닥이 돌을 삼키고 다시 평평해졌다.<br><br>
    발목 깊이다. 그래도 발이 잠긴다.`,
  o:[
    { l:'① 마보로 뿌리를 내리며 한 걸음씩 건넌다.', k:'steady', dc:23,
      doom:{ title:'바닥의 손', what:'바닥 속으로 발목을 잡혀 끌려 들어갑니다', dc:18, sec:45,
        text:`첫 발을 디뎠다. 손이 쥐었다. 발목을. 마보로 낮게 앉아 발을 박았다. 뿌리처럼. 버틴다.<br><br>손이 당긴다. 아래로. 발이 버틴다. 그런데 손이 하나 더 쥔다. 정강이를. 또 하나. 무릎을. 바닥에서 손이 줄줄이 자란다. 다 아래로.<br>뿌리를 내린 것이 실수다. 박은 발을 손들이 뿌리째 뽑아 아래로 끈다. 발목이 바닥에 잠긴다. 바닥이 물렁하다. 정강이. 무릎.`,
        dieText:`물웅덩이가 평평하다. 발목 깊이다.<br><br>바닥에 손이 하나 늘었다. 손바닥이 위를 본다. 손이 크다. 마디가 굵다. 오래 단련한 손이다.<br>그 손은 아무것도 쥐지 않는다. 디디는 발을 그냥 받쳐 준다. 그래서 더 무섭다.` },
      ok:`첫 발을 디뎠다. 손이 발목을 쥐었다. 마보로 낮게 앉아 발을 박았다. 손이 당긴다. 버틴다. 그 사이에 다른 발을 앞으로 옮겼다. 박은 발을 축으로.<br><br>손은 하나만 쥘 수 있다. 이쪽이 뽑히지 않으니 손이 놓았다. 다음 손이 다음 발을 쥔다. 또 버틴다. 또 놓는다. 한 걸음에 한 손씩.<br><br>건너편에 닿았다. 발목마다 손자국이 겹겹이다. 일행이 이쪽 발자국 자리만 밟고 따라왔다. 손들은 다 지쳐 있었다.`,
      win:{ exp:20, dream:3 } },
    { l:'② 내공을 발바닥으로 내려 바닥을 내리찍는다.', k:'break', dc:22, cost:{ qi:28 },
      ok:`물가에 서서 내공을 발바닥으로 모았다. 한 발을 들어 물웅덩이 가장자리 바닥을 내리찍었다.<br><br>쿵. 물이 튄다. 바닥이 울린다. 물 밑 손들이 일제히 움찔 오므라든다. 놀란 손바닥이 접힌다. 주먹이 된다.<br><br>접힌 손들이 다시 펴지기 전에 건넜다. 주먹 위를 밟고. 단단하다. 디디기 좋다. 다 건넜을 때 손들이 천천히 펴졌다. 아무것도 없는 데를 받으려고.`,
      ng:`내리찍었다. 바닥이 울렸다. 손들이 움찔했다. 그런데 바닥에 금이 갔다. 이쪽 발밑부터.<br><br>금 사이로 손이 올라와 이쪽 발을 쥐었다. 이쪽이 연 틈이다. 당긴다. 금 사이로 정강이가 빠진다.<br><br>동료들이 겨드랑이를 끼고 끌어올렸다. 정강이 살갗이 금 모서리에 다 긁혔다. 바닥 금은 다시 닫혔다. 이쪽 신발 한 짝을 물고.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-30, mind:-16 } }
  ] },

{ at:'A1', t:'7층 복도 — 도는 바닥',
  x:`7층 복도 끝에 둥근 바닥이 있다. 회전 무대다. 바닥에 화살표가 그려졌다. 여기 서세요.<br><br>
    그 위를 지나야 송출 부스 쪽으로 간다. 지나는 순간 바닥이 돈다. 천천히. 스튜디오 문 쪽으로.<br>
    도는 바닥 위에 선 사람은 문 앞으로 실려 간다. 스튜디오 안에서 음악이 흐른다. 생방송 1분 전.<br><br>
    바닥이 돈다. 발밑이 미끄러진다.`,
  o:[
    { l:'① 내공을 발바닥에 내려 바닥에 붙는다.', k:'steady', dc:23, cost:{ qi:30 }, wake:1,
      ok:`도는 바닥 위에서 내공을 발바닥으로 내렸다. 발이 바닥을 붙든다. 바닥이 돈다. 몸은 같이 돌지 않는다. 발바닥 밑에서 바닥만 미끄러져 간다.<br><br>발바닥이 뜨겁다. 그래도 붙었다. 바닥이 한 바퀴 돌아 처음 자리가 왔다. 그때 한 걸음 내디뎌 송출 부스 쪽으로 넘어갔다.<br><br>뿌리를 내리는 것은 다리였다. 이번엔 발바닥 한 장이 뿌리였다. 내공을 발바닥 가운데 한 점에 모으면 몸 전체가 그 점에 매달린다. 미끄러지는 데서도 서는 법이 생겼다. 스튜디오 문이 이쪽 없이 닫혔다.`,
      ng:`내공을 발바닥에 내렸다. 그런데 바닥이 내공을 탔다. 붙은 발째 이쪽을 실어 간다. 더 빠르게.<br><br>스튜디오 문이 다가온다. 문틈으로 빛. 박수. 발을 떼려는데 안 떨어진다. 붙인 게 이쪽이다.<br><br>내공을 끊었다. 발이 떨어지며 넘어졌다. 바닥이 이쪽을 굴려 문 앞에 내려놓았다. 동료들이 끌어냈다. 문이 열리기 한 박자 전이었다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-24, mind:-18 } },
    { l:'② 도는 반대로 걷는다 — 제자리에 머문다.', k:'evade', dc:22,
      ok:`바닥이 도는 반대쪽으로 걸었다. 같은 빠르기로. 제자리걸음이다. 바닥 위에서 이쪽은 안 움직인다.<br><br>일행도 따라 걸었다. 다섯이 바닥 위에서 제자리를 걷는다. 스튜디오 문 쪽으로 안 간다. 음악이 끝나 간다.<br><br>음악이 끝나자 바닥이 멈췄다. 화살표가 송출 부스 쪽을 보고 있었다. 내렸다. 스튜디오 안에서 실망한 소리가 길게 났다.`,
      ng:`반대로 걸었다. 바닥이 빨라졌다. 이쪽도 빨리 걸었다. 바닥이 더 빨라졌다.<br><br>뛰었다. 숨이 찬다. 바닥이 이긴다. 조금씩 문 쪽으로 밀린다. 넘어졌다. 넘어진 채로 실려 간다.<br><br>동료가 손을 뻗어 잡았다. 바닥 밖으로 끌어냈다. 무릎과 손바닥이 바닥에 갈렸다. 피가 화살표 위에 줄을 그었다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-26, spirit:-20 } }
  ] },

{ at:'A2', t:'배수로 — 당기는 물',
  x:`수영장 밑 배수로다. 물이 한쪽으로 흐른다. 세다. 관 안쪽으로.<br><br>
    배수로를 따라가면 강당이다. 그런데 관 중간에 쇠창살이 있다. 물은 지나가고 사람은 걸린다.<br>
    쇠창살에 걸린 것들이 있다. 교복 조각, 명찰, 신발. 그리고 손. 쇠창살을 쥔 손들. 지나가려다 걸린 자세 그대로.<br><br>
    창살 한 칸이 빠졌다. 사람 하나 지날 틈이다. 물이 그 틈으로 가장 세게 빨려 든다.`,
  o:[
    { l:'① 팔다리를 관 벽에 박고 물살을 버티며 틈으로 간다.', k:'steady', dc:23,
      doom:{ title:'창살 틈', what:'배수로 물살에 빨려 창살 너머로 끌려갑니다', dc:18, sec:45,
        text:`팔다리를 관 벽에 박았다. 물살이 등을 민다. 버텼다. 한 뼘씩 틈으로 갔다. 단련한 다리가 관 벽을 붙든다.<br><br>틈 앞에서 창살에 걸린 손들이 이쪽을 쥐었다. 발목, 허리띠. 같이 가자는 손이다. 무게가 늘었다. 물살과 손들이 같이 민다.<br>박은 다리가 미끄러졌다. 몸이 틈으로 빨려 든다. 어깨가 걸렸다. 어깨째 끌려간다. 창살 너머 물이 까맣다. 숨이 거품이 되어 앞질러 간다.`,
        dieText:`배수로 쇠창살에 손 하나가 늘었다.<br><br>창살을 쥔 손이 크다. 마디가 굵다. 쥐는 힘이 아직 남았다. 지나가는 물살을 버티는 손이다.<br>틈은 그대로 사람 하나 지날 크기다. 그 틈으로 물이 가장 세게 빨려 든다.` },
      ok:`팔다리를 관 벽에 박았다. 물살이 민다. 한 뼘씩 갔다. 틈 앞에서 걸린 손들이 쥐러 왔다. 쥐기 전에 몸을 틀어 틈에 다리부터 넣었다.<br><br>물살이 이쪽을 틈으로 밀어 넣는다. 손들이 허공을 쥔다. 창살 너머로 빠져나왔다. 물살이 약해지는 데까지 흘러가 관 벽을 짚었다.<br><br>뒤를 봤다. 창살에 걸린 손들이 다 이쪽을 향해 펴져 있다. 손가락이 아쉽게 오므라든다. 일행이 이쪽이 간 길로 하나씩 왔다.`,
      win:{ exp:22, dream:3 } },
    { l:'② 힘을 빼고 물살에 몸을 맡긴다.', k:'luck', dc:22,
      ok:`버티지 않았다. 숨을 크게 들이켜고 힘을 다 뺐다. 물살에 몸을 맡겼다. 몸이 가볍게 떠 흘러간다.<br><br>창살 앞에서 걸린 손들이 쥐러 왔다. 힘 뺀 몸은 미끄럽다. 손이 쥐었다가 놓친다. 물살이 이쪽을 정확히 틈으로 넣었다. 가장 센 물이 가장 넓은 데로 간다.<br><br>창살 너머로 빠져나왔다. 운이다. 단련도 아니고 기술도 아니다. 그래도 지났다.`,
      ng:`힘을 뺐다. 흘러갔다. 그런데 틈이 아니라 창살로 갔다. 몸이 창살에 걸렸다. 가슴이 창살에 눌린다.<br><br>물살이 등을 민다. 창살이 가슴을 판다. 숨이 안 쉬어진다. 걸린 손들이 이쪽 옷을 쥔다. 이제 같이 걸린 것이다.<br><br>동료들이 와서 틈으로 끌어 넣었다. 가슴에 창살 자국이 줄줄이 났다. 걸린 손 하나가 이쪽 소매를 쥔 채 같이 뜯겨 왔다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-32, mind:-16 } }
  ] },

{ at:'A', t:'불침번 — 등 뒤의 손',
  x:`불침번이다. 불 앞에 앉았다. 등이 어둠 쪽이다.<br><br>
    등에 손이 얹혔다. 차다. 손바닥 하나. 견갑골 사이에. 가만히 있다.<br>
    등은 매일 벽에 쳤다. 등이 제일 단단하다. 그런데 등은 볼 수가 없다.<br><br>
    손바닥이 아주 조금씩 차가워진다. 등뼈를 타고 차가움이 내려온다.`,
  o:[
    { l:'① 돌아보지 않고 등 근육으로 손을 밀어낸다.', k:'steady', dc:22,
      ok:`돌아보지 않았다. 숨을 들이켜 등 근육에 힘을 모았다. 견갑골을 모았다가 확 폈다. 등이 손바닥을 밀어낸다.<br><br>손이 떨어졌다. 다시 얹힌다. 또 밀어냈다. 몇 번. 손이 망설인다. 이 등은 받아 주지 않는다.<br><br>새벽에 손이 오지 않았다. 등 가운데 손바닥 자국이 서리로 찍혔다. 해가 뜨자 녹았다. 녹은 물이 등을 타고 흘렀다. 눈물처럼 미지근했다.`,
      ng:`밀어냈다. 손이 떨어졌다. 그런데 다음엔 손이 둘이다. 셋이다. 등이 손바닥으로 덮인다.<br><br>등이 얼어 간다. 근육이 굳는다. 밀어낼 힘이 안 남았다. 불 앞인데 등이 얼음이다.<br><br>동료가 교대하러 와서 이쪽 등을 보고 소리를 질렀다. 손이 사라졌다. 등에 손바닥 자국이 빼곡하다. 사흘 동안 등을 대고 눕지 못했다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, spirit:-22 } },
    { l:'② 돌아본다.', k:'gaze', dc:23,
      doom:{ title:'등 뒤', what:'등 뒤의 것에게 어둠 속으로 끌려갑니다', dc:18, sec:45,
        text:`돌아봤다. 아무도 없다. 어둠뿐이다. 손바닥은 여전히 등에 있다.<br><br>돌아본 것이 대답이었다. 손이 등에서 어깨로, 목으로 올라온다. 목덜미를 쥔다. 다정하게. 고양이 새끼를 물어 가듯.<br>들린다. 엉덩이가 바닥에서 뜬다. 불이 멀어진다. 뒤로 끌려간다. 발뒤꿈치가 땅을 긁는다. 어둠 안쪽에서 숨소리가 가깝다. 아무도 없는 데서.`,
        dieText:`불이 꺼져 있었다. 불침번 자리에 아무도 없다.<br><br>불 자리 둘레에 발뒤꿈치 자국이 두 줄. 어둠 쪽으로 길게.<br>그 뒤로 일행은 불침번을 둘씩 섰다. 등과 등을 붙이고. 그래도 가끔 셋째 등이 느껴졌다.` },
      ok:`돌아보기 전에 불붙은 나뭇가지를 쥐었다. 돌아보며 등 뒤를 불로 그었다.<br><br>어둠이 갈라진다. 불빛 끝에 무엇이 웅크렸다. 손을 이쪽 등 높이로 뻗은 채. 불을 보고 손을 거둔다. 얼굴을 손으로 가린다.<br><br>불을 들고 노려봤다. 그것이 뒷걸음질로 어둠에 녹았다. 등이 다시 따뜻해졌다. 남은 밤 내내 불을 등 뒤에 두고 앉았다.`,
      win:{ exp:20, dream:3 } }
  ] },

{ at:'A', t:'쉬는 자리 — 빈 단전',
  x:`내공이 바닥났다. 단전이 텅 비었다. 숨을 모아도 모일 데가 없다.<br><br>
    밤이 차다. 몸이 식는다. 내공으로 데우던 몸이다. 데울 것이 없다.<br>
    어둠에서 무엇이 다가온다. 따뜻한 것을 찾는 기척이다. 이쪽은 이제 따뜻하지 않다. 그래서 다른 동료들 쪽으로 간다.<br><br>
    외공 수련생은 내공 없이도 몸이 몸이라는 걸 안다. 몸은 몇 해를 맞아 왔다.`,
  o:[
    { l:'① 숨을 아랫배에 천천히 다시 쌓는다 — 맨몸으로 버티며.', k:'steady', dc:22, wake:1,
      ok:`가부좌를 틀었다. 빈 단전에 숨을 한 모금씩 내렸다. 아무것도 안 모인다. 그래도 내렸다. 백 번. 이백 번.<br><br>내공은 안 돌아왔다. 대신 숨 자체가 따뜻해졌다. 오래 내린 숨이 아랫배를 데운다. 내공이 아니어도 숨은 숨이다.<br>그 숨으로 동료들 쪽 기척을 봤다. 일어나 동료들 앞에 앉았다. 맨몸으로. 기척이 이쪽 앞에서 멈췄다. 따뜻하지 않은 것이 막고 있다.<br><br>내공이 몸을 지키는 줄 알았다. 몸이 내공을 담고 있었을 뿐이다. 빈 그릇도 그릇이다. 숨 하나로 몸을 세우는 법이 남았다. 새벽에 단전에 내공이 한 줌 돌아왔다. 처음보다 빨리.`,
      ng:`숨을 내렸다. 안 모인다. 몸이 계속 식는다. 손끝이 하얗다. 머리가 흐려진다.<br><br>기척이 이쪽으로 돌아왔다. 식어 가는 것도 좋은 모양이다. 이쪽 옆에 앉는다. 이쪽처럼 가부좌를 튼다. 숨을 같이 쉰다. 같은 박자로. 이쪽 숨을 가져간다.<br><br>동료가 깨서 이쪽을 흔들었다. 숨이 거의 멈춰 있었다. 옆자리 바닥에 가부좌 모양 서리가 앉았다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-26, spirit:-24 } },
    { l:'② 동료들과 붙어 체온을 나눈다.', k:'bond', dc:22,
      ok:`동료들 사이로 들어가 붙었다. 등과 가슴을 붙였다. 이쪽은 차다. 동료들이 움찔한다. 그래도 받아 줬다.<br><br>체온이 섞인다. 이쪽이 조금씩 데워진다. 기척이 다가오다 멈췄다. 따뜻한 것이 하나로 뭉쳐 있다. 하나만 떼어 갈 수가 없다.<br><br>새벽까지 붙어 잤다. 기척은 둘레를 돌다 갔다. 단전은 여전히 비었다. 그래도 몸은 살았다.`,
      ng:`붙었다. 이쪽 몸이 너무 차서 옆 동료가 떤다. 동료 체온이 이쪽으로 빨려 온다. 동료가 식는다.<br><br>기척이 식은 동료 쪽으로 온다. 동료 발목을 쥔다. 끈다. 이쪽이 붙어 있어서 같이 끌린다.<br><br>둘이 같이 버텼다. 다른 동료들이 깨서 붙잡았다. 기척이 놓았다. 옆 동료가 이쪽을 원망하는 눈으로 봤다. 할 말이 없었다.`,
      win:{ exp:16, dream:2, hp:6 }, lose:{ hp:-22, mind:-18 } },
    { l:'③ 찬 바닥에 엎드려 팔굽혀펴기로 몸을 데운다.', k:'fix', dc:21,
      ok:`엎드려 팔굽혀펴기를 했다. 하나, 둘. 백. 땀이 난다. 몸이 데워진다. 내공이 없으면 근육이 데운다.<br><br>기척이 이쪽을 돌아본다. 다시 따뜻해진 것이 있다. 다가온다. 이쪽은 계속 했다. 이백. 숨이 거칠다. 그 거친 숨이 기척을 멈칫하게 했다. 살아 있는 소리가 크다.<br><br>새벽까지 했다. 팔이 떨린다. 기척은 너무 시끄러운 것 곁에 오래 머물지 않았다.`,
      ng:`했다. 그런데 오십에서 팔이 무너졌다. 빈 단전으로는 근육도 오래 못 버틴다.<br><br>엎드린 채 숨을 몰아쉬었다. 땀이 식는다. 식은 땀이 더 차다. 등 위에 무엇이 올라앉았다. 가볍다. 차다.<br><br>일어나지 못했다. 아침까지 엎드려 있었다. 등에서 무게가 내려간 뒤에야 일어났다. 땀이 등에 하얗게 얼어 있었다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-24, spirit:-20 } }
  ] },

{ at:'A', t:'나가는 길 — 남은 쥔 자국',
  x:`나가는 문이 보인다. 쉬는 틈에 옷을 걷고 몸을 봤다.<br><br>
    멍투성이다. 맞은 멍, 받은 멍, 쥐인 멍. 다 읽힌다. 언제 어디서 무엇에.<br>
    하나만 안 읽힌다. 왼쪽 손목에 손가락 다섯 자국. 오늘 생긴 게 아니다. 들어올 때부터 있었다. 매일 조금씩 진해졌다.<br><br>
    지금도 쥐고 있다. 아주 가볍게.`,
  o:[
    { l:'① 그 자리를 쳐서 떼어 낸다.', k:'break', dc:22,
      ok:`오른손 날로 왼쪽 손목 멍을 내리쳤다. 단련할 때처럼. 한 번. 두 번.<br><br>세 번째에 손목이 가벼워졌다. 손가락이 하나씩 떨어져 나가는 감촉. 다섯. 멍이 그 자리에서 노랗게 빠지기 시작했다.<br><br>문을 나섰다. 뒤에서 무엇이 아쉬운 숨을 쉬었다. 들어올 때부터 같이 온 것이다. 나가는 문 앞까지만.`,
      ng:`내리쳤다. 손목이 아프다. 멍은 그대로다. 오히려 손가락이 조인다. 맞는 것을 아는 손이다.<br><br>세게 칠수록 세게 쥔다. 손목 뼈가 운다. 그만뒀다. 손이 다시 가벼워졌다. 가볍게 쥔다.<br><br>문을 나서도 손목이 무겁다. 밖에서 봐도 멍은 그대로였다. 손가락 다섯. 이쪽 손보다 조금 작다.`,
      win:{ exp:16, dream:3 }, lose:{ hp:-22, spirit:-24 } },
    { l:'② 그대로 둔다 — 쥔 손째로 걷는다.', k:'steady', dc:22, wake:1,
      ok:`치지 않았다. 손목을 내려다보고 그냥 두었다. 쥐고 있는 것은 당기지 않는다. 쥐고만 있다. 처음부터.<br><br>들어올 때부터 붙들고 있었다. 이쪽이 끌려갈 때마다 손목이 먼저 버텼다. 문간에서, 물속에서, 계단에서. 이쪽 몸이 버틴 줄 알았던 몇 번은 이 손이 같이 버텼다.<br><br>무엇이 쥐었는지 모른다. 몸이 그 무게까지 제 것으로 받아들였다. 쥐인 채로 서는 법, 남의 손을 몸의 일부로 삼는 법. 받아들인 무게는 짐이 아니다. 문을 나서자 쥔 손이 아주 조금 풀렸다. 다 풀리지는 않았다.`,
      ng:`그대로 두었다. 문 앞에서 손이 당겼다. 처음으로. 뒤로.<br><br>나가지 말라는 힘이다. 세지 않다. 그런데 오래 쥐어 온 손이라 뿌리치기 어렵다. 한참 문 앞에 서 있었다.<br><br>끝내 한 발을 내디뎠다. 손목에서 손가락이 하나씩 미끄러졌다. 아쉬운 듯 천천히. 밖에서 보니 손목이 하얗게 얼어 있었다.`,
      win:{ exp:22, dream:4 }, lose:{ mind:-18, spirit:-24 } }
  ] }

]);

// ── 광부 (miner) · 자원 없음
kJob('miner', 'A', [

{ at:'A', t:'들어가는 길 — 어깨 여섯, 이름 다섯',
  x:`들어서기 전에 머릿수를 셌다. 광부는 들어갈 때 세고 나올 때 센다. 둘이 맞아야 하루가 끝난다.<br><br>
    불을 끄고 셌다. 땅 밑에서는 눈보다 손이 정확하다. 어깨를 하나씩 짚었다. 하나, 둘, 셋, 넷, 다섯, 여섯.<br>
    불을 켜고 이름을 불렀다. 다섯이 대답했다.<br><br>
    여섯째 어깨는 맨 끝, 벽에 붙은 자리였다. 차고 젖은 어깨였다.`,
  o:[
    { l:'① 불을 끄고 다시 센다 — 이름을 부르며 어깨를 짚는다.', k:'fix', dc:22,
      ok:`불을 끄고 다시 셌다. 이번엔 어깨를 짚을 때마다 이름을 불렀다. 짚고, 부르고, 대답을 듣고.<br><br>다섯까지 대답이 왔다. 여섯째 어깨를 짚었다. 이름을 부를 게 없다. 그래서 물었다. 누구냐고.<br>어깨가 손바닥 밑에서 스르르 빠져나갔다. 벽 쪽으로. 대답 못 하는 것은 셈에 남지 못한다.<br><br>불을 켰다. 다섯이다. 벽에 젖은 어깨 자국이 하나 남았다. 이쪽 손바닥 높이에.`,
      ng:`불을 끄고 다시 셌다. 이름을 불렀다. 다섯째 동료 이름에서 대답이 두 번 왔다. 하나는 앞에서, 하나는 벽 쪽에서. 같은 목소리로.<br><br>어느 쪽이 진짜인지 손이 모른다. 둘 다 어깨가 있다. 둘 다 대답했다.<br><br>불을 켰다. 다섯이다. 그런데 다섯째 동료가 아까부터 벽 쪽에 서 있다. 원래는 이쪽 옆이었다. 동료는 자기는 안 움직였다고 한다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-18, spirit:-22 } },
    { l:'② 숨소리로 센다 — 어둠 속에서 귀로.', k:'sense', dc:22, wake:1,
      ok:`불을 끈 채 귀를 열었다. 숨소리를 셌다. 땅 밑에서 오래 산 귀다. 갱도마다 숨이 몇인지 들으면 안다.<br><br>하나, 둘, 셋, 넷, 다섯. 다섯이다. 숨이 다섯. 여섯째 어깨 자리에는 숨이 없다. 숨 없이 서 있는 것이 하나 있다.<br>그 자리 쪽으로 등불을 들이밀었다. 어깨 높이에 아무것도 없다. 바닥에 물이 고여 있다. 사람 하나 서 있던 넓이로.<br><br>어깨는 속이고 이름은 흉내 낸다. 숨은 속이지 못한다. 숨으로 머릿수를 세는 귀가 생겼다. 그 뒤로 어둠 속에서 몇이 있는지 손보다 귀가 먼저 알았다.`,
      ng:`숨소리를 셌다. 다섯. 그런데 다섯 중 하나가 너무 느리다. 사람 숨이 아니다.<br><br>누구 숨인지 찾으려고 귀를 기울였다. 느린 숨이 이쪽 귀 바로 옆에서 난다. 이쪽 어깨에 턱을 괴고. 차다.<br><br>불을 켰다. 다섯이다. 이쪽 옆에 아무도 없다. 다섯 중 누가 사람 숨이 아니었는지 그날 끝내 알 수 없었다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-20, spirit:-24 } },
    { l:'③ 벽 쪽 여섯째 어깨를 다시 짚어 본다.', k:'gaze', dc:23,
      doom:{ title:'여섯째 어깨', what:'벽 속으로 끌려 들어갑니다', dc:18, sec:50,
        text:`불을 끄고 벽 쪽으로 손을 뻗었다. 어깨가 있다. 차고 젖었다. 짚은 손을 그것이 잡았다. 어깨에서 손으로 옮겨 온다.<br><br>당긴다. 벽 쪽으로. 벽이 무르다. 진흙처럼. 손목이 벽에 잠긴다. 팔꿈치. 벽 속에서 그것이 이쪽 이름을 부른다. 셈을 마치는 목소리로. 여섯.<br>뒤에서 동료들이 불을 켜려고 부싯돌을 친다. 불똥만 튄다. 어깨가 벽에 닿는다. 벽이 이쪽 어깨 모양으로 받아들인다.`,
        dieText:`불이 켜졌다. 다섯이 섰다. 머릿수를 셌다. 다섯.<br><br>벽에 사람 모양 자국이 남았다. 어깨부터 들어간 모양으로. 손바닥 자국이 바깥으로 하나 나와 있다.<br>나올 때 센 머릿수는 들어갈 때와 같았다. 다섯과 다섯. 맞는데 맞는 것 같지가 않았다.` },
      ok:`불을 켠 채로 다가가 짚었다. 등불을 바로 옆에 대고. 빛 아래서 어깨는 벽이다. 젖은 돌이 어깨 모양으로 불룩할 뿐이다.<br><br>곡괭이 자루로 그 불룩한 데를 두드렸다. 텅. 속이 비었다. 빈 데가 어깨 모양이다. 누가 거기 서 있다 나갔다. 아니면 들어갔다.<br><br>그 벽에서 열 걸음 떨어져 쉬었다. 밤새 텅 빈 자리에서 물 떨어지는 소리가 났다. 숨 쉬는 박자로.`,
      win:{ exp:20, dream:3 } }
  ] },

{ at:'A1', t:'로비 — 텔레비전이 세는 머릿수',
  x:`방송국 정문 안쪽 로비. 텔레비전에 노란 해 얼굴이 웃는다. 입이 숫자를 센다. 하나, 둘.<br><br>
    들어갈 때는 머릿수를 센다. 이쪽이 세는 동안 텔레비전도 센다. 이쪽 일행을. 입 모양이 이쪽보다 반 박자 빠르다.<br>
    이쪽 셈이 다섯에서 끝났다. 텔레비전 입은 여섯에서 멈췄다. 그리고 이쪽을 보며 웃는다.<br><br>
    화면 속 로비에 일행이 비친다. 여섯이다.`,
  o:[
    { l:'① 일행 손목마다 분필로 표시를 하고 센다.', k:'fix', dc:22,
      ok:`분필을 꺼내 일행 손목에 하나씩 표시를 그었다. 가로줄 하나. 이쪽만 아는 꼬리를 달아서. 그리고 손목을 보며 셌다. 다섯.<br><br>화면 속을 봤다. 여섯이 비친다. 손목에 분필이 있는 것은 다섯. 하나는 맨 끝에 서서 손을 등 뒤에 감추고 있다.<br><br>표시 없는 쪽을 등지고 계단으로 갔다. 화면 속에서 표시 없는 것이 따라오다 화면 끝에서 멈췄다. 손을 꺼냈다. 손목에 분필이 그어져 있다. 꼬리가 없다.`,
      ng:`표시를 그었다. 다섯. 그런데 화면 속 여섯 모두의 손목에 분필이 있다. 똑같은 줄이 똑같이.<br><br>화면 속 것이 이쪽을 흉내 낸다. 이쪽이 그은 대로. 이쪽 셈을 화면이 같이 센다.<br><br>텔레비전 전원을 찾다 포기하고 계단으로 뛰었다. 화면 속 여섯째가 계단 쪽을 향해 손을 흔들었다. 다시 보자고.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-18, spirit:-22 } },
    { l:'② 화면을 등지고 눈을 감고 어깨로 센다.', k:'steady', dc:22,
      ok:`텔레비전을 등졌다. 눈을 감았다. 일행 어깨를 하나씩 짚었다. 하나, 둘, 셋, 넷, 다섯. 손이 아는 숫자다.<br><br>등 뒤에서 텔레비전이 계속 센다. 여섯, 여섯. 이쪽은 다섯에서 멈췄다. 셈은 세는 사람이 정한다.<br><br>눈을 뜨고 계단으로 갔다. 등 뒤 화면에서 박수 소리가 났다. 소리는 꺼져 있었는데.`,
      ng:`등지고 눈을 감았다. 어깨를 짚었다. 다섯째를 짚고 손을 거두는데 손이 하나 더 짚었다. 저절로. 여섯째 어깨를.<br><br>등 뒤에서 텔레비전이 말한다. 잘했어요. 여섯. 손바닥 밑 어깨가 차갑다. 털이 있다.<br><br>눈을 떴다. 손이 허공을 짚고 있다. 손바닥에 갈색 털이 한 올 붙어 있었다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-22, spirit:-24 } }
  ] },

{ at:'A2', t:'나선 계단 — 등불의 불꽃',
  x:`종탑 나선 계단을 내려간다. 아래로 갈수록 물 냄새가 짙다. 몇 칸 아래가 물이다.<br><br>
    등불 불꽃을 본다. 땅 밑에서 불꽃은 말을 한다. 줄어들면 공기가 나쁘고, 파래지면 독한 기운이 있다.<br>
    지금 불꽃이 한쪽으로 눕는다. 아래로. 물 쪽으로. 바람이 그쪽으로 빨려 든다.<br><br>
    물 밑에 공기가 있다. 아니면 물 밑에서 무엇이 숨을 들이쉰다.`,
  o:[
    { l:'① 불꽃이 눕는 결을 오래 지켜본다.', k:'sense', dc:22, wake:1,
      ok:`계단에 쪼그려 앉아 등불을 무릎에 놓고 불꽃만 봤다. 눕는다. 다시 선다. 다시 눕는다. 일정하다. 숨 쉬는 박자다.<br><br>바람이 아니다. 물 밑에서 무엇이 숨을 쉰다. 들이쉴 때 불꽃이 아래로 눕고, 내쉴 때 선다. 박자가 느리다. 크다.<br>그 박자를 세었다. 내쉬는 사이가 길다. 그 사이에 물로 내려가면 빨려 들지 않는다.<br><br>불꽃은 공기만 말하는 줄 알았다. 무엇이 숨 쉬는지도 말한다. 불꽃 눕는 결로 숨의 크기와 자리를 읽는 눈이 생겼다. 내쉬는 박자에 물로 들어갔다. 물이 이쪽을 밀어냈다. 빨지 않았다.`,
      ng:`지켜보는데 불꽃이 갑자기 꺼졌다. 한 번에 빨려서.<br><br>어둠 속에서 계단 아래가 크게 숨을 들이쉰다. 이쪽 옷자락이 아래로 끌린다. 머리카락이 아래로 날린다. 발이 한 칸 미끄러졌다.<br><br>난간을 붙잡고 버텼다. 숨이 끝나자 끌림이 멎었다. 불을 다시 켰다. 이쪽은 세 칸 아래에 있었다. 물이 발목에 닿아 있었다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-24, spirit:-22 } },
    { l:'② 등불을 물 쪽으로 내밀어 비춰 본다.', k:'luck', dc:22,
      ok:`등불을 쥔 팔을 길게 뻗어 물 위로 내밀었다. 불빛이 물속을 비춘다. 맑다. 계단이 물속으로 이어진다. 그 옆으로 문이 하나. 다음 층이다.<br><br>문 너머 물이 흔들린다. 숨 쉬는 것이 거기 있다. 문 너머로 가지 않으면 된다. 계단은 문 앞을 지나 더 내려간다.<br><br>등불을 거두려는데 물속에서 손 하나가 불빛을 따라 올라온다. 손바닥으로 빛을 쥐려 한다. 빛은 쥐어지지 않는다. 손이 그걸 모르는 모양이다.`,
      ng:`내밀었는데 물속에서 손이 올라와 등불 고리를 쥐었다. 당긴다.<br><br>등불을 놓쳤다. 물에 떨어졌다. 불빛이 물속으로 가라앉으며 계단을 비춘다. 계단마다 사람이 앉아 있다. 위를 보고. 불빛이 지나갈 때마다 하나씩.<br><br>불빛이 바닥에 닿아 꺼졌다. 예비 심지로 겨우 불을 살렸다. 그 뒤로 등불을 물 쪽으로 내밀지 않았다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-22, mind:-18 } }
  ] },

{ at:'A', t:'좁은 굴 — 벽 속의 노크',
  x:`굴이 좁다. 벽 속에서 소리가 난다. 똑, 똑, 똑. 쉬고. 똑, 똑, 똑.<br><br>
    이 박자를 안다. 갇힌 사람이 보내는 소리다. 살아 있다. 꺼내 달라.<br>
    땅 밑에서 그 소리를 들으면 무조건 판다. 그게 광부의 규칙이다. 맨 처음 배운 규칙이다.<br><br>
    여기는 갱도가 아니다. 벽 너머에 사람이 있을 리 없다. 소리는 계속 난다. 아주 정확하게.`,
  o:[
    { l:'① 세 번 두드려 대답한다 — 알았다, 판다.', k:'bond', dc:23,
      doom:{ title:'대답', what:'벽 속에서 나온 손에 끌려 들어갑니다', dc:18, sec:50,
        text:`곡괭이 자루로 벽을 세 번 두드렸다. 알았다. 판다. 배운 대로.<br><br>벽 너머가 조용해졌다. 그리고 벽이 안에서 열렸다. 돌이 진흙처럼 갈라진다. 손이 나왔다. 여럿. 반가운 손이다. 이쪽 손목을, 팔을, 옷깃을 쥔다.<br>당긴다. 벽 안으로. 꺼내 달라고 부른 것이 아니다. 들어오라고 부른 것이다. 갇힌 쪽은 이쪽이었다는 듯이. 어깨가 벽에 묻힌다. 벽 속이 따뜻하다. 사람 체온이 많다.`,
        dieText:`굴 벽에서 소리가 난다. 똑, 똑, 똑. 쉬고. 똑, 똑, 똑.<br><br>박자가 조금 달라졌다. 끝에 한 번이 더 붙는다. 땅 밑 사람들이 쓰는 꼬리다.<br>남은 사람들은 대답하지 않았다. 그 소리를 등지고 오래 걸었다. 소리가 굴 끝까지 따라왔다.` },
      ok:`세 번 두드렸다. 그러고 바로 귀를 벽에 댔다. 대답을 기다렸다. 진짜 갇힌 사람이면 두 번 대답한다. 기다리겠다고.<br><br>대답이 없다. 대신 벽 안에서 손바닥 비비는 소리가 난다. 반가운 손이 벽을 더듬는다. 이쪽 귀 바로 너머에서. 벽이 조금 물렁해진다.<br><br>귀를 떼고 물러섰다. 갇힌 사람은 대답할 줄 안다. 대답을 모르는 것은 갇힌 게 아니다. 기다리는 것이다. 벽이 이쪽 귀 모양으로 오목하게 패었다.`,
      win:{ exp:20, dream:3 } },
    { l:'② 벽을 한 뼘씩 두드려 빈 데가 어딘지 찾는다.', k:'sense', dc:22,
      ok:`곡괭이 머리로 한 뼘씩 두드렸다. 꽉, 꽉, 텅. 텅 빈 데가 길다. 사람 키 높이로 옆으로 이어진다. 벽 속에 굴이 하나 더 있다. 이쪽 굴과 나란히.<br><br>노크 소리가 그 빈 굴을 따라 움직인다. 이쪽이 걸으면 같이 걷는다. 앞질러 가기도 한다.<br><br>빈 굴이 끝나는 데를 찾았다. 저 앞 굽이에서 두 굴이 만난다. 굽이 앞에서 길을 바꿨다. 노크 소리가 굽이에서 기다리다 실망한 듯 빨라졌다.`,
      ng:`두드리는데 이쪽이 두드리는 박자를 벽 속이 따라 한다. 꽉, 꽉, 텅. 똑같이.<br><br>어디가 빈 데인지 모르겠다. 벽 속 것이 소리를 섞는다. 두드릴수록 다 비어 있다. 굴 전체가.<br><br>그만뒀다. 귀가 먹먹하다. 밤새 귀에서 노크 소리가 났다. 벽 없는 데서도.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-18, spirit:-22 } },
    { l:'③ 대답하지 않는다 — 규칙을 어기고 지나간다.', k:'steady', dc:22,
      ok:`곡괭이를 고쳐 쥐고 지나갔다. 대답하지 않았다. 맨 처음 배운 규칙을 처음으로 어겼다. 땅 밑이 아니니까. 갱도가 아니니까.<br><br>노크가 빨라진다. 똑똑똑똑. 절박하다. 사람 같다. 너무 사람 같다. 걸음을 멈추지 않았다.<br><br>굴 끝에서 소리가 그쳤다. 마지막에 아주 작게 한 번. 그건 땅 밑에서 쓰는 소리가 아니다. 아이가 손톱으로 긁는 소리였다.`,
      ng:`지나가려는데 발이 안 떨어진다. 몸이 규칙을 기억한다. 손이 저절로 벽으로 간다.<br><br>손이 벽에 닿았다. 두드리지는 않았다. 손바닥을 댔을 뿐이다. 벽 너머에서 손바닥이 마주 댔다. 차갑다.<br><br>떼어 냈다. 손바닥에 벽 흙이 아니라 젖은 손금이 찍혀 있다. 남의 손금이다. 씻어도 한동안 안 지워졌다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-22, spirit:-24 } }
  ] },

{ at:'A', t:'쉬는 자리 — 파래지는 등불',
  x:`쉬는 자리에서 등불이 파래졌다. 불꽃 끝이 푸르다. 줄어든다.<br><br>
    파란 불꽃이 무엇인지 안다. 독한 기운이다. 낮은 데 고인다. 잠든 사람부터 데려간다.<br>
    그런데 오늘 불꽃은 고르게 파랗지 않다. 한쪽만 파랗다. 잠든 동료 쪽만.<br><br>
    그 동료 머리맡이 어둡다. 무엇이 웅크리고 있는 만큼.`,
  o:[
    { l:'① 등불을 바닥까지 낮춰 공기를 본다.', k:'sense', dc:22,
      ok:`등불을 바닥까지 내렸다. 불꽃이 더 줄지 않는다. 바닥 공기는 괜찮다. 독한 기운이 아니다.<br><br>등불을 동료 머리맡으로 옮겼다. 불꽃이 확 파래진다. 거기만 차다. 무엇이 숨을 쉰다. 아주 찬 숨을. 동료 얼굴에.<br><br>등불을 그 자리에 두었다. 불을 가까이 두면 그것이 물러난다. 불꽃이 천천히 노래졌다. 동료 입술 색이 돌아왔다.`,
      ng:`낮췄는데 불꽃이 꺼졌다. 바닥 공기가 나쁘다. 정말 독한 기운도 있었다.<br><br>어둠 속에서 동료 쪽 숨소리가 느려진다. 그 옆에서 다른 숨소리가 빨라진다. 신난 숨이다.<br><br>더듬어 동료를 끌고 높은 데로 올라갔다. 머리가 지끈거린다. 불을 다시 켜는 데 한참 걸렸다. 동료 볼에 손바닥 자국이 하얗다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-24, mind:-16 } },
    { l:'② 불꽃이 기우는 쪽을 보고 일행을 깨워 자리를 옮긴다.', k:'steady', dc:22, wake:1,
      ok:`불꽃을 봤다. 파란 쪽이 동료 머리맡이다. 그런데 불꽃 끝이 그쪽이 아니라 반대쪽으로 기운다. 찬 것이 숨을 내쉬는 방향이다. 그것은 동료 머리맡에서 입구 쪽을 보고 있다.<br><br>입구가 아니라 안쪽으로 옮겼다. 일행을 다 깨웠다. 소리 없이. 손짓으로. 안쪽 높은 자리에 다시 앉았다.<br>그것이 입구 쪽만 보다가 나갔다. 사람들이 입구로 나갈 줄 알았던 모양이다.<br><br>불꽃은 무엇이 있는지만 말하는 줄 알았다. 무엇이 어디를 보는지도 말한다. 파란 쪽과 기우는 쪽이 다르다. 그 둘을 함께 읽는 눈이 생겼다. 그 밤 등불은 다시 노래졌다.`,
      ng:`옮기려고 일행을 깨웠다. 하나가 깨지 않는다. 머리맡 동료다. 흔들어도 숨만 느리다.<br><br>업었다. 업는 순간 등이 무거워졌다. 둘을 업은 무게다. 동료 등에 무엇이 같이 매달렸다.<br><br>자리를 옮기고 내려놓자 무게가 하나로 돌아왔다. 동료는 아침에 깼다. 꿈에 누가 업혀 가자고 했다고. 업은 사람 등이 따뜻했다고.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-22, spirit:-24 } }
  ] },

{ at:'A1', t:'소품 창고 — 판자 벽',
  x:`3층 소품 창고. 세트 판자가 겹겹이 세워졌다. 판자와 판자 사이가 좁은 길이다. 갱도처럼.<br><br>
    판자마다 그림이 있다. 웃는 해, 꽃밭, 무지개. 뒤쪽은 맨 나무다. 버팀대로 받쳤다.<br>
    판자 하나가 기울었다. 버팀대가 빠졌다. 기운 판자가 옆 판자에 기댔다. 옆 판자가 다음 판자에.<br><br>
    판자들 사이에서 숨소리가 난다. 그림 뒤에서.`,
  o:[
    { l:'① 기댄 판자들을 두드려 무게가 어디로 가는지 본다.', k:'sense', dc:22, wake:1,
      ok:`곡괭이 자루로 판자를 하나씩 두드렸다. 소리가 다르다. 무게를 받는 판자는 소리가 낮다. 받지 않는 판자는 높다.<br><br>낮은 소리가 셋. 그 셋이 나머지 무게를 다 받는다. 그 셋만 피하면 된다. 그런데 셋 중 하나 뒤에서 숨소리가 난다. 무엇이 판자 뒤에서 받치고 있다. 아니면 밀 준비를 한다.<br>그 판자 앞을 지날 때 동료들을 반대쪽으로 붙였다. 지나자 판자들이 와르르 쓰러졌다. 아무도 밑에 없었다.<br><br>버팀목은 땅 밑에만 있는 줄 알았다. 무게가 기대는 데면 어디든 있다. 나무든 판자든 사람이든. 소리로 무게의 길을 읽는 손이 땅 밖에서도 통했다. 쓰러진 판자 밑에서 그림 속 해가 이쪽을 올려다봤다.`,
      ng:`두드리는데 소리가 다 같다. 판자 뒤 숨소리가 소리를 먹는다.<br><br>기운 판자 쪽으로 동료가 지난다. 판자가 밀렸다. 뒤에서. 판자 셋이 한꺼번에 쓰러진다. 동료를 덮쳤다.<br><br>판자를 들어 올렸다. 동료는 판자 사이 틈에 끼어 살았다. 다리가 깔렸다. 판자 그림 속 해가 웃고 있다. 판자 뒤에 손자국이 찍혀 있다. 민 손이다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-28, mind:-14 } },
    { l:'② 판자 사이를 빨리 지나간다.', k:'evade', dc:22,
      ok:`몸을 낮추고 판자 사이를 뛰었다. 일행이 뒤를 따랐다. 판자가 흔들린다. 숨소리가 따라온다. 그림 뒤에서 그림 뒤로.<br><br>마지막 판자를 지나는데 등 뒤에서 판자들이 쓰러졌다. 연달아. 먼지가 확 일었다.<br><br>먼지가 가라앉자 쓰러진 판자 뒤가 다 보였다. 아무것도 없다. 판자마다 뒷면에 분필 글씨. 출연자 대기. 그 밑에 이름들.`,
      ng:`뛰는데 판자 하나가 앞으로 쓰러진다. 길을 막았다. 뒤로 돌아서는데 뒤 판자도 쓰러진다.<br><br>판자 두 장 사이에 갇혔다. 위가 열렸다. 기어오르려는데 판자 뒤에서 손이 발목을 잡았다. 그림 뒤에서.<br><br>동료들이 판자를 밀어 젖혔다. 빠져나왔다. 발목에 페인트가 묻었다. 노란색. 웃는 해의 색이다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-26, spirit:-20 } }
  ] },

{ at:'A2', t:'보일러실 — 석탄 더미',
  x:`보일러실 한쪽에 석탄이 산처럼 쌓였다. 아랫단은 물에 잠겼다. 윗단은 물 밖이다.<br><br>
    석탄 더미 중간에서 손 하나가 나와 있다. 손바닥을 위로. 하얗다. 석탄 가루가 묻지 않았다.<br>
    석탄이라면 안다. 무너지는 결, 버티는 결. 손으로 마구 파면 더미 전체가 쏟아진다.<br><br>
    손가락이 움직인다. 아주 조금. 꺼내 달라는 것처럼.`,
  o:[
    { l:'① 석탄 결을 읽어 무너지지 않게 한 덩이씩 걷어 낸다.', k:'steady', dc:22, wake:1,
      ok:`석탄 더미를 봤다. 덩이마다 기대는 방향이 있다. 큰 것이 작은 것을 받친다. 위에서부터, 받치지 않는 것부터 하나씩 걷었다. 더미가 흔들리지 않는다.<br><br>손 둘레가 드러났다. 손목, 팔. 팔이 더미 속으로 길다. 너무 길다. 사람 팔 길이를 넘었다. 걷는 손을 멈췄다.<br>더 걷으면 저것이 나온다. 꺼내 달라는 손이 아니다. 나오고 싶은 손이다.<br><br>걷어 낸 덩이를 도로 하나씩 얹었다. 받치는 결대로. 더미가 손을 다시 덮었다. 파는 손이 덮는 손도 된다. 결을 아는 손은 어느 쪽이든 무너뜨리지 않는다. 그 감각이 손바닥에 남았다. 손가락이 석탄 밑에서 아쉽게 오므라들었다.`,
      ng:`결을 읽어 걷었다. 그런데 손이 이쪽 손을 잡았다. 걷어 내던 손을. 꽉.<br><br>당긴다. 더미 속으로. 석탄이 이쪽 팔 위로 쏟아진다. 결이 무너졌다. 이쪽이 받치던 덩이가 이쪽을 덮는다.<br><br>동료들이 석탄을 퍼 끌어냈다. 팔이 석탄에 긁혀 엉망이다. 손을 잡혔던 자리만 하얗다. 석탄 가루가 안 묻는다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-30, mind:-14 } },
    { l:'② 손을 잡아 단번에 끌어낸다.', k:'bond', dc:22,
      ok:`손을 잡았다. 차다. 단번에 당겼다. 석탄이 쏟아졌다. 손이 쑥 빠져나왔다.<br><br>손만 나왔다. 팔꿈치까지. 그 뒤가 없다. 손이 이쪽 손을 잡은 채 계속 꼭 쥔다. 고맙다는 듯이.<br><br>손가락을 하나씩 떼어 냈다. 떼어 낸 손을 석탄 더미 위에 놓았다. 손이 석탄 위를 기어 물 쪽으로 갔다. 물속으로 들어갔다. 더 찾을 것이 있는 모양이다.`,
      ng:`잡아 당겼다. 손이 안 빠진다. 더미 속에서 무엇이 마주 당긴다. 이쪽보다 세다.<br><br>더미가 무너지며 이쪽을 덮쳤다. 석탄 속에서 숨을 쉴 수가 없다. 잡힌 손이 더 깊이 끈다.<br><br>동료들이 발목을 잡고 끌어냈다. 기침에 검은 가루가 섞여 나온다. 잡혔던 손을 펴니 손바닥에 명찰이 쥐여 있었다. 석탄 가루 하나 안 묻은 명찰이.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-26, spirit:-22 } }
  ] },

{ at:'A', t:'내려가는 길 — 바뀐 분필 화살표',
  x:`굽이마다 벽에 분필로 화살표를 긋는다. 돌아갈 길이다. 땅 밑에서 길을 잃으면 그걸로 끝이다.<br><br>
    돌아보니 화살표가 바뀌었다. 아까 그은 것이 다른 쪽을 가리킨다. 분필 자국이 새것이다.<br>
    누가 이쪽 화살표를 지우고 다시 그었다. 이쪽 글씨체로. 똑같이.<br><br>
    화살표가 가리키는 쪽이 어둡다. 아까 온 길보다 더.`,
  o:[
    { l:'① 이쪽만 아는 표시를 찾는다.', k:'gaze', dc:22, wake:1,
      ok:`화살표 꼬리를 봤다. 이쪽은 화살표 꼬리에 짧은 줄 셋을 긋는다. 들어간 날 수. 오래된 버릇이다. 아무에게도 말한 적 없다.<br><br>새 화살표 꼬리에 줄이 없다. 흉내 낸 것은 화살표만 흉내 냈다. 꼬리는 몰랐다. 벽 아래쪽을 더듬자 지워진 원래 화살표가 희미하게 남았다. 꼬리에 줄 셋.<br><br>표시는 길을 남기는 것이었다. 이쪽만 아는 꼬리를 다는 순간 표시가 이쪽을 증명한다. 흉내 낼 수 없는 것을 하나씩 섞는 손이 됐다. 그 뒤로 화살표마다 꼬리를 바꿔 달았다. 굽이마다 다르게.`,
      ng:`꼬리를 봤다. 줄이 셋 있다. 이쪽 버릇까지 흉내 냈다. 어느 쪽이 진짜인지 모른다.<br><br>벽 아래쪽을 더듬었다. 다른 화살표가 또 있다. 줄 셋. 그 옆에 또. 벽 전체에 화살표가 빼곡하다. 다 이쪽 글씨다. 다 다른 쪽을 가리킨다.<br><br>한참 섰다가 발밑을 봤다. 이쪽 발자국을 따라 돌아갔다. 발자국은 흉내 내지 않았다. 아직은.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-20, spirit:-24 } },
    { l:'② 새 화살표를 따라가 본다.', k:'luck', dc:23,
      doom:{ title:'새 화살표', what:'화살표 끝 어둠 속으로 끌려갑니다', dc:18, sec:45,
        text:`새 화살표를 따라갔다. 다음 굽이에도 화살표가 있다. 그다음에도. 이쪽 글씨다. 친절하게 계속 이어진다.<br><br>굽이가 좁아진다. 천장이 낮아진다. 마지막 화살표가 바닥을 가리킨다. 아래로. 바닥에 구멍이 있다.<br>구멍 앞에서 돌아서는데 발목이 잡혔다. 구멍 속에서. 손에 분필 가루가 묻어 있다. 당긴다. 아래로. 화살표가 가리키는 쪽으로. 굽이마다 그은 화살표가 다 이쪽을 여기로 데려오려고 그은 것이었다.`,
        dieText:`남은 사람들이 원래 화살표를 찾아 돌아 나왔다.<br><br>나오는 길에 벽마다 새 화살표가 하나씩 늘어 있었다. 이쪽 글씨다. 꼬리에 줄이 넷이다.<br>들어간 날 수가 하루 더 늘었다. 아무도 그 화살표를 따라가지 않았다.` },
      ok:`새 화살표를 따라가되 굽이마다 이쪽 표시를 따로 그었다. 꼬리를 바꿔서. 다음 굽이에도 새 화살표. 따라갔다. 또 그었다.<br><br>셋째 굽이에서 바닥에 구멍이 나왔다. 화살표가 아래를 가리킨다. 거기서 멈췄다. 이쪽이 그은 표시를 거꾸로 따라 돌아 나왔다.<br><br>원래 길로 돌아왔다. 벽의 새 화살표가 이쪽이 돌아간 쪽으로 다시 바뀌어 있었다. 따라오는 것이다. 표시를 지우며.`,
      win:{ exp:20, dream:3 } }
  ] },

{ at:'A1', t:'세트 뒤 — 바닥 밑 케이블 굴',
  x:`세트 뒤 바닥에 판자 뚜껑이 있다. 열면 좁은 도랑이다. 케이블이 다니는 굴이다. 무대 반대편으로 이어진다.<br><br>
    이런 굴은 익숙하다. 기어서 지나는 굴. 무릎과 팔꿈치로.<br>
    케이블이 굴 바닥에 수십 가닥 깔렸다. 굵고 검다. 아주 천천히 꿈틀댄다. 전기가 흐르는 게 아니다.<br><br>
    위쪽 무대에서는 무대 감독이 다음 순서를 찾는다. 위로 가면 들킨다.`,
  o:[
    { l:'① 굴로 기어 들어가 케이블 위를 지난다.', k:'steady', dc:23,
      doom:{ title:'케이블 굴', what:'케이블에 감겨 굴 안쪽으로 끌려갑니다', dc:18, sec:45,
        text:`굴에 들어갔다. 팔꿈치와 무릎으로 기었다. 케이블이 배 밑에서 꿈틀댄다. 무시하고 기었다.<br><br>가운데쯤에서 케이블 하나가 발목을 감았다. 하나, 둘. 허벅지, 허리. 감기는 게 아니라 끌고 간다. 굴 안쪽으로. 무대 반대편이 아니라 굴이 꺾이는 데로. 거기서 케이블이 다 한 데로 모인다.<br>팔꿈치로 바닥을 긁었다. 판자 바닥에 손톱이 박힌다. 끌려간다. 앞쪽 어둠에서 웅 하는 소리가 난다. 송출 장비 소리다.`,
        dieText:`무대 반대편 판자 뚜껑이 열려 있다. 굴에서 아무도 나오지 않았다.<br><br>세트 뒤 모니터 하나에 화면이 켜졌다. 굴 속이 나온다. 케이블이 다 한 데로 모인 자리에 무엇이 웅크렸다. 케이블에 감긴 채로.<br>화면 아래 자막. 송출선 점검 중.` },
      ok:`굴에 들어가기 전에 곡괭이를 앞으로 내밀었다. 기면서 곡괭이 끝을 판자 바닥에 박고 몸을 당겼다. 박고, 당기고.<br><br>가운데쯤에서 케이블이 발목을 감았다. 당긴다. 곡괭이가 박혀 버틴다. 케이블이 한참 당기다 풀렸다. 박힌 것은 끌기 어렵다.<br><br>무대 반대편 뚜껑을 밀고 나왔다. 돌아보니 굴 속 케이블들이 곡괭이 박았던 자국마다 감겨 있다. 거기 무엇이 있었던 것처럼.`,
      win:{ exp:20, dream:3 } },
    { l:'② 굴 위 판자를 밟고 간다 — 판자 소리를 들으며.', k:'sense', dc:22,
      ok:`굴 뚜껑 판자 위를 따라 걸었다. 발바닥으로 판자 소리를 들었다. 텅 빈 데는 굴 위, 꽉 찬 데는 들보 위. 꽉 찬 데만 디뎠다.<br><br>판자 밑에서 케이블이 꿈틀대는 소리가 따라온다. 판자 틈으로 올라오려 한다. 들보 위는 틈이 없다.<br><br>무대 감독이 고개를 돌렸다. 이쪽은 들보 그늘에 섰다. 소리 나지 않는 판자 위에. 무대 감독이 다른 쪽을 가리켰다. 다음 순서는 거기 없었다.`,
      ng:`판자를 밟는데 한 장이 텅 울렸다. 크게. 무대 감독이 돌아본다.<br><br>판자 틈으로 케이블이 올라와 발목을 감았다. 무대 감독이 손가락을 접는다. 셋, 둘.<br><br>케이블을 곡괭이로 끊었다. 끊긴 데서 검은 물이 흘렀다. 그 틈에 뛰었다. 발목에 케이블 감긴 자국이 나선으로 남았다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-24, mind:-18 } }
  ] },

{ at:'A2', t:'교실동 — 물 밑 계단',
  x:`교실동 끝에 물 밑으로 내려가는 계단이 있다. 아래층은 다 잠겼다. 숨을 참고 가야 한다.<br><br>
    계단이 중간에서 둘로 갈라진다. 물속이라 어느 쪽이 다음 층 복도로 이어지는지 안 보인다.<br>
    땅 밑에서는 바람으로 길을 안다. 바람이 드는 쪽이 밖이다. 물속도 비슷하다. 흐름이 있다.<br><br>
    두 계단 다 아래로 사람 머리카락이 흘러 나와 있다. 흐름을 따라 흔들린다.`,
  o:[
    { l:'① 손등으로 물 흐름을 읽는다.', k:'sense', dc:22,
      ok:`계단참 물속에 손등을 담갔다. 오래. 차다. 손등 털이 한쪽으로 눕는다. 왼쪽 계단에서 오른쪽 계단으로 물이 흐른다.<br><br>흘러 나가는 쪽이 열린 쪽이다. 오른쪽. 그런데 왼쪽 계단 머리카락은 흐름을 거슬러 흔들린다. 누가 아래서 쥐고 흔드는 것이다.<br><br>오른쪽으로 갔다. 숨을 참고 내려가 복도에 닿았다. 왼쪽 계단 아래에서 머리카락이 쑥 빨려 들어갔다. 미끼를 거두는 것처럼.`,
      ng:`손등을 담갔다. 흐름이 안 느껴진다. 물이 고였다. 대신 손등에 머리카락이 감겼다. 왼쪽 계단에서 흘러온 것이다.<br><br>감긴 머리카락이 당긴다. 아래로. 손을 빼려는데 더 감긴다. 손목까지.<br><br>칼로 끊었다. 손목에 머리카락이 파고든 자국이 줄줄이 남았다. 오른쪽 계단으로 내려갔다. 운이 좋았다. 다음엔 모른다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-22, spirit:-22 } },
    { l:'② 곡괭이로 계단 난간을 두드려 소리로 찾는다.', k:'fix', dc:22,
      ok:`곡괭이 머리로 난간을 두드렸다. 물속에서 소리가 퍼진다. 왼쪽 계단에서 소리가 금방 돌아온다. 막혔다. 오른쪽은 소리가 멀리 갔다가 늦게 돌아온다. 열렸다.<br><br>그런데 왼쪽에서 돌아온 소리 끝에 다른 소리가 붙었다. 손톱으로 난간 긁는 소리. 대답이다.<br><br>오른쪽으로 갔다. 숨을 참고. 복도에 닿아 머리를 내밀었다. 왼쪽 계단 쪽에서 난간 두드리는 소리가 들렸다. 이쪽 박자로. 흉내다.`,
      ng:`두드렸다. 소리가 물속에서 뭉개진다. 어느 쪽인지 모르겠다. 그런데 소리를 들은 것들이 있다.<br><br>두 계단 아래에서 머리가 올라온다. 하나씩. 소리 난 쪽으로. 계단참이 금방 찼다.<br><br>숨을 참고 그 사이를 비집고 내려갔다. 아무 쪽이나. 운 좋게 복도였다. 어깨에 손자국 셋. 비집을 때 짚인 것이다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, mind:-18 } }
  ] },

{ at:'A', t:'좁은 굴 — 무너진 뒤',
  x:`굴이 무너졌다. 맨 뒤 동료가 묻혔다. 흙 더미 속이다.<br><br>
    흙 속에서 두드리는 소리가 난다. 똑, 똑, 똑. 살아 있다. 이 소리가 나면 판다. 무조건.<br>
    그런데 소리가 두 군데서 난다. 하나는 흙 더미 왼쪽 아래. 하나는 오른쪽 위. 박자가 같다.<br><br>
    묻힌 사람은 하나다. 파는 손은 하나다.`,
  o:[
    { l:'① 두드림 박자를 오래 듣고 진짜 쪽을 판다.', k:'steady', dc:22,
      ok:`흙에 귀를 대고 들었다. 같은 박자다. 그런데 오른쪽 위는 쉬는 데가 늘 같다. 왼쪽 아래는 쉬는 데가 조금씩 길어진다. 숨이 찬다. 지친다.<br><br>지치는 쪽이 사람이다. 왼쪽 아래를 팠다. 손으로. 곡괭이는 위험하다. 손톱이 깨졌다. 팠다.<br><br>손이 나왔다. 따뜻하다. 동료다. 끌어냈다. 기침을 하며 흙을 토한다. 오른쪽 위에서 두드림이 계속됐다. 지치지 않는 박자로. 끝까지.`,
      ng:`들었다. 같다. 구별이 안 된다. 왼쪽을 팠다. 손이 나왔다. 차다.<br><br>잡아 끌었다. 손이 이쪽 손을 마주 쥐고 흙 속으로 당긴다. 오른쪽 위 두드림이 빨라진다. 진짜가 오른쪽이었다.<br><br>손을 뿌리치고 오른쪽을 팠다. 늦었다. 동료를 끌어냈을 때 숨이 거의 없었다. 살았다. 겨우. 왼쪽 흙 속 손이 아직 밖으로 나와 흔들리고 있었다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-26, spirit:-24 } },
    { l:'② 버팀목부터 세우고 판다.', k:'fix', dc:22,
      ok:`서두르지 않았다. 남은 천장부터 봤다. 결이 바뀌는 자리에 굴러온 기둥을 세웠다. 쐐기를 박았다. 또 무너지면 둘이 묻힌다.<br><br>버팀목이 서자 두드림이 한쪽에서 멈췄다. 오른쪽 위. 버팀목이 그 자리 흙을 눌렀다. 거기 있던 것이 눌려 조용해졌다.<br><br>남은 소리를 따라 팠다. 동료가 나왔다. 버팀목 밑 흙에서 무엇이 꿈틀하다 멈췄다.`,
      ng:`버팀목을 세우는데 시간이 걸렸다. 그사이 두 두드림이 다 약해졌다.<br><br>한쪽이 멈췄다. 어느 쪽인지 모른다. 남은 쪽을 팠다. 손이 나왔다. 동료다. 살았다.<br><br>멈춘 쪽은 끝내 다시 두드리지 않았다. 그런데 그 밤 쉬는 자리 바닥에서 두드림이 났다. 똑, 똑, 똑. 이번엔 이쪽 등 밑에서.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-22, mind:-18 } },
    { l:'③ 오른쪽 위를 판다.', k:'luck', dc:22,
      ok:`오른쪽 위를 팠다. 감이다. 흙이 무르다. 금방 손이 닿았다. 동료 손이다. 따뜻하다. 끌어냈다.<br><br>동료가 기침을 하며 말한다. 왼쪽 아래에서도 누가 두드렸다고. 자기 옆에서. 같은 박자로 맞춰서. 자기 소리를 묻으려고.<br><br>왼쪽 아래는 파지 않았다. 흙 더미를 뒤로하고 갔다. 두드림이 등 뒤에서 한참 따라왔다. 박자가 점점 이쪽 걸음에 맞춰졌다.`,
      ng:`오른쪽 위를 팠다. 흙 속에서 손이 나왔다. 차다. 손바닥이 위를 본다. 손가락으로 흙 위를 톡톡 두드린다. 똑, 똑, 똑.<br><br>진짜는 왼쪽이었다. 돌아서서 왼쪽을 팠다. 손톱이 다 깨지도록. 동료를 끌어냈다. 숨이 끊기기 직전이었다.<br><br>오른쪽 위 손은 계속 두드렸다. 일행이 떠날 때까지. 작별 인사처럼.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-24, spirit:-22 } }
  ] },

{ at:'A', t:'쉬는 자리 — 곡괭이를 쥔 손',
  x:`한밤에 깼다. 곡괭이가 없다. 늘 손 닿는 데 둔다. 자루를 베고 잘 때도 있다.<br><br>
    어둠 속에서 쇠 끌리는 소리가 난다. 곡괭이 머리가 바닥을 긁는 소리다. 누가 끌고 다닌다.<br>
    소리가 잠든 동료들 사이를 돈다. 하나 앞에서 멈춘다. 들어 올리는 소리.<br><br>
    곡괭이 무게는 손이 안다. 들어 올린 높이를 소리로 안다. 머리 위다.`,
  o:[
    { l:'① 소리 나는 쪽으로 몸을 던져 자루를 쥔다.', k:'steady', dc:23,
      ok:`소리 쪽으로 몸을 던졌다. 어둠 속에서 손을 뻗었다. 자루가 손에 잡혔다. 이쪽 자루다. 손때가 안다.<br><br>자루를 쥔 다른 손이 있다. 차다. 둘이 같이 쥐었다. 당긴다. 이쪽이 더 오래 쥐어 온 자루다. 손이 놓았다.<br><br>불을 켰다. 곡괭이 끝이 잠든 동료 머리맡 한 뼘 위에 떠 있었다. 이쪽 손에 들린 채로. 동료는 그대로 잤다. 자루에 손자국이 하나 더 찍혀 있었다.`,
      ng:`몸을 던졌다. 허공이다. 소리가 다른 데서 난다. 이쪽 등 뒤에서.<br><br>쇠가 바닥을 찍었다. 이쪽 발 바로 옆이다. 돌이 튀어 정강이를 찢었다. 다시 들어 올리는 소리.<br><br>소리를 지르자 다들 깼다. 불이 켜졌다. 곡괭이는 이쪽 베개 자리에 반듯하게 놓여 있었다. 정강이 상처는 그대로였다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-28, mind:-16 } },
    { l:'② 등불을 켠다.', k:'sense', dc:22,
      ok:`손을 더듬어 등불을 켰다. 빛이 퍼진다. 쇠 소리가 뚝 멈췄다.<br><br>곡괭이가 동료들 한가운데 서 있다. 자루가 위로. 아무도 안 잡았다. 혼자 서 있다. 머리 쪽 쇠가 바닥에 박혀 있다.<br><br>뽑아 들었다. 박혔던 자리 바닥에 금이 갔다. 금 밑이 비었다. 곡괭이가 판 것이다. 이쪽 대신. 무엇을 꺼내려고. 그 구멍을 돌로 막고 곡괭이를 끌어안고 잤다.`,
      ng:`등불을 켜는데 부싯돌이 안 맞는다. 몇 번 쳤다. 불똥만.<br><br>그 사이 쇠 소리가 이쪽으로 온다. 끌리는 소리. 바로 앞에서 멈췄다. 들어 올리는 소리.<br><br>불이 붙었다. 앞에 아무도 없다. 곡괭이는 이쪽 무릎 위에 놓여 있다. 자루가 차다. 이쪽 손이 쥐고 있었다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-20, spirit:-24 } }
  ] },

{ at:'A1', t:'6층 계단 — 푹신한 바닥',
  x:`6층 계단 앞에 신발 벗는 곳이 있다. 놀이 세트로 들어가는 길이다. 바닥에 매트가 깔렸다. 푹신하다.<br><br>
    발바닥이 안다. 매트 밑이 비었다. 디딜 때마다 아래로 조금씩 꺼진다. 아래가 깊다.<br>
    벽에 그림판. 신발을 벗고 들어와요. 신발장에 작은 신발이 빼곡하다. 다 젖었다.<br><br>
    매트가 숨을 쉬듯 오르내린다.`,
  o:[
    { l:'① 곡괭이 자루로 매트를 두드려 디딜 데를 찾는다.', k:'sense', dc:22,
      ok:`자루 끝으로 매트를 한 뼘씩 눌렀다. 대부분 쑥 꺼진다. 몇 군데만 꽉 받친다. 매트 밑에 들보가 지나는 자리다.<br><br>그 자리에 분필로 동그라미를 그었다. 징검다리처럼. 일행이 동그라미만 디디고 건넜다.<br><br>마지막 사람이 건너자 매트 가운데가 푹 꺼졌다. 아래서 작은 손들이 매트를 끌어내렸다. 아무도 없는 것을 확인하고 다시 밀어 올렸다. 매트가 원래대로 평평해졌다.`,
      ng:`누르는데 매트 밑에서 무엇이 자루 끝을 쥐었다. 당긴다. 자루가 매트 속으로 들어간다.<br><br>놓지 않고 버텼다. 버티는 사이 이쪽 발밑 매트가 꺼졌다. 무릎까지 빠졌다. 매트가 다리를 감싼다. 푹신하게. 아래로.<br><br>동료들이 끌어냈다. 자루는 겨우 지켰다. 신발 한 짝이 없다. 신발장에 이쪽 신발이 한 짝 젖어 꽂혀 있었다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-24, mind:-18 } },
    { l:'② 매트를 걷어 내고 밑을 본다.', k:'break', dc:22,
      ok:`매트 끝을 곡괭이로 걸어 확 걷었다. 밑에 들보가 드러났다. 들보 사이가 깊다. 어둡다. 바닥이 안 보인다.<br><br>들보 사이 어둠에서 작은 얼굴들이 위를 본다. 빛을 보고 눈을 찌푸린다. 신발을 안 벗은 이쪽 발을 본다.<br><br>들보 위로만 디뎌 건넜다. 걷은 매트를 다시 덮지 않았다. 다음 사람이 보게. 들보 사이 얼굴들이 매트를 도로 끌어당기려 손을 뻗었다. 손이 짧았다.`,
      ng:`걷으려는데 매트가 무겁다. 밑에서 붙들고 있다. 확 당겼다. 매트가 찢어졌다.<br><br>찢어진 틈으로 손이 쏟아져 나왔다. 작은 손들. 이쪽 다리를, 곡괭이를 쥔다. 놀자고.<br><br>곡괭이 자루로 쳐 내며 뒷걸음질했다. 계단까지. 다리에 작은 손톱자국이 빼곡하다. 찢어진 매트 틈에서 웃음소리가 오래 났다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, spirit:-20 } }
  ] },

{ at:'A2', t:'체육관 — 공기 냄새',
  x:`체육관 천장 철골 밑에 공기가 고였다. 머리만 내밀면 숨을 쉰다. 철골을 따라가야 한다.<br><br>
    공기 냄새를 안다. 나쁜 공기는 달다. 단 공기를 마시면 졸리다. 졸리면 끝이다.<br>
    철골마다 공기가 다르다. 어떤 데는 비리고 어떤 데는 달다. 단 데에서 동료 하나가 벌써 눈을 감았다 뜬다.<br><br>
    단 공기 철골 밑 물속에 학생 하나가 떠 있다. 자는 얼굴이다.`,
  o:[
    { l:'① 철골마다 공기를 맡아 비린 데만 고른다.', k:'sense', dc:22,
      ok:`철골마다 코를 대고 한 번씩 맡았다. 길게 마시지 않았다. 비린 데, 비린 데, 단 데. 단 데는 건너뛰었다. 숨을 참고.<br><br>비린 공기는 물 냄새가 나도 숨이다. 단 공기는 숨 같아도 숨이 아니다. 졸던 동료 뺨을 쳐서 깨우고 비린 철골로 데려갔다.<br><br>탈의실 문에 닿았다. 돌아보니 단 공기 철골 밑 학생이 눈을 떴다. 이쪽을 본다. 같이 자자고 하는 얼굴이다. 다시 눈을 감았다.`,
      ng:`맡았다. 그런데 냄새가 섞였다. 비린 데에도 단 맛이 조금. 구별이 안 된다.<br><br>한 철골에서 숨을 오래 쉬었다. 달았다. 졸음이 쏟아진다. 철골을 쥔 손이 풀린다. 물이 턱, 코.<br><br>동료가 머리채를 잡아 올렸다. 눈을 뜨니 물속에서 자던 학생이 이쪽 발목을 쥐고 있었다. 같이 자려고.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-26, mind:-16 } },
    { l:'② 숨을 아껴 세며 단 데를 참고 지난다.', k:'steady', dc:22,
      ok:`단 데를 지날 때 숨을 참았다. 세었다. 하나에서 서른까지. 서른이면 다음 철골이다. 일행에게도 손가락으로 셈을 보였다.<br><br>다섯이 같이 셌다. 단 데를 셋 지났다. 아무도 졸지 않았다. 숨을 아끼는 것은 땅 밑에서 배운다. 무너진 갱도에서, 공기가 반 남았을 때.<br><br>탈의실 문에 닿아 한꺼번에 숨을 쉬었다. 비린 공기가 폐를 채웠다. 맛있었다.`,
      ng:`참고 셌다. 스물에서 숨이 찼다. 단 데가 길다. 서른까지 못 버틴다.<br><br>한 모금 마셨다. 달다. 머리가 흐려진다. 셈이 엉킨다. 스물, 열, 다섯. 거꾸로 센다. 눈이 감긴다.<br><br>동료들이 끌고 갔다. 탈의실 문 앞에서 깼다. 입안이 달았다. 한나절 내내 졸음이 따라왔다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-22, spirit:-24 } }
  ] },

{ at:'A', t:'좁은 구멍 — 기어서 지나는 길',
  x:`길이 구멍 하나로 줄었다. 기어서 지나야 한다. 길다. 끝이 안 보인다.<br><br>
    기는 굴을 안다. 팔꿈치와 무릎, 앞으로만. 뒤로는 못 돌아선다.<br>
    앞서 들어간 동료가 소리친다. 뒤에서 누가 발목을 잡는다고. 그 동료 뒤에는 이쪽이 있다. 이쪽은 아직 들어가지 않았다.<br><br>
    구멍 안 어딘가에 사람 아닌 것이 끼어 있다. 기는 사람들 사이에.`,
  o:[
    { l:'① 곡괭이를 앞에 박아 당기며 기어간다.', k:'steady', dc:22, wake:1,
      ok:`곡괭이를 앞으로 내밀고 들어갔다. 자루를 짧게 쥐고 앞 바닥에 끝을 박았다. 당겼다. 몸이 앞으로 간다. 또 박고, 또 당기고.<br><br>중간쯤에서 발목이 잡혔다. 뒤에서 당긴다. 곡괭이가 박혀 버틴다. 이쪽은 곡괭이에 매달렸다. 뒤의 것이 당기다 놓았다. 박힌 것과 다투면 진다.<br>앞 동료 발목을 잡고 있던 것도 이쪽 곡괭이 소리를 듣고 놓았다.<br><br>곡괭이는 파는 것이었다. 박으면 붙드는 것이 된다. 기든 매달리든 앞에 박을 데만 있으면 몸이 끌려가지 않는다. 곡괭이를 쥐는 손이 그 쓸모를 하나 더 외웠다. 구멍 끝에서 곡괭이 끝이 무뎌져 있었다.`,
      ng:`박고 당기며 갔다. 중간쯤에서 곡괭이 끝이 박히지 않았다. 바닥이 돌이다. 미끄러졌다.<br><br>그 순간 발목이 당겨졌다. 뒤로. 한 뼘. 두 뼘. 팔꿈치로 버틴다. 살갗이 벗겨진다.<br><br>앞의 동료가 손을 뒤로 뻗어 곡괭이 자루를 잡아 줬다. 둘이 같이 당겼다. 발목이 풀렸다. 구멍을 빠져나와서 보니 발목에 감긴 자국. 손이 아니다. 머리카락이다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-28, mind:-16 } },
    { l:'② 뒤를 걷어차며 빨리 기어간다.', k:'evade', dc:23,
      doom:{ title:'기는 굴', what:'굴 뒤쪽으로 발목을 잡혀 끌려갑니다', dc:18, sec:45,
        text:`빨리 기었다. 발목에 무엇이 닿을 때마다 걷어찼다. 한 번. 두 번.<br><br>세 번째에 찬 발이 잡혔다. 발목이 아니라 발 전체를. 손 둘이 감싸 쥔다. 당긴다. 뒤로. 기던 방향 반대로. 팔꿈치가 바닥에서 미끄러진다.<br>굴은 뒤로 돌아설 수 없다. 앞으로만 가는 길이다. 뒤로 끌려가는 몸이 굴 벽에 긁힌다. 앞 동료 발이 멀어진다. 뒤쪽 어둠이 넓어진다. 굴이 아니라 방이다.`,
        dieText:`구멍 끝으로 넷이 기어 나왔다. 하나가 없다.<br><br>구멍 안에서 기는 소리가 난다. 팔꿈치와 무릎. 앞으로 오는 소리다. 아주 천천히.<br>아무도 구멍을 들여다보지 않았다. 기어 나오는 것이 누구 얼굴을 하고 있을지 알 것 같아서.` },
      ok:`빨리 기었다. 발목에 닿는 것을 걷어찼다. 찬 발이 무엇의 얼굴에 맞았다. 물렁하다. 뒤에서 멈칫하는 기척.<br><br>그 틈에 앞 동료 발뒤꿈치를 밀었다. 같이 빨리. 둘이 붙어 기었다. 뒤의 것이 다시 쫓아오지 못했다. 찬 얼굴이 아픈 모양이다.<br><br>구멍 끝으로 빠져나왔다. 신발 코에 하얀 분 같은 것이 묻었다. 얼굴에 바른 것이다.`,
      win:{ exp:20, dream:3 } }
  ] },

{ at:'A1', t:'부조정실 — 방음벽 속의 노크',
  x:`5층 부조정실 벽은 방음재로 덮였다. 두툼한 천과 솜이다. 소리를 먹는다.<br><br>
    방음벽 속에서 두드리는 소리가 난다. 똑, 똑, 똑. 쉬고. 똑, 똑, 똑. 땅 밑에서 쓰는 박자다. 갇혔다, 살아 있다.<br>
    방음재는 소리를 먹는다. 그런데 이 소리는 새어 나온다. 아주 세게 두드리는 것이다. 오래.<br><br>
    두드리는 높이가 낮다. 아이 키다.`,
  o:[
    { l:'① 방음재를 뜯어 본다.', k:'break', dc:22,
      ok:`곡괭이 끝으로 방음재 천을 찢었다. 솜을 걷어 냈다. 안에 벽이 있다. 벽에 작은 문이 하나. 점검구다.<br><br>점검구를 열었다. 안이 좁다. 아무도 없다. 바닥에 크레용이 굴러다닌다. 벽에 그림. 해, 꽃, 웃는 사람들. 그리고 셈을 한 줄. 사흘, 나흘, 닷새.<br><br>점검구 안쪽 문고리가 없다. 안에서는 못 연다. 두드리는 소리가 그쳤다. 이쪽이 열었으니까. 늦었지만.`,
      ng:`찢었다. 솜이 쏟아진다. 솜 속에서 손이 나왔다. 작은 손. 이쪽 곡괭이 끝을 쥔다.<br><br>당긴다. 방음벽 속으로. 솜이 이쪽 얼굴을 덮는다. 숨이 막힌다. 소리를 지르는데 방음재가 먹는다.<br><br>동료들이 허리를 끌어당겼다. 솜에서 빠져나왔다. 곡괭이를 놓쳤다. 방음벽 속에서 곡괭이로 두드리는 소리가 났다. 똑, 똑, 똑.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, mind:-18 } },
    { l:'② 두 번 두드려 대답한다 — 기다려라.', k:'bond', dc:22,
      ok:`곡괭이 자루로 방음벽을 두 번 두드렸다. 기다려라. 땅 밑에서 쓰는 대답이다.<br><br>안에서 두드림이 멈췄다. 한참. 그리고 두 번. 알았다. 대답을 아는 것이다.<br><br>이쪽은 꺼내 줄 수 없다. 그래도 기다리라고 했다. 부조정실을 나서는 내내 방음벽 속에서 두 번씩 두드리는 소리가 났다. 기다릴게. 기다릴게.`,
      ng:`두 번 두드렸다. 안에서 두드림이 멈췄다. 그리고 방음벽이 부풀었다. 안에서 민다. 기다리지 않는다.<br><br>방음재가 찢기며 손이 나왔다. 이쪽 손목을 쥔다. 기다렸다고. 오래 기다렸다고.<br><br>뿌리쳤다. 손목에 작은 손톱자국 다섯. 방음벽 속에서 우는 소리가 났다. 방음재가 다 먹지 못했다.`,
      win:{ exp:16, dream:3 }, lose:{ mind:-18, spirit:-24 } }
  ] },

{ at:'A2', t:'무대 뒤 — 벽 속의 결석생',
  x:`지하 강당 무대 뒤. 벽이 젖은 벽돌이다. 한 군데만 벽돌 색이 다르다. 새로 쌓았다.<br><br>
    무대 쪽에서 출석을 부른다. 이름 하나에 대답 하나. 그런데 한 이름에서 대답이 벽 속에서 온다. 아주 작게. 네.<br>
    결석으로 처리되는 이름이다. 매번. 대답이 벽에 막혀 무대까지 가지 않는다.<br><br>
    벽은 두드려 보면 안다. 무엇이 있는지. 얼마나 깊은지.`,
  o:[
    { l:'① 벽을 두드려 대답을 센다.', k:'steady', dc:22, wake:1,
      ok:`새로 쌓은 벽돌을 곡괭이 자루로 두드렸다. 텅. 뒤가 비었다. 사람 하나 설 깊이.<br><br>한 번 두드리고 들었다. 벽 속에서 한 번 온다. 두 번 두드렸다. 두 번. 세 번에 세 번. 박자를 따라 한다. 흉내가 아니다. 대답이다. 셈을 아는 것이다.<br>네 번을 두드렸다. 벽 속에서 세 번이 왔다. 그리고 멈췄다. 힘이 다했다. 사람이다. 아니었던 것이 아니다.<br><br>두드리면 대답이 온다. 대답의 박자에서 대답하는 것의 숨이 들린다. 흉내 내는 것은 지치지 않는다. 지치는 것은 사람이다. 벽 너머의 숨을 박자로 재는 귀가 그날 생겼다. 출석이 다시 그 이름을 불렀다. 벽 속에서 대답하지 않았다. 이쪽이 대신 대답했다. 네.`,
      ng:`두드렸다. 벽 속에서 대답이 왔다. 그런데 너무 많이 온다. 한 번에 열 번. 스무 번. 벽 전체에서.<br><br>새로 쌓은 벽만이 아니다. 무대 뒤 벽 전체가 비어 있다. 다 대답한다. 결석생이 하나가 아니다.<br><br>귀를 막고 물러섰다. 출석은 계속 결석을 불렀다. 결석, 결석, 결석. 그날 밤 꿈에 벽돌 쌓는 소리가 났다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-20, spirit:-26 } },
    { l:'② 곡괭이로 새 벽돌을 깬다.', k:'break', dc:23,
      ok:`곡괭이로 새 벽돌 사이 줄눈을 쳤다. 젖은 회반죽이 무르다. 한 장씩 빠졌다.<br><br>안이 보였다. 좁은 틈. 젖은 교복이 벽에 기대 서 있다. 안에 사람은 없다. 명찰만 가슴에. 이름 칸에 실이 새것이다.<br><br>명찰을 떼어 무대 쪽으로 던졌다. 물속 명찰 줄로 떨어졌다. 출석이 그 이름을 불렀다. 무대 쪽에서 대답이 났다. 네. 처음으로 출석이었다.`,
      ng:`쳤다. 벽돌이 빠지는데 회반죽 속에서 손톱이 나왔다. 회반죽에 박힌 손톱들. 안에서 긁은 것이다.<br><br>벽이 무너지며 안의 것이 이쪽으로 쓰러졌다. 젖고 차다. 이쪽을 끌어안는다. 꺼내 줘서 고맙다는 듯이. 놓지 않는다.<br><br>동료들이 떼어 냈다. 젖은 교복만 남았다. 이쪽 가슴에 축축한 자국이 사람 모양으로 남았다. 명찰 자국까지.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-26, spirit:-22 } }
  ] },

{ at:'A', t:'불침번 — 발밑의 소리',
  x:`불침번이다. 바닥에 앉아 있는데 엉덩이 밑에서 소리가 난다. 아주 작게. 긁는 소리.<br><br>
    이 소리를 안다. 누가 판다. 땅 밑에서. 위를 향해.<br>
    소리가 가까워진다. 아주 느리게. 밤새 파면 새벽에는 닿는다.<br><br>
    어디로 올라오는지는 모른다. 일행이 잠든 데 중 하나다.`,
  o:[
    { l:'① 바닥에 귀를 대고 소리의 깊이와 자리를 잰다.', k:'sense', dc:22, wake:1,
      ok:`바닥에 엎드려 귀를 댔다. 한 자리. 옮겨서 또 한 자리. 소리가 제일 큰 데를 찾았다. 잠든 동료 하나 밑이다.<br><br>깊이도 쟀다. 긁는 소리와 흙 떨어지는 소리 사이. 그 사이가 짧을수록 가깝다. 아직 팔 길이 셋쯤.<br>동료를 깨워 옮겼다. 그 자리에 돌을 쌓았다. 새벽에 돌 밑에서 소리가 멎었다. 막혔다.<br><br>땅 밑 소리는 무엇이 있는지만 말하는 줄 알았다. 얼마나 깊은지, 언제 닿는지도 말한다. 귀가 소리 사이의 틈으로 거리를 재기 시작했다. 그 뒤로 바닥에 앉으면 저절로 그 틈부터 들렸다.`,
      ng:`귀를 댔다. 소리가 사방에서 난다. 하나가 아니다. 셋. 다섯. 다 위로 판다.<br><br>어디가 제일 가까운지 모르겠다. 바닥 전체가 긁힌다. 귀를 떼고 일행을 다 깨웠다. 다 같이 높은 바위 위로 올라갔다.<br><br>새벽에 내려다봤다. 잠자리마다 구멍이 났다. 사람 머리 크기. 다섯 개. 정확히 머리 자리에.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-20, spirit:-24 } },
    { l:'② 일행을 깨워 단단한 바위 위로 옮긴다.', k:'steady', dc:22,
      ok:`곡괭이로 둘레 바닥을 두드렸다. 텅, 텅, 꽉. 꽉 찬 데가 있다. 통바위다. 그 위로 일행을 깨워 옮겼다.<br><br>밤새 긁는 소리가 바위 둘레를 돌았다. 바위는 못 판다. 둘레만 판다. 새벽에 둘레에 구멍이 빙 둘러 났다. 바위 가장자리를 손가락이 짚고 있다.<br><br>해가 들자 손가락들이 구멍으로 내려갔다. 바위 위 다섯은 다 다섯이었다.`,
      ng:`옮기려고 깨웠다. 하나가 일어나지 않는다. 깨워도 눈만 뜬다. 바닥을 보며. 소리를 듣고 있다.<br><br>그 동료가 손으로 바닥을 판다. 마주 파는 것이다. 소리 쪽을 향해. 손톱이 깨지는데 멈추지 않는다.<br><br>끌어안아 바위로 올렸다. 동료가 버둥거린다. 새벽에 깼다. 손이 피투성이다. 마중 나가고 싶었다고 했다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-22, spirit:-24 } }
  ] },

{ at:'A', t:'쉬는 자리 — 버팀목에 기댄 것',
  x:`쉬는 자리 천장이 낮다. 버팀목 하나가 받친다. 낡았지만 아직 선다.<br><br>
    한밤에 버팀목이 운다. 끼익. 무게가 늘었다. 불을 비추니 버팀목에 무엇이 기대 있다. 등을 대고. 무릎을 끌어안고.<br>
    버팀목이 받는 무게를 안다. 천장 무게에 사람 하나가 더해지면 어떻게 되는지도.<br><br>
    끼익. 또 운다. 기댄 것이 조금 더 무거워졌다.`,
  o:[
    { l:'① 버팀목 옆에 하나를 더 세운다.', k:'fix', dc:22,
      ok:`짐 속 쪼갠 장작을 이어 묶었다. 기둥 하나가 됐다. 낡은 버팀목 옆, 천장 결이 바뀌는 자리에 세웠다. 쐐기를 박았다.<br><br>새 기둥이 무게를 반 받았다. 낡은 버팀목 우는 소리가 멎었다. 기댄 것이 고개를 든다. 새 기둥을 본다.<br><br>그것이 새 기둥으로 옮겨 기댔다. 무게가 넘어간다. 새 기둥이 받는다. 장작은 새것이다. 버틴다. 그것은 아침까지 새 기둥에 기대 있었다.`,
      ng:`세우는데 쐐기가 튀었다. 천장에서 돌가루가 쏟아진다.<br><br>기댄 것이 일어섰다. 이쪽으로 걸어온다. 이쪽 어깨에 기댄다. 무겁다. 천장 무게가 이쪽 어깨로 옮겨 온 것 같다.<br><br>무릎이 꺾일 때까지 버텼다. 동료가 기둥을 마저 세웠다. 어깨가 가벼워졌다. 어깨에 젖은 등 자국이 남았다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-24, mind:-18 } },
    { l:'② 버팀목에 기댄 것을 들여다본다.', k:'gaze', dc:22,
      ok:`등불을 가까이 댔다. 기댄 것이 고개를 들었다. 얼굴이 흙투성이다. 안전모를 썼다. 낡은 것이다. 앞에 등불 고리가 달렸다.<br><br>광부다. 오래전의. 버팀목을 지키는 자세로 기대 있다. 천장이 무너지지 않게 등으로 받치고 있다. 무거워진 게 아니다. 받치느라 힘을 쓰는 것이다.<br><br>그 옆에 등불을 하나 두고 물러났다. 그것이 아주 조금 고개를 숙였다. 버팀목은 밤새 울지 않았다.`,
      ng:`들여다봤다. 기댄 것이 고개를 들었다. 얼굴이 없다. 흙이 얼굴 모양으로 뭉쳐 있다.<br><br>흙 얼굴이 입을 연다. 흙이 쏟아진다. 버팀목이 크게 울었다. 천장에서 돌이 떨어진다.<br><br>일행을 깨워 뛰쳐나왔다. 뒤에서 천장이 반쯤 내려앉았다. 짐 반을 두고 왔다. 흙 얼굴은 무너진 데 속에서 계속 기대 있었다.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-26, spirit:-22 } },
    { l:'③ 천장을 두드려 얼마나 버틸지 잰다.', k:'steady', dc:23,
      doom:{ title:'기댄 무게', what:'내려앉은 천장 돌에 깔렸습니다', dc:18, sec:45,
        text:`곡괭이 자루로 천장을 두드렸다. 꽉, 꽉, 텅. 텅 빈 데가 버팀목 바로 위다. 금이 갔다.<br><br>두드린 소리에 기댄 것이 일어섰다. 버팀목에서 등을 뗐다. 받치던 것이 손을 놓았다.<br>천장이 내려앉는다. 버팀목이 꺾인다. 돌이 쏟아진다. 다리를 덮었다. 허리. 등. 숨 쉴 틈이 손바닥만큼 남았다. 그 틈으로 흙이 계속 흘러든다.`,
        dieText:`쉬는 자리 한쪽이 막혔다. 돌 더미다.<br><br>돌 사이로 곡괭이 자루가 비죽 나와 있다. 버팀목처럼 위를 받친 자세로.<br>그 자루에 무엇이 기대 앉았다. 등을 대고, 무릎을 끌어안고. 끼익. 자루가 울었다.` },
      ok:`천장을 두드렸다. 꽉, 꽉, 텅. 버팀목 바로 위가 비었다. 금이 갔다. 버팀목과 기댄 것이 같이 그 금을 받치고 있다.<br><br>두드리기를 멈췄다. 소리가 그것을 놀라게 하면 안 된다. 일행을 소리 없이 깨워 쉬는 자리 밖으로 하나씩 내보냈다. 마지막에 이쪽이 나왔다.<br><br>나오고 세 걸음 뒤에 기댄 것이 일어섰다. 천장이 내려앉았다. 세 걸음이면 충분하다. 돌 더미 너머에서 그것이 다시 기대 앉는 소리가 났다.`,
      win:{ exp:20, dream:3 } }
  ] },

{ at:'A', t:'나가는 길 — 다시 센다',
  x:`나가는 문 앞이다. 나갈 때 센다. 들어갈 때와 맞아야 하루가 끝난다.<br><br>
    들어갈 때 다섯이었다. 어깨 여섯을 짚고 숨 다섯을 들었다.<br>
    지금 문 앞에 선 그림자가 여섯이다. 등불 하나에 그림자 여섯.<br><br>
    광부의 규칙은 하나다. 안 맞으면 다시 들어간다. 맞을 때까지.`,
  o:[
    { l:'① 소리 내어 센다 — 이름과 숨과 그림자를 하나씩 맞춘다.', k:'steady', dc:22, wake:1,
      ok:`등불을 바닥에 내려놓고 하나씩 불렀다. 이름. 대답. 숨. 그림자. 하나. 이름, 대답, 숨, 그림자. 둘. 다섯까지 맞췄다.<br><br>여섯째 그림자가 남았다. 이름도 대답도 숨도 없다. 그림자만 있다. 그것에게 말했다. 넌 셈에 없다. 그림자가 문 반대쪽으로 길게 늘어나더니 끊어졌다.<br><br>세는 일이 길을 끝낸다. 숫자 하나에 이름과 숨과 그림자를 다 꿰어야 셈이 선다. 하나라도 빠지면 셈에서 내보낸다. 그 셈이 문 앞에서 이쪽 손에 쥐어진 도구가 됐다. 다섯. 들어갈 때와 같다. 하루가 끝났다.`,
      ng:`불렀다. 이름, 대답, 숨, 그림자. 다섯까지 맞았다. 여섯째 그림자가 남았다. 그런데 그림자가 대답했다. 이쪽 이름으로.<br><br>다섯째를 다시 셌다. 이쪽이었다. 이쪽 그림자가 둘이다. 하나는 문 쪽, 하나는 안쪽.<br><br>안쪽 그림자를 밟고 문을 나섰다. 그림자가 발에서 떨어지지 않는다. 밖에서 해가 들자 그림자가 하나로 겹쳤다. 조금 진했다.`,
      win:{ exp:22, dream:4 }, lose:{ mind:-20, spirit:-24 } },
    { l:'② 다섯을 먼저 내보내고 혼자 남아 다시 센다.', k:'bond', dc:22,
      ok:`동료 넷을 먼저 문 밖으로 내보냈다. 하나씩 어깨를 짚으며. 넷. 이쪽까지 다섯. 문 안에 이쪽 혼자 남았다.<br><br>그림자가 둘이다. 이쪽 것과 하나 더. 그 하나가 이쪽 옆에 서서 문을 본다. 나가고 싶은 모양이다.<br><br>이쪽이 문을 넘었다. 문을 닫기 전에 안을 봤다. 그림자 하나가 등불 곁에 앉아 있다. 들어갈 때 센 수에 없던 것이다. 그걸 두고 문을 닫았다. 셈이 맞았다.`,
      ng:`넷을 내보냈다. 혼자 남아 셌다. 그림자가 셋이다. 이쪽 것, 둘 더.<br><br>둘이 이쪽 양팔을 잡는다. 같이 남자고. 셈이 안 맞으니 다시 들어가야 한다고. 땅 밑 규칙을 아는 것이다.<br><br>뿌리치고 문을 넘었다. 양팔에 그림자 손자국이 남았다. 밖에서 보면 아무것도 없다. 그런데 팔이 무겁다. 셈이 안 맞은 채 끝났다.`,
      win:{ exp:18, dream:3, spirit:6 }, lose:{ hp:-22, spirit:-24 } }
  ] }

]);
